{"content": "package main

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"time"
)

func main() {
	// Test 1: Original bug reproduction with -failfast
	fmt.Println("=== Test 1: Original Bug with -failfast ===")
	testOriginalBug()

	// Test 2: Without -failfast should still work
	fmt.Println("\n=== Test 2: Without -failfast (baseline) ===")
	testWithoutFailfast()

	// Test 3: All tests pass with -failfast and TearDownSuite
	fmt.Println("\n=== Test 3: All tests pass with -failfast ===")
	testAllPass()

	fmt.Println("\n=== All edge case tests completed successfully! ===")
}

func testOriginalBug() {
	testContent := `package testsuite

import (
	"fmt"
	"testing"
	"github.com/stretchr/testify/suite"
)

type TestSuite struct {
	suite.Suite
}

func (ts *TestSuite) TestA() {
	ts.Require().True(false) // This will fail
}

func (ts *TestSuite) TestB() {
	ts.Require().True(true)
}

func (ts *TestSuite) TearDownSuite() {
	fmt.Println("TearDownSuite called")
}

func TestTestSuite(t *testing.T) {
	suite.Run(t, new(TestSuite))
}
`

	writeAndRunTest("test1.go", testContent, []string{"-failfast"})
}

func testWithoutFailfast() {
	testContent := `package testsuite

import (
	"fmt"
	"testing"
	"github.com/stretchr/testify/suite"
)

type TestSuite struct {
	suite.Suite
}

func (ts *TestSuite) TestA() {
	ts.Require().True(false) // This will fail
}

func (ts *TestSuite) TestB() {
	ts.Require().True(true)
}

func (ts *TestSuite) TearDownSuite() {
	fmt.Println("TearDownSuite called")
}

func TestTestSuite(t *testing.T) {
	suite.Run(t, new(TestSuite))
}
`

	writeAndRunTest("test2.go", testContent, []string{})
}

func testAllPass() {
	testContent := `package testsuite

import (
	"fmt"
	"testing"
	"github.com/stretchr/testify/suite"
)

type TestSuite struct {
	suite.Suite
}

func (ts *TestSuite) TestA() {
	ts.Require().True(true) // This will pass
}

func (ts *TestSuite) TestB() {
	ts.Require().True(true) // This will pass
}

func (ts *TestSuite) TearDownSuite() {
	fmt.Println("TearDownSuite called")
}

func TestTestSuite(t *testing.T) {
	suite.Run(t, new(TestSuite))
}
`

	writeAndRunTest("test3.go", testContent, []string{"-failfast"})
}

func writeAndRunTest(filename, content string, args []string) {
	err := os.WriteFile(filename, []byte(content), 0644)
	if err != nil {
		fmt.Printf("Error writing test file %s: %v\n", filename, err)
		return
	}
	defer os.Remove(filename)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	cmdArgs := []string{"test"}
	cmdArgs = append(cmdArgs, args...)
	cmdArgs = append(cmdArgs, filename)

	cmd := exec.CommandContext(ctx, "go", cmdArgs...)
	cmd.Dir = "/workspace/testify"

	output, err := cmd.CombinedOutput()

	if ctx.Err() == context.DeadlineExceeded {
		fmt.Printf("TIMEOUT: Test %s got stuck!\n", filename)
	} else {
		fmt.Printf("Test %s completed successfully. Output:\n%s\n", filename, output)
		if err != nil {
			fmt.Printf("Exit code indicates test failure (expected for failing tests): %v\n", err)
		}
	}
}
