   112→// mutateObject iterates over the given rendered secret data and calls the given mutator for each of them. It marshals
   113→// the objects back (with stable key ordering) after mutation and updates the secret data.
   114→func mutateObjects(secretData map[string][]byte, mutate func(obj *unstructured.Unstructured) error) error {
   115→	for key, data := range secretData {
   116→		buffer := &bytes.Buffer{}
   117→		manifestReader := kubernetes.NewManifestReader(data)
   118→
   119→		for {
   120→			_, _ = buffer.WriteString("\n---\n")
   121→			obj, err := manifestReader.Read()
   122→			if err == io.EOF {
   123→				break
   124→			}
   125→			if err != nil {
   126→				return err
   127→			}
   128→			if obj == nil {
   129→				continue
   130→			}
   131→
   132→			if err := mutate(obj); err != nil {
   133→				return err
   134→			}
   135→
   136→			// serialize unstructured back to secret data (with stable key ordering)
