    35→// InitializeSecretsManagement initializes the secrets management and deploys the required secrets to the shoot
    36→// namespace in the seed.
    37→func (b *Botanist) InitializeSecretsManagement(ctx context.Context) error {
    38→	// Generally, the existing secrets in the shoot namespace in the seeds are the source of truth for the secret
    39→	// manager. Hence, if we restore a shoot control plane then let's fetch the existing data from the ShootState and
    40→	// create corresponding secrets in the shoot namespace in the seed before initializing it. Note that this is
    41→	// explicitly only done in case of restoration to prevent split-brain situations as described in
    42→	// https://github.com/gardener/gardener/issues/5377.
    43→	if b.IsRestorePhase() {
    44→		if err := b.restoreSecretsFromShootStateForSecretsManagerAdoption(ctx); err != nil {
    45→			return err
    46→		}
    47→	}
    48→
    49→	taskFns := []flow.TaskFn{
    50→		b.generateCertificateAuthorities,
    51→		b.generateGenericTokenKubeconfig,
    52→		b.reconcileWildcardIngressCertificate,
    53→	}
    54→
    55→	if v1beta1helper.ShootEnablesSSHAccess(b.Shoot.GetInfo()) {
    56→		taskFns = append(taskFns, b.generateSSHKeypair)
    57→	} else {
    58→		taskFns = append(taskFns, b.deleteSSHKeypair)
    59→	}
    60→
    61→	if b.WantsObservabilityComponents() {
    62→		taskFns = append(taskFns, b.generateObservabilityIngressPassword)
    63→	} else {
    64→		taskFns = append(taskFns, b.deleteObservabilityIngressPassword)
    65→	}
    66→
    67→	return flow.Sequential(taskFns...)(ctx)
    68→}
