   114→func (b *Botanist) restoreSecretsFromShootStateForSecretsManagerAdoption(ctx context.Context) error {
   115→	var fns []flow.TaskFn
   116→
   117→	for _, v := range b.Shoot.GetShootState().Spec.Gardener {
   118→		entry := v
   119→
   120→		if entry.Labels[secretsmanager.LabelKeyManagedBy] != secretsmanager.LabelValueSecretsManager ||
   121→			entry.Type != v1beta1constants.DataTypeSecret {
   122→			continue
   123→		}
   124→
   125→		fns = append(fns, func(ctx context.Context) error {
   126→			objectMeta := metav1.ObjectMeta{
   127→				Name:      entry.Name,
   128→				Namespace: b.Shoot.SeedNamespace,
   129→				Labels:    entry.Labels,
   130→			}
   131→
   132→			data := make(map[string][]byte)
   133→			if err := json.Unmarshal(entry.Data.Raw, &data); err != nil {
   134→				return err
   135→			}
   136→
   137→			secret := secretsmanager.Secret(objectMeta, data)
   138→			return client.IgnoreAlreadyExists(b.SeedClientSet.Client().Create(ctx, secret))
   139→		})
   140→	}
   141→
   142→	return flow.Parallel(fns...)(ctx)
   143→}
