   145→func caCertConfigurations(isWorkerless bool) []secretsutils.ConfigInterface {
   146→	certificateSecretConfigs := []secretsutils.ConfigInterface{
   147→		// The CommonNames for CA certificates will be overridden with the secret name by the secrets manager when
   148→		// generated to ensure that each CA has a unique common name. For backwards-compatibility, we still keep the
   149→		// CommonNames here (if we removed them then new CAs would be generated with the next shoot reconciliation
   150→		// without the end-user to explicitly trigger it).
   151→		&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCACluster, CommonName: "kubernetes", CertType: secretsutils.CACert},
   152→		&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCAClient, CommonName: "kubernetes-client", CertType: secretsutils.CACert},
   153→		&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCAETCD, CommonName: "etcd", CertType: secretsutils.CACert},
   154→		&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCAETCDPeer, CommonName: "etcd-peer", CertType: secretsutils.CACert},
   155→		&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCAFrontProxy, CommonName: "front-proxy", CertType: secretsutils.CACert},
   156→	}
   157→
   158→	if !isWorkerless {
   159→		certificateSecretConfigs = append(certificateSecretConfigs,
   160→			&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCAKubelet, CommonName: "kubelet", CertType: secretsutils.CACert},
   161→			&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCAMetricsServer, CommonName: "metrics-server", CertType: secretsutils.CACert},
   162→			&secretsutils.CertificateSecretConfig{Name: v1beta1constants.SecretNameCAVPN, CommonName: "vpn", CertType: secretsutils.CACert},
   163→		)
   164→	}
   165→
   166→	return certificateSecretConfigs
   167→}
