   169→func (b *Botanist) caCertGenerateOptionsFor(configName string) []secretsmanager.GenerateOption {
   170→	options := []secretsmanager.GenerateOption{
   171→		secretsmanager.Persist(),
   172→		secretsmanager.Rotate(secretsmanager.KeepOld),
   173→	}
   174→
   175→	if v1beta1helper.GetShootCARotationPhase(b.Shoot.GetInfo().Status.Credentials) == gardencorev1beta1.RotationCompleting {
   176→		options = append(options, secretsmanager.IgnoreOldSecrets())
   177→	}
   178→
   179→	if configName == v1beta1constants.SecretNameCAClient {
   180→		return options
   181→	}
   182→
   183→	// For all CAs other than the client CA we ignore the checksum for the CA secret name due to backwards compatibility
   184→	// reasons in case the CA certificate were never rotated yet. With the first rotation we consider the config
   185→	// checksums since we can now assume that all components are able to cater with it (since we only allow triggering
   186→	// CA rotations after we have adapted all components that might rely on the constant CA secret names).
   187→	// The client CA was only introduced late with https://github.com/gardener/gardener/pull/5779, hence nobody was
   188→	// using it and the config checksum could be considered right away.
   189→	if shootStatus := b.Shoot.GetInfo().Status; shootStatus.Credentials == nil ||
   190→		shootStatus.Credentials.Rotation == nil ||
   191→		shootStatus.Credentials.Rotation.CertificateAuthorities == nil {
   192→		options = append(options, secretsmanager.IgnoreConfigChecksumForCASecretName())
   193→	}
   194→
   195→	return options
   196→}
