   198→func (b *Botanist) generateCertificateAuthorities(ctx context.Context) error {
   199→	var caClientSecret *corev1.Secret
   200→
   201→	for _, config := range caCertConfigurations(b.Shoot.IsWorkerless) {
   202→		caSecret, err := b.SecretsManager.Generate(ctx, config, b.caCertGenerateOptionsFor(config.GetName())...)
   203→		if err != nil {
   204→			return err
   205→		}
   206→		if config.GetName() == v1beta1constants.SecretNameCAClient {
   207→			caClientSecret = caSecret.DeepCopy()
   208→		}
   209→	}
   210→
   211→	caBundleSecret, found := b.SecretsManager.Get(v1beta1constants.SecretNameCACluster)
   212→	if !found {
   213→		return fmt.Errorf("secret %q not found", v1beta1constants.SecretNameCACluster)
   214→	}
   215→
   216→	caBundle := caBundleSecret.Data[secretsutils.DataKeyCertificateBundle]
   217→
   218→	if err := b.syncShootConfigMapToGarden(
   219→		ctx,
   220→		gardenerutils.ShootProjectConfigMapSuffixCACluster,
   221→		map[string]string{v1beta1constants.GardenRole: v1beta1constants.GardenRoleCACluster},
   222→		nil,
   223→		map[string]string{secretsutils.DataKeyCertificateCA: string(caBundle)},
   224→	); err != nil {
   225→		return err
   226→	}
   227→
   228→	// TODO(petersutter): Remove this code and cleanup Secret after v1.110 has been released. The caBundle is now being stored in a <shootname>.ca-cluster ConfigMap.
   229→	if err := b.syncShootCredentialToGarden(
   230→		ctx,
   231→		gardenerutils.ShootProjectSecretSuffixCACluster,
   232→		map[string]string{v1beta1constants.GardenRole: v1beta1constants.GardenRoleCACluster},
   233→		nil,
   234→		map[string][]byte{secretsutils.DataKeyCertificateCA: caBundle},
   235→	); err != nil {
   236→		return err
   237→	}
   238→
   239→	return b.syncInternalSecretToGarden(
   240→		ctx,
   241→		gardenerutils.ShootProjectSecretSuffixCAClient,
   242→		map[string]string{v1beta1constants.GardenRole: v1beta1constants.GardenRoleCAClient},
   243→		nil,
   244→		caClientSecret.Data,
   245→	)
   246→}
