   461→func (b *Botanist) DeployCloudProviderSecret(ctx context.Context) error {
   462→	switch credentials := b.Shoot.Credentials.(type) {
   463→	case *securityv1alpha1.WorkloadIdentity:
   464→		shootInfo := b.Shoot.GetInfo()
   465→		shootMeta := securityv1alpha1.ContextObject{
   466→			APIVersion: shootInfo.TypeMeta.GroupVersionKind().GroupVersion().String(),
   467→			Kind:       shootInfo.TypeMeta.Kind,
   468→			Namespace:  ptr.To(shootInfo.ObjectMeta.Namespace),
   469→			Name:       shootInfo.ObjectMeta.Name,
   470→			UID:        shootInfo.ObjectMeta.UID,
   471→		}
   472→
   473→		secret, err := workloadidentity.NewSecret(
   474→			v1beta1constants.SecretNameCloudProvider,
   475→			b.Shoot.SeedNamespace,
   476→			workloadidentity.For(credentials.Name, credentials.Namespace, credentials.Spec.TargetSystem.Type),
   477→			workloadidentity.WithProviderConfig(credentials.Spec.TargetSystem.ProviderConfig),
   478→			workloadidentity.WithContextObject(shootMeta),
   479→			workloadidentity.WithLabels(map[string]string{v1beta1constants.GardenerPurpose: v1beta1constants.SecretNameCloudProvider}),
   480→		)
   481→		if err != nil {
   482→			return err
   483→		}
   484→		return secret.Reconcile(ctx, b.SeedClientSet.Client())
   485→	case *corev1.Secret:
   486→		secret := &corev1.Secret{
   487→			ObjectMeta: metav1.ObjectMeta{
   488→				Name:      v1beta1constants.SecretNameCloudProvider,
   489→				Namespace: b.Shoot.SeedNamespace,
   490→			},
   491→		}
   492→		_, err := controllerutils.GetAndCreateOrMergePatch(ctx, b.SeedClientSet.Client(), secret, func() error {
   493→			secret.Annotations = map[string]string{}
   494→			secret.Labels = map[string]string{
   495→				v1beta1constants.GardenerPurpose: v1beta1constants.SecretNameCloudProvider,
   496→			}
   497→			secret.Type = corev1.SecretTypeOpaque
   498→			secret.Data = credentials.Data
   499→			return nil
   500→		})
   501→		return err
   502→	default:
   503→		return fmt.Errorf("unexpected type %T, should be either Secret or WorkloadIdentity", credentials)
   504→	}
