        } catch (Exception e) {
            System.out.println("✗ FAILED: " + e.getMessage());
            System.exit(1);
        }

        // The "success sql" from the issue
        String goodSql = "SELECT JSON_OBJECT('account','some string') as obj FROM tb_team";
        System.out.println("\nTesting the 'success sql' from the GitHub issue:");
        System.out.println("SQL: " + goodSql);
        try {
