   303→/* Callback for has_attribute.  */
   304→int
   305→c_common_has_attribute (cpp_reader *pfile, bool std_syntax)
   306→{
   307→  int result = 0;
   308→  tree attr_name = NULL_TREE;
   309→  const cpp_token *token;
   310→
   311→  token = get_token_no_padding (pfile);
   312→  if (token->type != CPP_OPEN_PAREN)
   313→    {
   314→      cpp_error (pfile, CPP_DL_ERROR,
   315→		 "missing '(' after \"__has_attribute\"");
   316→      return 0;
   317→    }
   318→  token = get_token_no_padding (pfile);
   319→  if (token->type == CPP_NAME)
   320→    {
   321→      attr_name = get_identifier ((const char *)
   322→				  cpp_token_as_text (pfile, token));
   323→      attr_name = canonicalize_attr_name (attr_name);
   324→      bool have_scope = false;
   325→      int idx = 0;
   326→      const cpp_token *nxt_token;
   327→      do
   328→	nxt_token = cpp_peek_token (pfile, idx++);
   329→      while (nxt_token->type == CPP_PADDING);
   330→      if (nxt_token->type == CPP_SCOPE)
   331→	{
   332→	  have_scope = true;
   333→	  get_token_no_padding (pfile); // Eat scope.
   334→	  nxt_token = get_token_no_padding (pfile);
   335→	  if (nxt_token->type == CPP_NAME)
   336→	    {
   337→	      tree attr_ns = attr_name;
   338→	      tree attr_id
   339→		= get_identifier ((const char *)
   340→				  cpp_token_as_text (pfile, nxt_token));
   341→	      attr_id = canonicalize_attr_name (attr_id);
   342→	      attr_name = build_tree_list (attr_ns, attr_id);
   343→	    }
   344→	  else
   345→	    {
   346→	      cpp_error (pfile, CPP_DL_ERROR,
   347→			 "attribute identifier required after scope");
   348→	      attr_name = NULL_TREE;
   349→	    }
   350→	}
   351→      else
   352→	{
   353→	  /* Some standard attributes need special handling.  */
   354→	  if (c_dialect_cxx ())
   355→	    {
   356→	      if (is_attribute_p ("noreturn", attr_name))
   357→		result = 200809;
   358→	      else if (is_attribute_p ("deprecated", attr_name))
   359→		result = 201309;
   360→	      else if (is_attribute_p ("maybe_unused", attr_name)
   361→		       || is_attribute_p ("fallthrough", attr_name))
   362→		result = 201603;
   363→	      else if (is_attribute_p ("no_unique_address", attr_name)
   364→		       || is_attribute_p ("likely", attr_name)
   365→		       || is_attribute_p ("unlikely", attr_name))
   366→		result = 201803;
   367→	      else if (is_attribute_p ("nodiscard", attr_name))
   368→		result = 201907;
   369→	    }
   370→	  else
   371→	    {
   372→	      if (is_attribute_p ("deprecated", attr_name)
   373→		  || is_attribute_p ("maybe_unused", attr_name)
   374→		  || is_attribute_p ("fallthrough", attr_name))
   375→		result = 201904;
   376→	      else if (is_attribute_p ("nodiscard", attr_name))
   377→		result = 202003;
   378→	    }
   379→	  if (result)
   380→	    attr_name = NULL_TREE;
   381→	}
   382→      if (attr_name && (have_scope || !std_syntax))
   383→	{
   384→	  init_attributes ();
   385→	  const struct attribute_spec *attr = lookup_attribute_spec (attr_name);
   386→	  if (attr)
   387→	    result = 1;
   388→	}
   389→    }
   390→  else
   391→    {
   392→      cpp_error (pfile, CPP_DL_ERROR,
   393→		 "macro \"__has_attribute\" requires an identifier");
   394→      return 0;
   395→    }
   396→
   397→  if (get_token_no_padding (pfile)->type != CPP_CLOSE_PAREN)
   398→    cpp_error (pfile, CPP_DL_ERROR,
   399→	       "missing ')' after \"__has_attribute\"");
   400→
   401→  return result;
   402→}
   403→
   404→/* Callback for has_builtin.  */
   405→
   406→int
   407→c_common_has_builtin (cpp_reader *pfile)
   408→{
   409→  const cpp_token *token = get_token_no_padding (pfile);
   410→  if (token->type != CPP_OPEN_PAREN)
   411→    {
   412→      cpp_error (pfile, CPP_DL_ERROR,
   413→		 "missing '(' after \"__has_builtin\"");
   414→      return 0;
   415→    }
   416→
   417→  const char *name = "";
   418→  token = get_token_no_padding (pfile);
   419→  if (token->type == CPP_NAME)
   420→    {
   421→      name = (const char *) cpp_token_as_text (pfile, token);
   422→      token = get_token_no_padding (pfile);
   423→      if (token->type != CPP_CLOSE_PAREN)
   424→	{
   425→	  cpp_error (pfile, CPP_DL_ERROR,
   426→		     "expected ')' after \"%s\"", name);
   427→	  name = "";
   428→	}
   429→    }
   430→  else
   431→    {
   432→      cpp_error (pfile, CPP_DL_ERROR,
   433→		 "macro \"__has_builtin\" requires an identifier");
   434→      if (token->type == CPP_CLOSE_PAREN)
   435→	return 0;
   436→    }
   437→
   438→  /* Consume tokens up to the closing parenthesis, including any nested
   439→     pairs of parentheses, to avoid confusing redundant errors.  */
   440→  for (unsigned nparen = 1; ; token = get_token_no_padding (pfile))
   441→    {
   442→      if (token->type == CPP_OPEN_PAREN)
   443→	++nparen;
   444→      else if (token->type == CPP_CLOSE_PAREN)
   445→	--nparen;
   446→      else if (token->type == CPP_EOF)
   447→	break;
   448→      if (!nparen)
   449→	break;
   450→    }
   451→
   452→  return names_builtin_p (name);
   453→}
