   456→/* Read a token and return its type.  Fill *VALUE with its value, if
   457→   applicable.  Fill *CPP_FLAGS with the token's flags, if it is
   458→   non-NULL.  */
   459→
   460→enum cpp_ttype
   461→c_lex_with_flags (tree *value, location_t *loc, unsigned char *cpp_flags,
   462→		  int lex_flags)
   463→{
   464→  const cpp_token *tok;
   465→  enum cpp_ttype type;
   466→  unsigned char add_flags = 0;
   467→  enum overflow_type overflow = OT_NONE;
   468→
   469→  timevar_push (TV_CPP);
   470→ retry:
   471→  tok = cpp_get_token_with_location (parse_in, loc);
   472→  type = tok->type;
   473→
   474→ retry_after_at:
   475→  switch (type)
   476→    {
   477→    case CPP_PADDING:
   478→      goto retry;
   479→
   480→    case CPP_NAME:
   481→      *value = HT_IDENT_TO_GCC_IDENT (HT_NODE (tok->val.node.node));
   482→      break;
   483→
   484→    case CPP_NUMBER:
   485→      {
   486→	const char *suffix = NULL;
   487→	unsigned int flags = cpp_classify_number (parse_in, tok, &suffix, *loc);
   488→
   489→	switch (flags & CPP_N_CATEGORY)
   490→	  {
   491→	  case CPP_N_INVALID:
   492→	    /* cpplib has issued an error.  */
   493→	    *value = error_mark_node;
   494→	    break;
   495→
   496→	  case CPP_N_INTEGER:
   497→	    /* C++ uses '0' to mark virtual functions as pure.
   498→	       Set PURE_ZERO to pass this information to the C++ parser.  */
   499→	    if (tok->val.str.len == 1 && *tok->val.str.text == '0')
   500→	      add_flags = PURE_ZERO;
   501→	    *value = interpret_integer (tok, flags, &overflow);
   502→	    break;
   503→
   504→	  case CPP_N_FLOATING:
   505→	    *value = interpret_float (tok, flags, suffix, &overflow);
   506→	    break;
   507→
   508→	  default:
   509→	    gcc_unreachable ();
   510→	  }
   511→
   512→	if (flags & CPP_N_USERDEF)
   513→	  {
   514→	    char *str;
   515→	    tree literal;
   516→	    tree suffix_id = get_identifier (suffix);
   517→	    int len = tok->val.str.len - strlen (suffix);
   518→	    /* If this is going to be used as a C string to pass to a
   519→	       raw literal operator, we need to add a trailing NUL.  */
   520→	    tree num_string = build_string (len + 1,
   521→					    (const char *) tok->val.str.text);
   522→	    TREE_TYPE (num_string) = char_array_type_node;
   523→	    num_string = fix_string_type (num_string);
   524→	    str = CONST_CAST (char *, TREE_STRING_POINTER (num_string));
   525→	    str[len] = '\0';
   526→	    literal = build_userdef_literal (suffix_id, *value, overflow,
   527→					     num_string);
   528→	    *value = literal;
   529→	  }
   530→      }
   531→      break;
   532→
   533→    case CPP_ATSIGN:
   534→      /* An @ may give the next token special significance in Objective-C.  */
   535→      if (c_dialect_objc ())
   536→	{
   537→	  location_t atloc = *loc;
   538→	  location_t newloc;
   539→
   540→	retry_at:
   541→	  tok = cpp_get_token_with_location (parse_in, &newloc);
   542→	  type = tok->type;
   543→	  switch (type)
   544→	    {
   545→	    case CPP_PADDING:
   546→	      goto retry_at;
   547→
   548→	    case CPP_STRING:
   549→	    case CPP_WSTRING:
   550→	    case CPP_STRING16:
   551→	    case CPP_STRING32:
   552→	    case CPP_UTF8STRING:
   553→	      type = lex_string (tok, value, true, true);
   554→	      break;
   555→
   556→	    case CPP_NAME:
   557→	      *value = HT_IDENT_TO_GCC_IDENT (HT_NODE (tok->val.node.node));
   558→	      if (OBJC_IS_AT_KEYWORD (C_RID_CODE (*value))
   559→		  || OBJC_IS_CXX_KEYWORD (C_RID_CODE (*value)))
   560→		{
   561→		  type = CPP_AT_NAME;
   562→		  /* Note the complication: if we found an OBJC_CXX
   563→		     keyword, for example, 'class', we will be
   564→		     returning a token of type CPP_AT_NAME and rid
   565→		     code RID_CLASS (not RID_AT_CLASS).  The language
   566→		     parser needs to convert that to RID_AT_CLASS.
   567→		     However, we've now spliced the '@' together with the
   568→		     keyword that follows; Adjust the location so that we
   569→		     get a source range covering the composite.
   570→		  */
   571→	         *loc = make_location (atloc, atloc, newloc);
   572→		  break;
   573→		}
   574→	      /* FALLTHROUGH */
   575→
   576→	    default:
   577→	      /* ... or not.  */
   578→	      error_at (atloc, "stray %<@%> in program");
   579→	      *loc = newloc;
   580→	      goto retry_after_at;
   581→	    }
   582→	  break;
   583→	}
   584→
   585→      /* FALLTHROUGH */
   586→    case CPP_HASH:
   587→    case CPP_PASTE:
   588→      {
   589→	unsigned char name[8];
   590→
   591→	*cpp_spell_token (parse_in, tok, name, true) = 0;
   592→
   593→	error_at (*loc, "stray %qs in program", name);
   594→      }
   595→
   596→      goto retry;
   597→
   598→    case CPP_OTHER:
   599→      {
   600→	cppchar_t c = tok->val.str.text[0];
   601→
   602→	if (c == '"' || c == '\'')
   603→	  error_at (*loc, "missing terminating %c character", (int) c);
   604→	else if (ISGRAPH (c))
   605→	  error_at (*loc, "stray %qc in program", (int) c);
   606→	else
   607→	  error_at (*loc, "stray %<\\%o%> in program", (int) c);
   608→      }
   609→      goto retry;
   610→
   611→    case CPP_CHAR_USERDEF:
   612→    case CPP_WCHAR_USERDEF:
   613→    case CPP_CHAR16_USERDEF:
   614→    case CPP_CHAR32_USERDEF:
   615→    case CPP_UTF8CHAR_USERDEF:
   616→      {
   617→	tree literal;
   618→	cpp_token temp_tok = *tok;
   619→	const char *suffix = cpp_get_userdef_suffix (tok);
   620→	temp_tok.val.str.len -= strlen (suffix);
   621→	temp_tok.type = cpp_userdef_char_remove_type (type);
   622→	literal = build_userdef_literal (get_identifier (suffix),
   623→					 lex_charconst (&temp_tok),
   624→					 OT_NONE, NULL_TREE);
   625→	*value = literal;
   626→      }
   627→      break;
   628→
   629→    case CPP_CHAR:
   630→    case CPP_WCHAR:
   631→    case CPP_CHAR16:
   632→    case CPP_CHAR32:
   633→    case CPP_UTF8CHAR:
   634→      *value = lex_charconst (tok);
   635→      break;
   636→
   637→    case CPP_STRING_USERDEF:
   638→    case CPP_WSTRING_USERDEF:
   639→    case CPP_STRING16_USERDEF:
   640→    case CPP_STRING32_USERDEF:
   641→    case CPP_UTF8STRING_USERDEF:
   642→      {
   643→	tree literal, string;
   644→	const char *suffix = cpp_get_userdef_suffix (tok);
   645→	string = build_string (tok->val.str.len - strlen (suffix),
   646→			       (const char *) tok->val.str.text);
   647→	literal = build_userdef_literal (get_identifier (suffix),
   648→					 string, OT_NONE, NULL_TREE);
   649→	*value = literal;
   650→      }
   651→      break;
   652→
   653→    case CPP_STRING:
   654→    case CPP_WSTRING:
   655→    case CPP_STRING16:
   656→    case CPP_STRING32:
   657→    case CPP_UTF8STRING:
   658→      if ((lex_flags & C_LEX_STRING_NO_JOIN) == 0)
   659→	{
   660→	  type = lex_string (tok, value, false,
   661→			     (lex_flags & C_LEX_STRING_NO_TRANSLATE) == 0);
   662→	  break;
   663→	}
   664→      *value = build_string (tok->val.str.len, (const char *) tok->val.str.text);
   665→      break;
   666→
   667→    case CPP_PRAGMA:
   668→      *value = build_int_cst (integer_type_node, tok->val.pragma);
   669→      break;
   670→
   671→    case CPP_HEADER_NAME:
   672→      *value = build_string (tok->val.str.len, (const char *)tok->val.str.text);
   673→      break;
   674→
   675→      /* This token should not be visible outside cpplib.  */
   676→    case CPP_MACRO_ARG:
   677→      gcc_unreachable ();
   678→
   679→    /* CPP_COMMENT will appear when compiling with -C.  Ignore, except
   680→       when it is a FALLTHROUGH comment, in that case set
   681→       PREV_FALLTHROUGH flag on the next non-comment token.  */
   682→    case CPP_COMMENT:
   683→      if (tok->flags & PREV_FALLTHROUGH)
   684→	{
   685→	  do
   686→	    {
   687→	      tok = cpp_get_token_with_location (parse_in, loc);
   688→	      type = tok->type;
   689→	    }
   690→	  while (type == CPP_PADDING || type == CPP_COMMENT);
   691→	  add_flags |= PREV_FALLTHROUGH;
   692→	  goto retry_after_at;
   693→	}
   694→       goto retry;
   695→
   696→    default:
   697→      *value = NULL_TREE;
   698→      break;
   699→    }
   700→
   701→  if (cpp_flags)
   702→    *cpp_flags = tok->flags | add_flags;
   703→
   704→  timevar_pop (TV_CPP);
   705→
   706→  return type;
   707→}
