   709→/* Returns the narrowest C-visible unsigned type, starting with the
   710→   minimum specified by FLAGS, that can fit HIGH:LOW, or itk_none if
   711→   there isn't one.  */
   712→
   713→static enum integer_type_kind
   714→narrowest_unsigned_type (const widest_int &val, unsigned int flags)
   715→{
   716→  int itk;
   717→
   718→  if ((flags & CPP_N_WIDTH) == CPP_N_SMALL)
   719→    itk = itk_unsigned_int;
   720→  else if ((flags & CPP_N_WIDTH) == CPP_N_MEDIUM)
   721→    itk = itk_unsigned_long;
   722→  else
   723→    itk = itk_unsigned_long_long;
   724→
   725→  for (; itk < itk_none; itk += 2 /* skip unsigned types */)
   726→    {
   727→      tree upper;
   728→
   729→      if (integer_types[itk] == NULL_TREE)
   730→	continue;
   731→      upper = TYPE_MAX_VALUE (integer_types[itk]);
   732→
   733→      if (wi::geu_p (wi::to_widest (upper), val))
   734→	return (enum integer_type_kind) itk;
   735→    }
   736→
   737→  return itk_none;
   738→}
   739→
   740→/* Ditto, but narrowest signed type.  */
   741→static enum integer_type_kind
   742→narrowest_signed_type (const widest_int &val, unsigned int flags)
   743→{
   744→  int itk;
   745→
   746→  if ((flags & CPP_N_WIDTH) == CPP_N_SMALL)
   747→    itk = itk_int;
   748→  else if ((flags & CPP_N_WIDTH) == CPP_N_MEDIUM)
   749→    itk = itk_long;
   750→  else
   751→    itk = itk_long_long;
   752→
   753→  for (; itk < itk_none; itk += 2 /* skip signed types */)
   754→    {
   755→      tree upper;
   756→
   757→      if (integer_types[itk] == NULL_TREE)
   758→	continue;
   759→      upper = TYPE_MAX_VALUE (integer_types[itk]);
   760→
   761→      if (wi::geu_p (wi::to_widest (upper), val))
   762→	return (enum integer_type_kind) itk;
   763→    }
   764→
   765→  return itk_none;
   766→}
