   768→/* Interpret TOKEN, an integer with FLAGS as classified by cpplib.  */
   769→static tree
   770→interpret_integer (const cpp_token *token, unsigned int flags,
   771→		   enum overflow_type *overflow)
   772→{
   773→  tree value, type;
   774→  enum integer_type_kind itk;
   775→  cpp_num integer;
   776→  HOST_WIDE_INT ival[3];
   777→
   778→  *overflow = OT_NONE;
   779→
   780→  integer = cpp_interpret_integer (parse_in, token, flags);
   781→  if (integer.overflow)
   782→    *overflow = OT_OVERFLOW;
   783→
   784→  ival[0] = integer.low;
   785→  ival[1] = integer.high;
   786→  ival[2] = 0;
   787→  widest_int wval = widest_int::from_array (ival, 3);
   788→
   789→  /* The type of a constant with a U suffix is straightforward.  */
   790→  if (flags & CPP_N_UNSIGNED)
   791→    itk = narrowest_unsigned_type (wval, flags);
   792→  else
   793→    {
   794→      /* The type of a potentially-signed integer constant varies
   795→	 depending on the base it's in, the standard in use, and the
   796→	 length suffixes.  */
   797→      enum integer_type_kind itk_u
   798→	= narrowest_unsigned_type (wval, flags);
   799→      enum integer_type_kind itk_s
   800→	= narrowest_signed_type (wval, flags);
   801→
   802→      /* In both C89 and C99, octal and hex constants may be signed or
   803→	 unsigned, whichever fits tighter.  We do not warn about this
   804→	 choice differing from the traditional choice, as the constant
   805→	 is probably a bit pattern and either way will work.  */
   806→      if ((flags & CPP_N_RADIX) != CPP_N_DECIMAL)
   807→	itk = MIN (itk_u, itk_s);
   808→      else
   809→	{
   810→	  /* In C99, decimal constants are always signed.
   811→	     In C89, decimal constants that don't fit in long have
   812→	     undefined behavior; we try to make them unsigned long.
   813→	     In GCC's extended C89, that last is true of decimal
   814→	     constants that don't fit in long long, too.  */
   815→
   816→	  itk = itk_s;
   817→	  if (itk_s > itk_u && itk_s > itk_long)
   818→	    {
   819→	      if (!flag_isoc99)
   820→		{
   821→		  if (itk_u < itk_unsigned_long)
   822→		    itk_u = itk_unsigned_long;
   823→		  itk = itk_u;
   824→		  warning (0, "this decimal constant is unsigned only in ISO C90");
   825→		}
   826→	      else
   827→		warning (OPT_Wtraditional,
   828→			 "this decimal constant would be unsigned in ISO C90");
   829→	    }
   830→	}
   831→    }
   832→
   833→  if (itk == itk_none)
   834→    /* cpplib has already issued a warning for overflow.  */
   835→    type = ((flags & CPP_N_UNSIGNED)
   836→	    ? widest_unsigned_literal_type_node
   837→	    : widest_integer_literal_type_node);
   838→  else if (flags & CPP_N_SIZE_T)
   839→    {
   840→      /* itk refers to fundamental types not aliased size types.  */
   841→      if (flags & CPP_N_UNSIGNED)
   842→	type = size_type_node;
   843→      else
   844→	type = signed_size_type_node;
   845→    }
   846→  else
   847→    {
   848→      type = integer_types[itk];
   849→      if (itk > itk_unsigned_long
   850→	  && (flags & CPP_N_WIDTH) != CPP_N_LARGE)
   851→	emit_diagnostic
   852→	  ((c_dialect_cxx () ? cxx_dialect == cxx98 : !flag_isoc99)
   853→	   ? DK_PEDWARN : DK_WARNING,
   854→	   input_location, OPT_Wlong_long,
   855→	   (flags & CPP_N_UNSIGNED)
   856→	   ? "integer constant is too large for %<unsigned long%> type"
   857→	   : "integer constant is too large for %<long%> type");
   858→    }
   859→
   860→  value = wide_int_to_tree (type, wval);
   861→
   862→  /* Convert imaginary to a complex type.  */
   863→  if (flags & CPP_N_IMAGINARY)
   864→    value = build_complex (NULL_TREE, build_int_cst (type, 0), value);
   865→
   866→  return value;
   867→}
