   869→/* Interpret TOKEN, a floating point number with FLAGS as classified
   870→   by cpplib.  For C++11 SUFFIX may contain a user-defined literal suffix.  */
   871→static tree
   872→interpret_float (const cpp_token *token, unsigned int flags,
   873→		 const char *suffix, enum overflow_type *overflow)
   874→{
   875→  tree type;
   876→  tree const_type;
   877→  tree value;
   878→  REAL_VALUE_TYPE real;
   879→  REAL_VALUE_TYPE real_trunc;
   880→  char *copy;
   881→  size_t copylen;
   882→
   883→  *overflow = OT_NONE;
   884→
   885→  /* Default (no suffix) depends on whether the FLOAT_CONST_DECIMAL64
   886→     pragma has been used and is either double or _Decimal64.  Types
   887→     that are not allowed with decimal float default to double.  */
   888→  if (flags & CPP_N_DEFAULT)
   889→    {
   890→      flags ^= CPP_N_DEFAULT;
   891→      flags |= CPP_N_MEDIUM;
   892→
   893→      if (((flags & CPP_N_HEX) == 0) && ((flags & CPP_N_IMAGINARY) == 0))
   894→	{
   895→	  warning (OPT_Wunsuffixed_float_constants,
   896→		   "unsuffixed floating constant");
   897→	  if (float_const_decimal64_p ())
   898→	    flags |= CPP_N_DFLOAT;
   899→	}
   900→    }
   901→
   902→  /* Decode _Fract and _Accum.  */
   903→  if (flags & CPP_N_FRACT || flags & CPP_N_ACCUM)
   904→    return interpret_fixed (token, flags);
   905→
   906→  /* Decode type based on width and properties. */
   907→  if (flags & CPP_N_DFLOAT)
   908→    if (!targetm.decimal_float_supported_p ())
   909→      {
   910→	error ("decimal floating-point not supported for this target");
   911→	return error_mark_node;
   912→      }
   913→    else if ((flags & CPP_N_WIDTH) == CPP_N_LARGE)
   914→      type = dfloat128_type_node;
   915→    else if ((flags & CPP_N_WIDTH) == CPP_N_SMALL)
   916→      type = dfloat32_type_node;
   917→    else
   918→      type = dfloat64_type_node;
   919→  else
   920→    if (flags & CPP_N_WIDTH_MD)
   921→      {
   922→	char suffix;
   923→	machine_mode mode;
   924→
   925→	if ((flags & CPP_N_WIDTH_MD) == CPP_N_MD_W)
   926→	  suffix = 'w';
   927→	else
   928→	  suffix = 'q';
   929→
   930→	mode = targetm.c.mode_for_suffix (suffix);
   931→	if (mode == VOIDmode)
   932→	  {
   933→	    error ("unsupported non-standard suffix on floating constant");
   934→
   935→	    return error_mark_node;
   936→	  }
   937→	else
   938→	  pedwarn (input_location, OPT_Wpedantic, "non-standard suffix on floating constant");
   939→
   940→	type = c_common_type_for_mode (mode, 0);
   941→	gcc_assert (type);
   942→      }
   943→    else if ((flags & (CPP_N_FLOATN | CPP_N_FLOATNX)) != 0)
   944→      {
   945→	unsigned int n = (flags & CPP_N_WIDTH_FLOATN_NX) >> CPP_FLOATN_SHIFT;
   946→	bool extended = (flags & CPP_N_FLOATNX) != 0;
   947→	type = NULL_TREE;
   948→	for (int i = 0; i < NUM_FLOATN_NX_TYPES; i++)
   949→	  if (floatn_nx_types[i].n == (int) n
   950→	      && floatn_nx_types[i].extended == extended)
   951→	    {
   952→	      type = FLOATN_NX_TYPE_NODE (i);
   953→	      break;
   954→	    }
   955→	if (type == NULL_TREE)
   956→	  {
   957→	    error ("unsupported non-standard suffix on floating constant");
   958→	    return error_mark_node;
   959→	  }
   960→	else
   961→	  pedwarn (input_location, OPT_Wpedantic, "non-standard suffix on floating constant");
   962→      }
   963→    else if ((flags & CPP_N_WIDTH) == CPP_N_LARGE)
   964→      type = long_double_type_node;
   965→    else if ((flags & CPP_N_WIDTH) == CPP_N_SMALL
   966→	     || flag_single_precision_constant)
   967→      type = float_type_node;
   968→    else
   969→      type = double_type_node;
   970→
   971→  const_type = excess_precision_type (type);
   972→  if (!const_type)
   973→    const_type = type;
   974→
   975→  /* Copy the constant to a nul-terminated buffer.  If the constant
   976→     has any suffixes, cut them off; REAL_VALUE_ATOF/ REAL_VALUE_HTOF
   977→     can't handle them.  */
   978→  copylen = token->val.str.len;
   979→  if (flags & CPP_N_USERDEF)
   980→    copylen -= strlen (suffix);
   981→  else if (flags & CPP_N_DFLOAT)
   982→    copylen -= 2;
   983→  else
   984→    {
   985→      if ((flags & CPP_N_WIDTH) != CPP_N_MEDIUM)
   986→	/* Must be an F or L or machine defined suffix.  */
   987→	copylen--;
   988→      if (flags & CPP_N_IMAGINARY)
   989→	/* I or J suffix.  */
   990→	copylen--;
   991→      if (flags & CPP_N_FLOATNX)
   992→	copylen--;
   993→      if (flags & (CPP_N_FLOATN | CPP_N_FLOATNX))
   994→	{
   995→	  unsigned int n = (flags & CPP_N_WIDTH_FLOATN_NX) >> CPP_FLOATN_SHIFT;
   996→	  while (n > 0)
   997→	    {
   998→	      copylen--;
   999→	      n /= 10;
  1000→	    }
  1001→	}
  1002→    }
  1003→
  1004→  copy = (char *) alloca (copylen + 1);
  1005→  if (cxx_dialect > cxx11)
  1006→    {
  1007→      size_t maxlen = 0;
  1008→      for (size_t i = 0; i < copylen; ++i)
  1009→        if (token->val.str.text[i] != '\'')
  1010→          copy[maxlen++] = token->val.str.text[i];
  1011→      copy[maxlen] = '\0';
  1012→    }
  1013→  else
  1014→    {
  1015→      memcpy (copy, token->val.str.text, copylen);
  1016→      copy[copylen] = '\0';
  1017→    }
  1018→
  1019→  real_from_string3 (&real, copy, TYPE_MODE (const_type));
  1020→  if (const_type != type)
  1021→    /* Diagnosing if the result of converting the value with excess
  1022→       precision to the semantic type would overflow (with associated
  1023→       double rounding) is more appropriate than diagnosing if the
  1024→       result of converting the string directly to the semantic type
  1025→       would overflow.  */
  1026→    real_convert (&real_trunc, TYPE_MODE (type), &real);
  1027→
  1028→  /* Both C and C++ require a diagnostic for a floating constant
  1029→     outside the range of representable values of its type.  Since we
  1030→     have __builtin_inf* to produce an infinity, this is now a
  1031→     mandatory pedwarn if the target does not support infinities.  */
  1032→  if (REAL_VALUE_ISINF (real)
  1033→      || (const_type != type && REAL_VALUE_ISINF (real_trunc)))
  1034→    {
  1035→      *overflow = OT_OVERFLOW;
  1036→      if (!(flags & CPP_N_USERDEF))
  1037→	{
  1038→	  if (!MODE_HAS_INFINITIES (TYPE_MODE (type)))
  1039→	    pedwarn (input_location, 0,
  1040→		     "floating constant exceeds range of %qT", type);
  1041→	  else
  1042→	    warning (OPT_Woverflow,
  1043→		     "floating constant exceeds range of %qT", type);
  1044→	}
  1045→    }
  1046→  /* We also give a warning if the value underflows.  */
  1047→  else if (real_equal (&real, &dconst0)
  1048→	   || (const_type != type
  1049→	       && real_equal (&real_trunc, &dconst0)))
  1050→    {
  1051→      REAL_VALUE_TYPE realvoidmode;
  1052→      int oflow = real_from_string (&realvoidmode, copy);
  1053→      *overflow = (oflow == 0 ? OT_NONE
  1054→			      : (oflow < 0 ? OT_UNDERFLOW : OT_OVERFLOW));
  1055→      if (!(flags & CPP_N_USERDEF))
  1056→	{
  1057→	  if (oflow < 0 || !real_equal (&realvoidmode, &dconst0))
  1058→	    warning (OPT_Woverflow, "floating constant truncated to zero");
  1059→	}
  1060→    }
  1061→
  1062→  /* Create a node with determined type and value.  */
  1063→  value = build_real (const_type, real);
  1064→  if (flags & CPP_N_IMAGINARY)
  1065→    {
  1066→      value = build_complex (NULL_TREE,
  1067→			     fold_convert (const_type,
  1068→					   integer_zero_node), value);
  1069→      if (type != const_type)
  1070→	{
  1071→	  const_type = TREE_TYPE (value);
  1072→	  type = build_complex_type (type);
  1073→	}
  1074→    }
  1075→
  1076→  if (type != const_type)
  1077→    value = build1_loc (token->src_loc, EXCESS_PRECISION_EXPR, type, value);
  1078→
  1079→  return value;
  1080→}
