  1082→/* Interpret TOKEN, a fixed-point number with FLAGS as classified
  1083→   by cpplib.  */
  1084→
  1085→static tree
  1086→interpret_fixed (const cpp_token *token, unsigned int flags)
  1087→{
  1088→  tree type;
  1089→  tree value;
  1090→  FIXED_VALUE_TYPE fixed;
  1091→  char *copy;
  1092→  size_t copylen;
  1093→
  1094→  copylen = token->val.str.len;
  1095→
  1096→  if (flags & CPP_N_FRACT) /* _Fract.  */
  1097→    {
  1098→      if (flags & CPP_N_UNSIGNED) /* Unsigned _Fract.  */
  1099→	{
  1100→	  if ((flags & CPP_N_WIDTH) == CPP_N_LARGE)
  1101→	    {
  1102→	      type = unsigned_long_long_fract_type_node;
  1103→	      copylen -= 4;
  1104→	    }
  1105→	  else if ((flags & CPP_N_WIDTH) == CPP_N_MEDIUM)
  1106→	    {
  1107→	      type = unsigned_long_fract_type_node;
  1108→	      copylen -= 3;
  1109→	    }
  1110→	  else if ((flags & CPP_N_WIDTH) == CPP_N_SMALL)
  1111→	    {
  1112→	      type = unsigned_short_fract_type_node;
  1113→	      copylen -= 3;
  1114→	    }
  1115→          else
  1116→	    {
  1117→	      type = unsigned_fract_type_node;
  1118→	      copylen -= 2;
  1119→	    }
  1120→	}
  1121→      else /* Signed _Fract.  */
  1122→	{
  1123→	  if ((flags & CPP_N_WIDTH) == CPP_N_LARGE)
  1124→	    {
  1125→	      type = long_long_fract_type_node;
  1126→	      copylen -= 3;
  1127→	    }
  1128→	  else if ((flags & CPP_N_WIDTH) == CPP_N_MEDIUM)
  1129→	    {
  1130→	      type = long_fract_type_node;
  1131→	      copylen -= 2;
  1132→	    }
  1133→	  else if ((flags & CPP_N_WIDTH) == CPP_N_SMALL)
  1134→	    {
  1135→	      type = short_fract_type_node;
  1136→	      copylen -= 2;
  1137→	    }
  1138→          else
  1139→	    {
  1140→	      type = fract_type_node;
  1141→	      copylen --;
  1142→	    }
  1143→	  }
  1144→    }
  1145→  else /* _Accum.  */
  1146→    {
  1147→      if (flags & CPP_N_UNSIGNED) /* Unsigned _Accum.  */
  1148→	{
  1149→	  if ((flags & CPP_N_WIDTH) == CPP_N_LARGE)
  1150→	    {
  1151→	      type = unsigned_long_long_accum_type_node;
  1152→	      copylen -= 4;
  1153→	    }
  1154→	  else if ((flags & CPP_N_WIDTH) == CPP_N_MEDIUM)
  1155→	    {
  1156→	      type = unsigned_long_accum_type_node;
  1157→	      copylen -= 3;
  1158→	    }
  1159→	  else if ((flags & CPP_N_WIDTH) == CPP_N_SMALL)
  1160→	    {
  1161→	      type = unsigned_short_accum_type_node;
  1162→	      copylen -= 3;
  1163→	     }
  1164→	  else
  1165→	    {
  1166→	      type = unsigned_accum_type_node;
