  1252→    {
  1253→    case CPP_PADDING:
  1254→      goto retry;
  1255→    case CPP_ATSIGN:
  1256→      if (objc_string)
  1257→	{
  1258→	  if (objc_at_sign_was_seen)
  1259→	    error ("repeated %<@%> before Objective-C string");
  1260→
  1261→	  objc_at_sign_was_seen = true;
  1262→	  goto retry;
  1263→	}
  1264→      /* FALLTHROUGH */
  1265→
  1266→    default:
  1267→      break;
  1268→
  1269→    case CPP_WSTRING:
  1270→    case CPP_STRING16:
  1271→    case CPP_STRING32:
  1272→    case CPP_UTF8STRING:
