  1288→	  obstack_grow (&loc_ob, &init_loc, sizeof (location_t));
  1289→	}
  1290→
  1291→      concats++;
  1292→      obstack_grow (&str_ob, &tok->val.str, sizeof (cpp_string));
  1293→      obstack_grow (&loc_ob, &tok->src_loc, sizeof (location_t));
