  1340→	  break;
  1341→	case CPP_STRING16:
  1342→	  value = build_string (TYPE_PRECISION (char16_type_node)
  1343→				/ TYPE_PRECISION (char_type_node),
  1344→				"\0");  /* char16_t is 16 bits */
  1345→	  break;
  1346→	case CPP_STRING32:
  1347→	  value = build_string (TYPE_PRECISION (char32_type_node)
  1348→				/ TYPE_PRECISION (char_type_node),
  1349→				"\0\0\0");  /* char32_t is 32 bits */
  1350→	  break;
  1351→	case CPP_WSTRING:
  1352→	  value = build_string (TYPE_PRECISION (wchar_type_node)
  1353→				/ TYPE_PRECISION (char_type_node),
  1354→				"\0\0\0");  /* widest supported wchar_t
  1355→					       is 32 bits */
  1356→	  break;
  1357→        }
  1358→    }
  1359→
  1360→  switch (type)
  1361→    {
  1362→    default:
  1363→    case CPP_STRING:
  1364→      TREE_TYPE (value) = char_array_type_node;
  1365→      break;
  1366→    case CPP_UTF8STRING:
  1367→      if (flag_char8_t)
  1368→        TREE_TYPE (value) = char8_array_type_node;
  1369→      else
  1370→        TREE_TYPE (value) = char_array_type_node;
  1371→      break;
  1372→    case CPP_STRING16:
  1373→      TREE_TYPE (value) = char16_array_type_node;
  1374→      break;
  1375→    case CPP_STRING32:
  1376→      TREE_TYPE (value) = char32_array_type_node;
  1377→      break;
  1378→    case CPP_WSTRING:
  1379→      TREE_TYPE (value) = wchar_array_type_node;
  1380→    }
