  1392→/* Converts a (possibly wide) character constant token into a tree.  */
  1393→static tree
  1394→lex_charconst (const cpp_token *token)
  1395→{
  1396→  cppchar_t result;
  1397→  tree type, value;
  1398→  unsigned int chars_seen;
  1399→  int unsignedp = 0;
  1400→
  1401→  result = cpp_interpret_charconst (parse_in, token,
  1402→				    &chars_seen, &unsignedp);
  1403→
  1404→  if (token->type == CPP_WCHAR)
  1405→    type = wchar_type_node;
  1406→  else if (token->type == CPP_CHAR32)
  1407→    type = char32_type_node;
  1408→  else if (token->type == CPP_CHAR16)
  1409→    type = char16_type_node;
  1410→  else if (token->type == CPP_UTF8CHAR)
  1411→    {
  1412→      if (!c_dialect_cxx ())
  1413→	type = unsigned_char_type_node;
  1414→      else if (flag_char8_t)
  1415→        type = char8_type_node;
  1416→      else
  1417→        type = char_type_node;
  1418→    }
  1419→  /* In C, a character constant has type 'int'.
  1420→     In C++ 'char', but multi-char charconsts have type 'int'.  */
  1421→  else if (!c_dialect_cxx () || chars_seen > 1)
  1422→    type = integer_type_node;
  1423→  else
  1424→    type = char_type_node;
  1425→
  1426→  /* Cast to cppchar_signed_t to get correct sign-extension of RESULT
  1427→     before possibly widening to HOST_WIDE_INT for build_int_cst.  */
  1428→  if (unsignedp || (cppchar_signed_t) result >= 0)
  1429→    value = build_int_cst (type, result);
  1430→  else
  1431→    value = build_int_cst (type, (cppchar_signed_t) result);
  1432→
  1433→  return value;
  1434→}
