    93→// processClientSideListener checks if the provided Listener proto meets
    94→// the expected criteria. If so, it returns a non-empty routeConfigName.
    95→func processClientSideListener(lis *v3listenerpb.Listener, logger *grpclog.PrefixLogger, v2 bool) (*ListenerUpdate, error) {
    96→	update := &ListenerUpdate{}
    97→
    98→	apiLisAny := lis.GetApiListener().GetApiListener()
    99→	if !IsHTTPConnManagerResource(apiLisAny.GetTypeUrl()) {
   100→		return nil, fmt.Errorf("unexpected resource type: %q", apiLisAny.GetTypeUrl())
   101→	}
   102→	apiLis := &v3httppb.HttpConnectionManager{}
   103→	if err := proto.Unmarshal(apiLisAny.GetValue(), apiLis); err != nil {
   104→		return nil, fmt.Errorf("failed to unmarshal api_listner: %v", err)
   105→	}
   106→
   107→	switch apiLis.RouteSpecifier.(type) {
   108→	case *v3httppb.HttpConnectionManager_Rds:
   109→		if apiLis.GetRds().GetConfigSource().GetAds() == nil {
   110→			return nil, fmt.Errorf("ConfigSource is not ADS: %+v", lis)
   111→		}
   112→		name := apiLis.GetRds().GetRouteConfigName()
   113→		if name == "" {
   114→			return nil, fmt.Errorf("empty route_config_name: %+v", lis)
   115→		}
   116→		update.RouteConfigName = name
   117→	case *v3httppb.HttpConnectionManager_RouteConfig:
   118→		routeU, err := generateRDSUpdateFromRouteConfiguration(apiLis.GetRouteConfig(), logger, v2)
   119→		if err != nil {
   120→			return nil, fmt.Errorf("failed to parse inline RDS resp: %v", err)
   121→		}
   122→		update.InlineRouteConfig = &routeU
   123→	case nil:
   124→		return nil, fmt.Errorf("no RouteSpecifier: %+v", apiLis)
   125→	default:
   126→		return nil, fmt.Errorf("unsupported type %T for RouteSpecifier", apiLis.RouteSpecifier)
   127→	}
   128→
   129→	if v2 {
   130→		return update, nil
   131→	}
   132→
   133→	// The following checks and fields only apply to xDS protocol versions v3+.
   134→
   135→	update.MaxStreamDuration = apiLis.GetCommonHttpProtocolOptions().GetMaxStreamDuration().AsDuration()
   136→
   137→	var err error
   138→	if update.HTTPFilters, err = processHTTPFilters(apiLis.GetHttpFilters(), false); err != nil {
   139→		return nil, err
   140→	}
   141→
   142→	return update, nil
   143→}
