   145→func unwrapHTTPFilterConfig(config *anypb.Any) (proto.Message, string, error) {
   146→	// The real type name is inside the TypedStruct.
   147→	s := new(v1typepb.TypedStruct)
   148→	if !ptypes.Is(config, s) {
   149→		return config, config.GetTypeUrl(), nil
   150→	}
   151→	if err := ptypes.UnmarshalAny(config, s); err != nil {
   152→		return nil, "", fmt.Errorf("error unmarshalling TypedStruct filter config: %v", err)
   153→	}
   154→	return s, s.GetTypeUrl(), nil
   155→}
   156→
   157→func validateHTTPFilterConfig(cfg *anypb.Any, lds, optional bool) (httpfilter.Filter, httpfilter.FilterConfig, error) {
   158→	config, typeURL, err := unwrapHTTPFilterConfig(cfg)
   159→	if err != nil {
   160→		return nil, nil, err
   161→	}
   162→	filterBuilder := httpfilter.Get(typeURL)
   163→	if filterBuilder == nil {
   164→		if optional {
   165→			return nil, nil, nil
   166→		}
   167→		return nil, nil, fmt.Errorf("no filter implementation found for %q", typeURL)
   168→	}
   169→	parseFunc := filterBuilder.ParseFilterConfig
   170→	if !lds {
   171→		parseFunc = filterBuilder.ParseFilterConfigOverride
   172→	}
   173→	filterConfig, err := parseFunc(config)
   174→	if err != nil {
   175→		return nil, nil, fmt.Errorf("error parsing config for filter %q: %v", typeURL, err)
   176→	}
   177→	return filterBuilder, filterConfig, nil
   178→}
   179→
   180→func processHTTPFilterOverrides(cfgs map[string]*anypb.Any) (map[string]httpfilter.FilterConfig, error) {
   181→	if !env.FaultInjectionSupport || len(cfgs) == 0 {
   182→		return nil, nil
   183→	}
   184→	m := make(map[string]httpfilter.FilterConfig)
   185→	for name, cfg := range cfgs {
   186→		optional := false
   187→		s := new(v3routepb.FilterConfig)
   188→		if ptypes.Is(cfg, s) {
   189→			if err := ptypes.UnmarshalAny(cfg, s); err != nil {
   190→				return nil, fmt.Errorf("filter override %q: error unmarshalling FilterConfig: %v", name, err)
   191→			}
   192→			cfg = s.GetConfig()
   193→			optional = s.GetIsOptional()
   194→		}
   195→
   196→		httpFilter, config, err := validateHTTPFilterConfig(cfg, false, optional)
   197→		if err != nil {
   198→			return nil, fmt.Errorf("filter override %q: %v", name, err)
   199→		}
   200→		if httpFilter == nil {
   201→			// Optional configs are ignored.
   202→			continue
   203→		}
   204→		m[name] = config
   205→	}
   206→	return m, nil
   207→}
   208→
   209→func processHTTPFilters(filters []*v3httppb.HttpFilter, server bool) ([]HTTPFilter, error) {
   210→	if !env.FaultInjectionSupport {
   211→		return nil, nil
   212→	}
   213→
   214→	ret := make([]HTTPFilter, 0, len(filters))
   215→	seenNames := make(map[string]bool, len(filters))
   216→	for _, filter := range filters {
   217→		name := filter.GetName()
   218→		if name == "" {
   219→			return nil, errors.New("filter missing name field")
   220→		}
   221→		if seenNames[name] {
   222→			return nil, fmt.Errorf("duplicate filter name %q", name)
   223→		}
   224→		seenNames[name] = true
   225→
   226→		httpFilter, config, err := validateHTTPFilterConfig(filter.GetTypedConfig(), true, filter.GetIsOptional())
   227→		if err != nil {
   228→			return nil, err
   229→		}
   230→		if httpFilter == nil {
   231→			// Optional configs are ignored.
   232→			continue
   233→		}
   234→		if server {
   235→			if _, ok := httpFilter.(httpfilter.ServerInterceptorBuilder); !ok {
   236→				if filter.GetIsOptional() {
   237→					continue
   238→				}
   239→				return nil, fmt.Errorf("HTTP filter %q not supported server-side", name)
   240→			}
   241→		} else if _, ok := httpFilter.(httpfilter.ClientInterceptorBuilder); !ok {
   242→			if filter.GetIsOptional() {
   243→				continue
   244→			}
   245→			return nil, fmt.Errorf("HTTP filter %q not supported client-side", name)
   246→		}
   247→
   248→		// Save name/config
   249→		ret = append(ret, HTTPFilter{Name: name, Filter: httpFilter, Config: config})
   250→	}
   251→	return ret, nil
   252→}
