   254→func processServerSideListener(lis *v3listenerpb.Listener) (*ListenerUpdate, error) {
   255→	if n := len(lis.ListenerFilters); n != 0 {
   256→		return nil, fmt.Errorf("unsupported field 'listener_filters' contains %d entries", n)
   257→	}
   258→	if useOrigDst := lis.GetUseOriginalDst(); useOrigDst != nil && useOrigDst.GetValue() {
   259→		return nil, errors.New("unsupported field 'use_original_dst' is present and set to true")
   260→	}
   261→	addr := lis.GetAddress()
   262→	if addr == nil {
   263→		return nil, fmt.Errorf("no address field in LDS response: %+v", lis)
   264→	}
   265→	sockAddr := addr.GetSocketAddress()
   266→	if sockAddr == nil {
   267→		return nil, fmt.Errorf("no socket_address field in LDS response: %+v", lis)
   268→	}
   269→	lu := &ListenerUpdate{
   270→		InboundListenerCfg: &InboundListenerConfig{
   271→			Address: sockAddr.GetAddress(),
   272→			Port:    strconv.Itoa(int(sockAddr.GetPortValue())),
   273→		},
   274→	}
   275→	chains := lis.GetFilterChains()
   276→	if def := lis.GetDefaultFilterChain(); def != nil {
   277→		chains = append(chains, def)
   278→	}
   279→	if err := validateNetworkFilterChains(chains); err != nil {
   280→		return nil, err
   281→	}
   282→
   283→	fcMgr, err := NewFilterChainManager(lis)
   284→	if err != nil {
   285→		return nil, err
   286→	}
   287→	lu.InboundListenerCfg.FilterChains = fcMgr
   288→	return lu, nil
   289→}
   290→
   291→func validateNetworkFilterChains(filterChains []*v3listenerpb.FilterChain) error {
   292→	for _, filterChain := range filterChains {
   293→		seenNames := make(map[string]bool, len(filterChain.GetFilters()))
   294→		seenHCM := false
   295→		for _, filter := range filterChain.GetFilters() {
   296→			name := filter.GetName()
   297→			if name == "" {
   298→				return fmt.Errorf("filter chain {%+v} is missing name field in filter: {%+v}", filterChain, filter)
   299→			}
   300→			if seenNames[name] {
   301→				return fmt.Errorf("filter chain {%+v} has duplicate filter name %q", filterChain, name)
   302→			}
   303→			seenNames[name] = true
   304→
   305→			// Network filters have a oneof field named `config_type` where we
   306→			// only support `TypedConfig` variant.
   307→			switch typ := filter.GetConfigType().(type) {
   308→			case *v3listenerpb.Filter_TypedConfig:
   309→				// The typed_config field has an `anypb.Any` proto which could
   310→				// directly contain the serialized bytes of the actual filter
   311→				// configuration, or it could be encoded as a `TypedStruct`.
   312→				// TODO: Add support for `TypedStruct`.
   313→				tc := filter.GetTypedConfig()
   314→
   315→				// The only network filter that we currently support is the v3
   316→				// HttpConnectionManager. So, we can directly check the type_url
   317→				// and unmarshal the config.
   318→				// TODO: Implement a registry of supported network filters (like
   319→				// we have for HTTP filters), when we have to support network
   320→				// filters other than HttpConnectionManager.
   321→				if tc.GetTypeUrl() != version.V3HTTPConnManagerURL {
   322→					return fmt.Errorf("filter chain {%+v} has unsupported network filter %q in filter {%+v}", filterChain, tc.GetTypeUrl(), filter)
   323→				}
   324→				hcm := &v3httppb.HttpConnectionManager{}
   325→				if err := ptypes.UnmarshalAny(tc, hcm); err != nil {
   326→					return fmt.Errorf("filter chain {%+v} failed unmarshaling of network filter {%+v}: %v", filterChain, filter, err)
   327→				}
   328→				// We currently don't support HTTP filters on the server-side.
   329→				// We will be adding support for it in the future. So, we want
   330→				// to make sure that the http_filters configuration is valid.
   331→				if _, err := processHTTPFilters(hcm.GetHttpFilters(), true); err != nil {
   332→					return err
   333→				}
   334→				seenHCM = true
   335→			default:
   336→				return fmt.Errorf("filter chain {%+v} has unsupported config_type %T in filter %s", filterChain, typ, filter.GetName())
   337→			}
   338→		}
   339→		if !seenHCM {
   340→			return fmt.Errorf("filter chain {%+v} missing HttpConnectionManager filter", filterChain)
   341→		}
   342→	}
   343→	return nil
   344→}
