   356→func unmarshalRouteConfigResource(r *anypb.Any, logger *grpclog.PrefixLogger) (string, RouteConfigUpdate, error) {
   357→	if !IsRouteConfigResource(r.GetTypeUrl()) {
   358→		return "", RouteConfigUpdate{}, fmt.Errorf("unexpected resource type: %q ", r.GetTypeUrl())
   359→	}
   360→	rc := &v3routepb.RouteConfiguration{}
   361→	if err := proto.Unmarshal(r.GetValue(), rc); err != nil {
   362→		return "", RouteConfigUpdate{}, fmt.Errorf("failed to unmarshal resource: %v", err)
   363→	}
   364→	logger.Infof("Resource with name: %v, type: %T, contains: %v.", rc.GetName(), rc, pretty.ToJSON(rc))
   365→
   366→	// TODO: Pass version.TransportAPI instead of relying upon the type URL
   367→	v2 := r.GetTypeUrl() == version.V2RouteConfigURL
   368→	u, err := generateRDSUpdateFromRouteConfiguration(rc, logger, v2)
   369→	if err != nil {
