   375→
   376→// generateRDSUpdateFromRouteConfiguration checks if the provided
   377→// RouteConfiguration meets the expected criteria. If so, it returns a
   378→// RouteConfigUpdate with nil error.
   379→//
   380→// A RouteConfiguration resource is considered valid when only if it contains a
   381→// VirtualHost whose domain field matches the server name from the URI passed
   382→// to the gRPC channel, and it contains a clusterName or a weighted cluster.
   383→//
   384→// The RouteConfiguration includes a list of VirtualHosts, which may have zero
   385→// or more elements. We are interested in the element whose domains field
   386→// matches the server name specified in the "xds:" URI. The only field in the
   387→// VirtualHost proto that the we are interested in is the list of routes. We
   388→// only look at the last route in the list (the default route), whose match
   389→// field must be empty and whose route field must be set.  Inside that route
   390→// message, the cluster field will contain the clusterName or weighted clusters
   391→// we are looking for.
   392→func generateRDSUpdateFromRouteConfiguration(rc *v3routepb.RouteConfiguration, logger *grpclog.PrefixLogger, v2 bool) (RouteConfigUpdate, error) {
   393→	var vhs []*VirtualHost
   394→	for _, vh := range rc.GetVirtualHosts() {
   395→		routes, err := routesProtoToSlice(vh.Routes, logger, v2)
   396→		if err != nil {
   397→			return RouteConfigUpdate{}, fmt.Errorf("received route is invalid: %v", err)
   398→		}
   399→		vhOut := &VirtualHost{
   400→			Domains: vh.GetDomains(),
   401→			Routes:  routes,
   402→		}
   403→		if !v2 {
   404→			cfgs, err := processHTTPFilterOverrides(vh.GetTypedPerFilterConfig())
   405→			if err != nil {
   406→				return RouteConfigUpdate{}, fmt.Errorf("virtual host %+v: %v", vh, err)
   407→			}
   408→			vhOut.HTTPFilterConfigOverride = cfgs
   409→		}
   410→		vhs = append(vhs, vhOut)
   411→	}
   412→	return RouteConfigUpdate{VirtualHosts: vhs}, nil
   413→}
   414→
   415→func routesProtoToSlice(routes []*v3routepb.Route, logger *grpclog.PrefixLogger, v2 bool) ([]*Route, error) {
   416→	var routesRet []*Route
   417→
   418→	for _, r := range routes {
   419→		match := r.GetMatch()
   420→		if match == nil {
   421→			return nil, fmt.Errorf("route %+v doesn't have a match", r)
   422→		}
   423→
   424→		if len(match.GetQueryParameters()) != 0 {
   425→			// Ignore route with query parameters.
   426→			logger.Warningf("route %+v has query parameter matchers, the route will be ignored", r)
   427→			continue
   428→		}
   429→
   430→		pathSp := match.GetPathSpecifier()
   431→		if pathSp == nil {
   432→			return nil, fmt.Errorf("route %+v doesn't have a path specifier", r)
   433→		}
   434→
   435→		var route Route
   436→		switch pt := pathSp.(type) {
   437→		case *v3routepb.RouteMatch_Prefix:
   438→			route.Prefix = &pt.Prefix
   439→		case *v3routepb.RouteMatch_Path:
   440→			route.Path = &pt.Path
   441→		case *v3routepb.RouteMatch_SafeRegex:
   442→			regex := pt.SafeRegex.GetRegex()
   443→			re, err := regexp.Compile(regex)
   444→			if err != nil {
   445→				return nil, fmt.Errorf("route %+v contains an invalid regex %q", r, regex)
   446→			}
   447→			route.Regex = re
   448→		default:
   449→			return nil, fmt.Errorf("route %+v has an unrecognized path specifier: %+v", r, pt)
   450→		}
   451→
   452→		if caseSensitive := match.GetCaseSensitive(); caseSensitive != nil {
   453→			route.CaseInsensitive = !caseSensitive.Value
   454→		}
   455→
   456→		for _, h := range match.GetHeaders() {
   457→			var header HeaderMatcher
   458→			switch ht := h.GetHeaderMatchSpecifier().(type) {
   459→			case *v3routepb.HeaderMatcher_ExactMatch:
   460→				header.ExactMatch = &ht.ExactMatch
   461→			case *v3routepb.HeaderMatcher_SafeRegexMatch:
   462→				regex := ht.SafeRegexMatch.GetRegex()
   463→				re, err := regexp.Compile(regex)
   464→				if err != nil {
   465→					return nil, fmt.Errorf("route %+v contains an invalid regex %q", r, regex)
   466→				}
   467→				header.RegexMatch = re
   468→			case *v3routepb.HeaderMatcher_RangeMatch:
   469→				header.RangeMatch = &Int64Range{
   470→					Start: ht.RangeMatch.Start,
   471→					End:   ht.RangeMatch.End,
   472→				}
   473→			case *v3routepb.HeaderMatcher_PresentMatch:
   474→				header.PresentMatch = &ht.PresentMatch
   475→			case *v3routepb.HeaderMatcher_PrefixMatch:
   476→				header.PrefixMatch = &ht.PrefixMatch
   477→			case *v3routepb.HeaderMatcher_SuffixMatch:
   478→				header.SuffixMatch = &ht.SuffixMatch
   479→			default:
   480→				return nil, fmt.Errorf("route %+v has an unrecognized header matcher: %+v", r, ht)
   481→			}
   482→			header.Name = h.GetName()
   483→			invert := h.GetInvertMatch()
   484→			header.InvertMatch = &invert
   485→			route.Headers = append(route.Headers, &header)
   486→		}
   487→
   488→		if fr := match.GetRuntimeFraction(); fr != nil {
   489→			d := fr.GetDefaultValue()
   490→			n := d.GetNumerator()
   491→			switch d.GetDenominator() {
   492→			case v3typepb.FractionalPercent_HUNDRED:
   493→				n *= 10000
   494→			case v3typepb.FractionalPercent_TEN_THOUSAND:
   495→				n *= 100
   496→			case v3typepb.FractionalPercent_MILLION:
   497→			}
   498→			route.Fraction = &n
   499→		}
   500→
   501→		route.WeightedClusters = make(map[string]WeightedCluster)
   502→		action := r.GetRoute()
   503→		switch a := action.GetClusterSpecifier().(type) {
   504→		case *v3routepb.RouteAction_Cluster:
   505→			route.WeightedClusters[a.Cluster] = WeightedCluster{Weight: 1}
   506→		case *v3routepb.RouteAction_WeightedClusters:
   507→			wcs := a.WeightedClusters
   508→			var totalWeight uint32
   509→			for _, c := range wcs.Clusters {
   510→				w := c.GetWeight().GetValue()
   511→				if w == 0 {
   512→					continue
   513→				}
   514→				wc := WeightedCluster{Weight: w}
   515→				if !v2 {
   516→					cfgs, err := processHTTPFilterOverrides(c.GetTypedPerFilterConfig())
   517→					if err != nil {
   518→						return nil, fmt.Errorf("route %+v, action %+v: %v", r, a, err)
   519→					}
   520→					wc.HTTPFilterConfigOverride = cfgs
   521→				}
   522→				route.WeightedClusters[c.GetName()] = wc
   523→				totalWeight += w
   524→			}
   525→			if totalWeight != wcs.GetTotalWeight().GetValue() {
   526→				return nil, fmt.Errorf("route %+v, action %+v, weights of clusters do not add up to total total weight, got: %v, want %v", r, a, wcs.GetTotalWeight().GetValue(), totalWeight)
   527→			}
   528→			if totalWeight == 0 {
   529→				return nil, fmt.Errorf("route %+v, action %+v, has no valid cluster in WeightedCluster action", r, a)
   530→			}
   531→		case *v3routepb.RouteAction_ClusterHeader:
   532→			continue
   533→		}
   534→
   535→		msd := action.GetMaxStreamDuration()
   536→		// Prefer grpc_timeout_header_max, if set.
   537→		dur := msd.GetGrpcTimeoutHeaderMax()
   538→		if dur == nil {
   539→			dur = msd.GetMaxStreamDuration()
   540→		}
   541→		if dur != nil {
   542→			d := dur.AsDuration()
   543→			route.MaxStreamDuration = &d
   544→		}
   545→
   546→		if !v2 {
   547→			cfgs, err := processHTTPFilterOverrides(r.GetTypedPerFilterConfig())
   548→			if err != nil {
   549→				return nil, fmt.Errorf("route %+v: %v", r, err)
   550→			}
   551→			route.HTTPFilterConfigOverride = cfgs
   552→		}
   553→		routesRet = append(routesRet, &route)
   554→	}
   555→	return routesRet, nil
   556→}
