   643→	if name := ts.GetName(); name != transportSocketName {
   644→		return nil, fmt.Errorf("transport_socket field has unexpected name: %s", name)
   645→	}
   646→	any := ts.GetTypedConfig()
   647→	if any == nil || any.TypeUrl != version.V3UpstreamTLSContextURL {
   648→		return nil, fmt.Errorf("transport_socket field has unexpected typeURL: %s", any.TypeUrl)
   649→	}
   650→	upstreamCtx := &v3tlspb.UpstreamTlsContext{}
   651→	if err := proto.Unmarshal(any.GetValue(), upstreamCtx); err != nil {
   652→		return nil, fmt.Errorf("failed to unmarshal UpstreamTlsContext in CDS response: %v", err)
   653→	}
