   668→// common is expected to be not nil.
   669→func securityConfigFromCommonTLSContext(common *v3tlspb.CommonTlsContext) (*SecurityConfig, error) {
   670→	// The `CommonTlsContext` contains a
   671→	// `tls_certificate_certificate_provider_instance` field of type
   672→	// `CertificateProviderInstance`, which contains the provider instance name
   673→	// and the certificate name to fetch identity certs.
   674→	sc := &SecurityConfig{}
   675→	if identity := common.GetTlsCertificateCertificateProviderInstance(); identity != nil {
   676→		sc.IdentityInstanceName = identity.GetInstanceName()
   677→		sc.IdentityCertName = identity.GetCertificateName()
   678→	}
   679→
   680→	// The `CommonTlsContext` contains a `validation_context_type` field which
   681→	// is a oneof. We can get the values that we are interested in from two of
   682→	// those possible values:
   683→	//  - combined validation context:
   684→	//    - contains a default validation context which holds the list of
   685→	//      matchers for accepted SANs.
   686→	//    - contains certificate provider instance configuration
   687→	//  - certificate provider instance configuration
   688→	//    - in this case, we do not get a list of accepted SANs.
   689→	switch t := common.GetValidationContextType().(type) {
   690→	case *v3tlspb.CommonTlsContext_CombinedValidationContext:
   691→		combined := common.GetCombinedValidationContext()
   692→		var matchers []xds.StringMatcher
   693→		if def := combined.GetDefaultValidationContext(); def != nil {
   694→			for _, m := range def.GetMatchSubjectAltNames() {
   695→				matcher, err := xds.StringMatcherFromProto(m)
   696→				if err != nil {
   697→					return nil, err
   698→				}
   699→				matchers = append(matchers, matcher)
   700→			}
   701→		}
   702→		sc.SubjectAltNameMatchers = matchers
   703→		if pi := combined.GetValidationContextCertificateProviderInstance(); pi != nil {
   704→			sc.RootInstanceName = pi.GetInstanceName()
   705→			sc.RootCertName = pi.GetCertificateName()
   706→		}
   707→	case *v3tlspb.CommonTlsContext_ValidationContextCertificateProviderInstance:
   708→		pi := common.GetValidationContextCertificateProviderInstance()
   709→		sc.RootInstanceName = pi.GetInstanceName()
   710→		sc.RootCertName = pi.GetCertificateName()
   711→	case nil:
   712→		// It is valid for the validation context to be nil on the server side.
   713→	default:
   714→		return nil, fmt.Errorf("validation context contains unexpected type: %T", t)
   715→	}
