   947→				errStrB.WriteString(";\n")
   948→			}
   949→			errStrB.WriteString(err.Error())
   950→		}
   951→	}
   952→	if len(perResourceErrors) > 0 {
   953→		var i int
   954→		for name, err := range perResourceErrors {
   955→			if i != 0 {
   956→				errStrB.WriteString(";\n")
   957→			}
   958→			i++
   959→			errStrB.WriteString(fmt.Sprintf("resource %q: %v", name, err.Error()))
