// Final edge case test for weighted cluster totalWeight defaulting
func TestWeightedClusterEdgeCases(t *testing.T) {
	tests := []struct {
		name        string
		totalWeight *wrapperspb.UInt32Value
		weights     []uint32
		shouldFail  bool
	}{
		{
			name:        "nil totalWeight, sum to 100",
			totalWeight: nil,
			weights:     []uint32{50, 50},
			shouldFail:  false,
		},
		{
			name:        "zero totalWeight, sum to 100",
			totalWeight: &wrapperspb.UInt32Value{Value: 0},
			weights:     []uint32{70, 30},
			shouldFail:  false,
		},
		{
			name:        "explicit 100 totalWeight, sum to 100",
			totalWeight: &wrapperspb.UInt32Value{Value: 100},
			weights:     []uint32{25, 75},
			shouldFail:  false,
		},
		{
			name:        "explicit 50 totalWeight, sum to 50",
			totalWeight: &wrapperspb.UInt32Value{Value: 50},
			weights:     []uint32{20, 30},
			shouldFail:  false,
		},
		{
			name:        "nil totalWeight, sum to 50 (should fail)",
			totalWeight: nil,
			weights:     []uint32{25, 25},
			shouldFail:  true,
		},
		{
			name:        "explicit 100 totalWeight, sum to 50 (should fail)",
			totalWeight: &wrapperspb.UInt32Value{Value: 100},
			weights:     []uint32{25, 25},
			shouldFail:  true,
		},
		{
			name:        "GitHub issue case: nil totalWeight with 5 clusters summing to 100",
			totalWeight: nil,
			weights:     []uint32{36, 13, 14, 31, 6},
			shouldFail:  false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clusters := make([]*v3routepb.WeightedCluster_ClusterWeight, len(tt.weights))
			for i, w := range tt.weights {
				clusters[i] = &v3routepb.WeightedCluster_ClusterWeight{
					Name:   "cluster-" + string(rune('a'+i)),
					Weight: &wrapperspb.UInt32Value{Value: w},
				}
			}

			rc := &v3routepb.RouteConfiguration{
				Name: "test-route",
				VirtualHosts: []*v3routepb.VirtualHost{
					{
						Domains: []string{"test.domain"},
						Routes: []*v3routepb.Route{
							{
								Match: &v3routepb.RouteMatch{
									PathSpecifier: &v3routepb.RouteMatch_Prefix{Prefix: "/"},
								},
								Action: &v3routepb.Route_Route{
									Route: &v3routepb.RouteAction{
										ClusterSpecifier: &v3routepb.RouteAction_WeightedClusters{
											WeightedClusters: &v3routepb.WeightedCluster{
												Clusters:    clusters,
												TotalWeight: tt.totalWeight,
											},
										},
									},
								},
							},
						},
					},
				},
			}

			_, err := generateRDSUpdateFromRouteConfiguration(rc, nil, false)
			if tt.shouldFail && err == nil {
				t.Errorf("Expected error but got success")
			} else if !tt.shouldFail && err != nil {
				t.Errorf("Expected success but got error: %v", err)
			}
		})
	}
}
