fn main() {
    println!("Reproducing regex flag sorting issue...");

    let start_time = Instant::now();
    let timeout_duration = Duration::from_secs(60);

    // Create test input with unsorted regex flags
    let test_input = r#"/[/]\/\u0aBc/mgi;"#;

    // Expected output (sorted flags)
    let expected_output = r#"/[/]\/\u0aBc/gim;"#;

    println!("Input:    {}", test_input);
    println!("Expected: {}", expected_output);

    // Run Rome formatter on the input
    let mut child = Command::new("cargo")
        .args(&["run", "--bin", "rome", "--", "format", "--stdin-file-path", "test.js"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to start rome process");

    // Send input to stdin
    if let Some(stdin) = child.stdin.take() {
        use std::io::Write;
        let mut stdin = stdin;
        stdin.write_all(test_input.as_bytes()).expect("Failed to write to stdin");
    }

    // Wait for the process with timeout
    let result = loop {
        if start_time.elapsed() > timeout_duration {
            println!("TIMEOUT: Process took longer than 60 seconds");
            child.kill().ok();
            return;
        }

        match child.try_wait() {
            Ok(Some(status)) => {
                let output = child.wait_with_output().expect("Failed to read output");
                break (status, output);
            }
            Ok(None) => {
                std::thread::sleep(Duration::from_millis(100));
                continue;
            }
            Err(e) => panic!("Error waiting for child: {}", e),
        }
    };

    let (status, output) = result;

    if !status.success() {
        println!("Rome formatter failed:");
        println!("stderr: {}", String::from_utf8_lossy(&output.stderr));
        return;
    }

    let formatted_output = String::from_utf8_lossy(&output.stdout).trim().to_string();
    println!("Actual:   {}", formatted_output);

    if formatted_output == expected_output {
        println!("✅ Test PASSED: Regex flags are properly sorted");
    } else {
        println!("❌ Test FAILED: Regex flags are NOT sorted");
        println!("Issue confirmed: Rome does not sort regex flags like Prettier does");
    }
}"}

