}", "newstring": "use crate::{Format, FormatElement, FormatNode, Formatter};
use rome_formatter::{FormatResult, Token};

use rome_js_syntax::JsRegexLiteralExpression;
use rome_js_syntax::JsRegexLiteralExpressionFields;

impl FormatNode for JsRegexLiteralExpression {
    fn format_fields(&self, formatter: &Formatter) -> FormatResult<FormatElement> {
        let JsRegexLiteralExpressionFields { value_token } = self.as_fields();
        let value_token = value_token?;

        let original = value_token.text_trimmed();

        // Parse regex literal to extract pattern and flags
        if let Some(sorted_regex) = sort_regex_flags(original) {
            // Flags need sorting
            Ok(formatter.format_replaced(
                &value_token,
                Token::new_dynamic(sorted_regex, value_token.text_trimmed_range().start()).into(),
            ))
        } else {
            // Flags already sorted or invalid regex
            value_token.format(formatter)
        }
    }
}

/// Parses a regex literal and returns a version with sorted flags if needed.
/// Returns None if the flags are already sorted or the regex is invalid.
fn sort_regex_flags(regex_literal: &str) -> Option<String> {
    // Regex literal format: /pattern/flags
    if !regex_literal.starts_with('/') {
        return None;
    }

    // Find the closing slash by scanning backwards
    let last_slash_pos = regex_literal.rfind('/')?;
    if last_slash_pos == 0 {
        return None; // No closing slash found
    }

    let pattern = &regex_literal[..last_slash_pos + 1]; // Include the closing slash
    let flags = &regex_literal[last_slash_pos + 1..];

    // If there are no flags, no sorting needed
    if flags.is_empty() {
        return None;
    }

    // Sort the flags alphabetically
    let mut flag_chars: Vec<char> = flags.chars().collect();
    flag_chars.sort_unstable();
    let sorted_flags: String = flag_chars.iter().collect();

    // If flags are already sorted, return None
    if flags == sorted_flags {
        return None;
    }

    // Return the regex with sorted flags
    Some(format!("{}{}", pattern, sorted_flags))
}"}

