async function run() {
  await mongoose.connect('mongodb://localhost:27017/test');

  await mongoose.connection.dropDatabase();

  const Test = mongoose.model('Test', new Schema({ name: String }));
  const Test2 = Test.discriminator('Test2', new Schema({ prop: String }));

  const doc = await Test2.create({ name: 'foo', prop: 'bar' });

  const Parent = mongoose.model('Parent', new Schema({
    child: { type: mongoose.ObjectId, ref: 'Test' }
  }));

