const { Schema } = mongoose;
const assert = require('assert');

async function run() {
  await mongoose.connect('mongodb://localhost:27017/test');

  await mongoose.connection.dropDatabase();

  // Based on the hint, create a test that validates excluding __t when populating
  const Test = mongoose.model(
    'Test',
    Schema({ name: String, arr: [{ testRef: { type: 'ObjectId', ref: 'Test2' } }] })
  );

  const schema = Schema({ name: String });
  const Test2 = mongoose.model('Test2', schema);
  const D = Test2.discriminator('D', Schema({ prop: String }));

  // Create a discriminator document
  const { _id } = await D.create({ name: 'foo', prop: 'bar' });
  const test = await Test.create({ name: 'test', arr: [{ testRef: _id }] });

  // Populate with projection excluding both _id and __t
  const doc = await Test
    .findById(test._id)
    .populate('arr.testRef', { name: 1, prop: 1, _id: 0, __t: 0 });

  const result = doc.toObject().arr[0].testRef;
  console.log('Result:', JSON.stringify(result, null, 2));

  // Should only have name and prop, not _id or __t
  assert.deepStrictEqual(
    result,
    { name: 'foo', prop: 'bar' }
  );

  console.log('✓ Test passed! Discriminator key __t was successfully deselected in populate');

  await mongoose.disconnect();
}

run().catch(err => {
  console.error('✗ Test failed:', err.message);
  process.exit(1);
});
"}

