{"content": "package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	v1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/kube-state-metrics/v2/internal/store"
	"k8s.io/kube-state-metrics/v2/pkg/allowdenylist"
	generator "k8s.io/kube-state-metrics/v2/pkg/metric_generator"
)

func main() {
	// Set up a timeout context
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	// Set up signal handling for timeout
	c := make(chan os.Signal, 1)
	signal.Notify(c, os.Interrupt, syscall.SIGTERM)
	go func() {
		select {
		case <-c:
			fmt.Println("\nTest interrupted")
			os.Exit(1)
		case <-ctx.Done():
			fmt.Println("\nTest timeout reached (30s)")
			os.Exit(1)
		}
	}()

	fmt.Println("=== Testing Azure Disk Name Support in kube_persistentvolume_info ===\n")

	// Create test PersistentVolumes with different volume sources
	pvGCE := &v1.PersistentVolume{
		ObjectMeta: metav1.ObjectMeta{
			Name: "test-gce-pv",
		},
		Spec: v1.PersistentVolumeSpec{
			PersistentVolumeSource: v1.PersistentVolumeSource{
				GCEPersistentDisk: &v1.GCEPersistentDiskVolumeSource{
					PDName: "gce-disk-123",
				},
			},
		},
	}

	pvEBS := &v1.PersistentVolume{
		ObjectMeta: metav1.ObjectMeta{
			Name: "test-ebs-pv",
		},
		Spec: v1.PersistentVolumeSpec{
			PersistentVolumeSource: v1.PersistentVolumeSource{
				AWSElasticBlockStore: &v1.AWSElasticBlockStoreVolumeSource{
					VolumeID: "vol-12345678",
				},
			},
		},
	}

	pvAzure := &v1.PersistentVolume{
		ObjectMeta: metav1.ObjectMeta{
			Name: "test-azure-pv",
		},
		Spec: v1.PersistentVolumeSpec{
			PersistentVolumeSource: v1.PersistentVolumeSource{
				AzureDisk: &v1.AzureDiskVolumeSource{
					DiskName:    "azure-disk-name-123",
					DataDiskURI: "https://mystorageaccount.blob.core.windows.net/vhds/azure-disk-name-123.vhd",
				},
			},
		},
	}

	// Create the metric family generators (simulate what's in store/persistentvolume.go)
	allowDenyList := allowdenylist.NewAllowDenyListFromStringSlice([]string{}, []string{})
	composedMetricGenFamilies := generator.ComposeMetricGenFamilies([]generator.FamilyGenerator{})
	familyHeaders := generator.ExtractMetricFamilyHeaders(composedMetricGenFamilies)

	// Use reflection to call the actual persistentVolume store function
	fmt.Println("Testing current kube_persistentvolume_info implementation:")
	fmt.Println("============================================================")

	// Test each PV
	testPVs := []*v1.PersistentVolume{pvGCE, pvEBS, pvAzure}
