   367→  private initIdentifier<T extends AnyEntity<T>>(entity: T): void {
   368→    const wrapped = entity.__helper!;
   369→
   370→    if (wrapped.__identifier || wrapped.hasPrimaryKey()) {
   371→      return;
   372→    }
   373→
   374→    wrapped.__identifier = new EntityIdentifier();
   375→  }
   376→
   377→  private processReference<T extends AnyEntity<T>>(parent: T, prop: EntityProperty<T>, reference: any, visited: WeakSet<AnyEntity>): void {
   378→    const isToOne = prop.reference === ReferenceType.MANY_TO_ONE || prop.reference === ReferenceType.ONE_TO_ONE;
   379→
   380→    if (isToOne && reference) {
   381→      return this.processToOneReference(reference, visited);
   382→    }
   383→
   384→    if (Utils.isCollection<any>(reference, prop, ReferenceType.MANY_TO_MANY) && reference.isDirty()) {
   385→      this.processToManyReference(reference, visited, parent, prop);
   386→    }
   387→  }
   388→
   389→  private processToOneReference<T extends AnyEntity<T>>(reference: any, visited: WeakSet<AnyEntity>): void {
   390→    if (!reference.__helper!.__managed) {
   391→      this.findNewEntities(reference, visited);
   392→    }
   393→  }
   394→
   395→  private processToManyReference<T extends AnyEntity<T>>(reference: Collection<AnyEntity>, visited: WeakSet<AnyEntity>, parent: T, prop: EntityProperty<T>): void {
   396→    if (this.isCollectionSelfReferenced(reference, visited)) {
   397→      this.extraUpdates.add([parent, prop.name, reference]);
   398→      parent[prop.name as keyof T] = new Collection<AnyEntity>(parent) as unknown as T[keyof T];
   399→
   400→      return;
   401→    }
   402→
   403→    reference.getItems(false)
   404→      .filter(item => !item.__helper!.__originalEntityData)
   405→      .forEach(item => this.findNewEntities(item, visited));
   406→  }
   407→
   408→  private async runHooks<T extends AnyEntity<T>>(type: EventType, changeSet: ChangeSet<T>, sync = false): Promise<unknown> {
   409→    const hasListeners = this.eventManager.hasListeners(type, changeSet.entity.__meta!);
   410→
   411→    if (!hasListeners) {
   412→      return;
   413→    }
   414→
   415→    if (!sync) {
   416→      return this.eventManager.dispatchEvent(type, { entity: changeSet.entity, em: this.em, changeSet });
   417→    }
   418→
   419→    const copy = this.comparator.prepareEntity(changeSet.entity) as T;
   420→    await this.eventManager.dispatchEvent(type, { entity: changeSet.entity, em: this.em, changeSet });
   421→    const current = this.comparator.prepareEntity(changeSet.entity) as T;
   422→    const diff = this.comparator.diffEntities<T>(changeSet.name, copy, current);
   423→    Object.assign(changeSet.payload, diff);
   424→    const wrapped = changeSet.entity.__helper!;
   425→
   426→    if (wrapped.__identifier && diff[wrapped.__meta.primaryKeys[0]]) {
   427→      wrapped.__identifier.setValue(diff[wrapped.__meta.primaryKeys[0]]);
   428→    }
   429→  }
