   431→  private postCommitCleanup(): void {
   432→    this.persistStack.clear();
   433→    this.removeStack.clear();
   434→    this.orphanRemoveStack.clear();
   435→    this.changeSets.clear();
   436→    this.collectionUpdates.clear();
   437→    this.extraUpdates.clear();
   438→    this.working = false;
   439→  }
   440→
   441→  private cascade<T extends AnyEntity<T>>(entity: T, type: Cascade, visited: WeakSet<AnyEntity>, options: { checkRemoveStack?: boolean } = {}): void {
   442→    if (visited.has(entity)) {
   443→      return;
   444→    }
   445→
   446→    visited.add(entity);
   447→
   448→    switch (type) {
   449→      case Cascade.PERSIST: this.persist(entity, visited, options.checkRemoveStack); break;
   450→      case Cascade.MERGE: this.merge(entity, visited); break;
   451→      case Cascade.REMOVE: this.remove(entity, visited); break;
   452→    }
   453→
   454→    for (const prop of entity.__meta!.relations) {
   455→      this.cascadeReference<T>(entity, prop, type, visited, options);
   456→    }
   457→  }
   458→
   459→  private cascadeReference<T extends AnyEntity<T>>(entity: T, prop: EntityProperty<T>, type: Cascade, visited: WeakSet<AnyEntity>, options: { checkRemoveStack?: boolean }): void {
   460→    this.fixMissingReference(entity, prop);
   461→
   462→    if (!this.shouldCascade(prop, type)) {
   463→      return;
   464→    }
   465→
   466→    const reference = Reference.unwrapReference(entity[prop.name]) as unknown as T | Collection<AnyEntity>;
   467→
   468→    if ([ReferenceType.MANY_TO_ONE, ReferenceType.ONE_TO_ONE].includes(prop.reference) && reference) {
   469→      return this.cascade(reference as T, type, visited, options);
   470→    }
   471→
   472→    const collection = reference as Collection<AnyEntity>;
   473→    const requireFullyInitialized = type === Cascade.PERSIST; // only cascade persist needs fully initialized items
   474→
   475→    if ([ReferenceType.ONE_TO_MANY, ReferenceType.MANY_TO_MANY].includes(prop.reference) && collection) {
   476→      if (type === Cascade.MERGE && collection.isInitialized()) {
   477→        collection.populated();
   478→      }
   479→
   480→      collection
   481→        .getItems(false)
   482→        .filter(item => !requireFullyInitialized || item.__helper!.__initialized)
   483→        .forEach(item => this.cascade(item, type, visited, options));
   484→    }
   485→  }
   486→
   487→  private isCollectionSelfReferenced(collection: Collection<AnyEntity>, visited: WeakSet<AnyEntity>): boolean {
   488→    const filtered = collection.getItems(false).filter(item => !item.__helper!.__originalEntityData);
   489→    return filtered.some(items => visited.has(items));
   490→  }
   491→
   492→  private shouldCascade(prop: EntityProperty, type: Cascade): boolean {
   493→    if (type === Cascade.REMOVE && prop.orphanRemoval) {
   494→      return true;
   495→    }
   496→
   497→    // ignore user settings for merge, it is kept only for back compatibility, this should have never been configurable
   498→    if (type === Cascade.MERGE) {
   499→      return true;
   500→    }
   501→
   502→    return prop.cascade && (prop.cascade.includes(type) || prop.cascade.includes(Cascade.ALL));
   503→  }
   504→
   505→  private async lockPessimistic<T extends AnyEntity<T>>(entity: T, mode: LockMode): Promise<void> {
   506→    if (!this.em.isInTransaction()) {
   507→      throw ValidationError.transactionRequired();
   508→    }
   509→
   510→    await this.em.getDriver().lockPessimistic(entity, mode, this.em.getTransactionContext());
   511→  }
   512→
   513→  private async lockOptimistic<T extends AnyEntity<T>>(entity: T, meta: EntityMetadata<T>, version: number | Date): Promise<void> {
   514→    if (!meta.versionProperty) {
   515→      throw OptimisticLockError.notVersioned(meta);
   516→    }
   517→
   518→    if (!Utils.isDefined<number | Date>(version)) {
   519→      return;
   520→    }
   521→
   522→    const wrapped = entity.__helper!;
   523→
   524→    if (!wrapped.__initialized) {
   525→      await wrapped.init();
   526→    }
   527→
   528→    const previousVersion = entity[meta.versionProperty] as unknown as Date | number;
   529→
   530→    if (previousVersion !== version) {
   531→      throw OptimisticLockError.lockFailedVersionMismatch(entity, version, previousVersion);
   532→    }
   533→  }
   534→
   535→  private fixMissingReference<T extends AnyEntity<T>>(entity: T, prop: EntityProperty<T>): void {
   536→    const reference = Reference.unwrapReference(entity[prop.name]);
   537→
   538→    if ([ReferenceType.MANY_TO_ONE, ReferenceType.ONE_TO_ONE].includes(prop.reference) && reference && !Utils.isEntity(reference)) {
   539→      entity[prop.name] = this.em.getReference(prop.type, reference as Primary<T[string & keyof T]>, !!prop.wrappedReference) as T[string & keyof T];
   540→    }
   541→
   542→    const isCollection = [ReferenceType.ONE_TO_MANY, ReferenceType.MANY_TO_MANY].includes(prop.reference);
   543→
   544→    if (isCollection && Array.isArray(reference)) {
   545→      const collection = new Collection<AnyEntity>(entity);
   546→      entity[prop.name as keyof T] = collection as unknown as T[keyof T];
   547→      collection.set(reference as AnyEntity[]);
   548→    }
   549→  }
   550→
   551→  private async persistToDatabase(groups: { [K in ChangeSetType]: Map<string, ChangeSet<any>[]> }, tx?: Transaction): Promise<void> {
   552→    const commitOrder = this.getCommitOrder();
   553→    const commitOrderReversed = [...commitOrder].reverse();
   554→
   555→    // 1. create
   556→    for (const name of commitOrder) {
   557→      await this.commitCreateChangeSets(groups[ChangeSetType.CREATE][name] ?? [], tx);
   558→    }
   559→
   560→    // 2. update
   561→    for (const name of commitOrder) {
   562→      await this.commitUpdateChangeSets(groups[ChangeSetType.UPDATE][name] ?? [], tx);
   563→    }
   564→
   565→    // 3. delete - entity deletions need to be in reverse commit order
   566→    for (const name of commitOrderReversed) {
   567→      await this.commitDeleteChangeSets(groups[ChangeSetType.DELETE][name] ?? [], tx);
   568→    }
   569→
   570→    // 4. extra updates
   571→    const extraUpdates: ChangeSet<any>[] = [];
   572→
   573→    for (const extraUpdate of this.extraUpdates) {
   574→      extraUpdate[0][extraUpdate[1]] = extraUpdate[2];
   575→      const changeSet = this.changeSetComputer.computeChangeSet(extraUpdate[0])!;
   576→
   577→      if (changeSet) {
   578→        extraUpdates.push(changeSet);
   579→      }
   580→    }
   581→
   582→    await this.commitUpdateChangeSets(extraUpdates, tx, false);
   583→
   584→    // 5. collection updates
   585→    for (const coll of this.collectionUpdates) {
   586→      await this.em.getDriver().syncCollection(coll, tx);
   587→      coll.takeSnapshot();
   588→    }
   589→  }
   590→
   591→  private async commitCreateChangeSets<T extends AnyEntity<T>>(changeSets: ChangeSet<T>[], ctx?: Transaction): Promise<void> {
   592→    if (changeSets.length === 0) {
   593→      return;
   594→    }
   595→
   596→    const meta = changeSets[0].entity.__meta!;
   597→    const props = meta.relations.filter(prop => {
   598→      return (prop.reference === ReferenceType.ONE_TO_ONE && prop.owner) || prop.reference === ReferenceType.MANY_TO_ONE;
   599→    });
   600→
   601→    for (const changeSet of changeSets) {
   602→      this.findExtraUpdates(changeSet, props);
   603→      await this.runHooks(EventType.beforeCreate, changeSet, true);
   604→    }
   605→
   606→    await this.changeSetPersister.executeInserts(changeSets, ctx);
   607→
   608→    for (const changeSet of changeSets) {
   609→      this.registerManaged<T>(changeSet.entity, changeSet.payload, true);
   610→      await this.runHooks(EventType.afterCreate, changeSet);
   611→    }
   612→  }
   613→
   614→  private findExtraUpdates<T extends AnyEntity<T>>(changeSet: ChangeSet<T>, props: EntityProperty<T>[]): void {
   615→    for (const prop of props) {
   616→      if (!changeSet.entity[prop.name]) {
   617→        continue;
   618→      }
   619→
   620→      const cs = this.changeSets.get(Reference.unwrapReference(changeSet.entity[prop.name]));
   621→      const isScheduledForInsert = cs && cs.type === ChangeSetType.CREATE && !cs.persisted;
   622→
   623→      if (isScheduledForInsert) {
   624→        this.scheduleExtraUpdate(changeSet, prop);
   625→      }
   626→    }
   627→  }
   628→
   629→  private async commitUpdateChangeSets<T extends AnyEntity<T>>(changeSets: ChangeSet<T>[], ctx?: Transaction, batched = true): Promise<void> {
   630→    if (changeSets.length === 0) {
   631→      return;
   632→    }
   633→
   634→    for (const changeSet of changeSets) {
   635→      await this.runHooks(EventType.beforeUpdate, changeSet, true);
   636→    }
   637→
   638→    await this.changeSetPersister.executeUpdates(changeSets, batched, ctx);
   639→
   640→    for (const changeSet of changeSets) {
   641→      changeSet.entity.__helper!.__originalEntityData = this.comparator.prepareEntity(changeSet.entity);
   642→      await this.runHooks(EventType.afterUpdate, changeSet);
   643→    }
   644→  }
   645→
   646→  private async commitDeleteChangeSets<T extends AnyEntity<T>>(changeSets: ChangeSet<T>[], ctx?: Transaction): Promise<void> {
   647→    if (changeSets.length === 0) {
   648→      return;
   649→    }
   650→
   651→    for (const changeSet of changeSets) {
   652→      await this.runHooks(EventType.beforeDelete, changeSet, true);
   653→    }
   654→
   655→    await this.changeSetPersister.executeDeletes(changeSets, ctx);
   656→
   657→    for (const changeSet of changeSets) {
   658→      this.unsetIdentity(changeSet.entity);
   659→      await this.runHooks(EventType.afterDelete, changeSet);
   660→    }
   661→  }
   662→
   663→  /**
   664→   * Orders change sets so FK constrains are maintained, ensures stable order (needed for node < 11)
   665→   */
   666→  private getChangeSetGroups(): { [K in ChangeSetType]: Map<string, ChangeSet<any>[]> } {
   667→    const groups = {
   668→      [ChangeSetType.CREATE]: new Map<string, ChangeSet<any>[]>(),
   669→      [ChangeSetType.UPDATE]: new Map<string, ChangeSet<any>[]>(),
   670→      [ChangeSetType.DELETE]: new Map<string, ChangeSet<any>[]>(),
   671→    };
   672→
   673→    this.changeSets.forEach(cs => {
   674→      const group = groups[cs.type];
   675→      group[cs.rootName] = group[cs.rootName] ?? [];
   676→      group[cs.rootName].push(cs);
   677→    });
   678→
   679→    return groups;
   680→  }
   681→
   682→  private getCommitOrder(): string[] {
   683→    const calc = new CommitOrderCalculator();
   684→    const set = new Set<string>();
   685→    this.changeSets.forEach(cs => set.add(cs.rootName));
   686→    set.forEach(entityName => calc.addNode(entityName));
   687→
   688→    for (const entityName of set) {
   689→      for (const prop of this.metadata.find(entityName)!.props) {
   690→        calc.discoverProperty(prop, entityName);
   691→      }
   692→    }
   693→
   694→    return calc.sort();
   695→  }
   696→
   697→}
