     7→export interface FactoryOptions {
     8→  initialized?: boolean;
     9→  newEntity?: boolean;
    10→  merge?: boolean;
    11→  refresh?: boolean;
    12→  convertCustomTypes?: boolean;
    13→}
    14→
    15→export class EntityFactory {
    16→
    17→  private readonly driver = this.em.getDriver();
    18→  private readonly platform = this.driver.getPlatform();
    19→  private readonly config = this.em.config;
    20→  private readonly metadata = this.em.getMetadata();
    21→  private readonly hydrator = this.config.getHydrator(this.metadata);
    22→  private readonly eventManager = this.em.getEventManager();
    23→
    24→  constructor(private readonly unitOfWork: UnitOfWork,
    25→              private readonly em: EntityManager) { }
    26→
    27→  create<T extends AnyEntity<T>, P extends Populate<T> = any>(entityName: EntityName<T>, data: EntityData<T>, options: FactoryOptions = {}): New<T, P> {
    28→    options.initialized = options.initialized ?? true;
    29→
    30→    if (data.__entity) {
    31→      return data as New<T, P>;
    32→    }
    33→
    34→    entityName = Utils.className(entityName);
    35→    const meta = this.metadata.get(entityName);
    36→
    37→    if (this.platform.usesDifferentSerializedPrimaryKey()) {
    38→      meta.primaryKeys.forEach(pk => this.denormalizePrimaryKey(data, pk, meta.properties[pk]));
    39→    }
    40→
    41→    const meta2 = this.processDiscriminatorColumn<T>(meta, data);
    42→    const exists = this.findEntity<T>(data, meta2, options.convertCustomTypes);
    43→
    44→    if (exists && exists.__helper!.__initialized && !options.refresh) {
    45→      return exists as New<T, P>;
    46→    }
    47→
    48→    data = { ...data };
    49→    const entity = exists ?? this.createEntity<T>(data, meta2, options);
    50→    entity.__helper!.__initialized = options.initialized;
    51→    this.hydrate(entity, meta2, data, options);
    52→
    53→    if (options.merge) {
    54→      this.unitOfWork.registerManaged(entity, data, options.refresh && options.initialized, options.newEntity);
    55→    }
    56→
    57→    if (this.eventManager.hasListeners(EventType.onInit, meta2)) {
    58→      this.eventManager.dispatchEvent(EventType.onInit, { entity, em: this.em });
