    63→
    64→  createReference<T>(entityName: EntityName<T>, id: Primary<T> | Primary<T>[] | Record<string, Primary<T>>, options: Pick<FactoryOptions, 'merge' | 'convertCustomTypes'> = {}): T {
    65→    options.convertCustomTypes = options.convertCustomTypes ?? true;
    66→    entityName = Utils.className(entityName);
    67→    const meta = this.metadata.get(entityName);
    68→
    69→    if (Array.isArray(id)) {
    70→      id = Utils.getPrimaryKeyCondFromArray(id, meta.primaryKeys);
    71→    }
    72→
    73→    const pks = Utils.getOrderedPrimaryKeys<T>(id, meta, this.platform, options.convertCustomTypes);
    74→
    75→    if (Utils.isPrimaryKey(id)) {
    76→      id = { [meta.primaryKeys[0]]: id as Primary<T> };
    77→    }
    78→
    79→    const exists = this.unitOfWork.getById<T>(entityName, pks);
    80→
    81→    if (exists) {
    82→      return exists;
    83→    }
    84→
    85→    return this.create<T>(entityName, id as EntityData<T>, { ...options, initialized: false });
    86→  }
    87→
    88→  private createEntity<T extends AnyEntity<T>>(data: EntityData<T>, meta: EntityMetadata<T>, options: FactoryOptions): T {
