   104→      this.unitOfWork.registerManaged<T>(entity);
   105→    }
   106→
   107→    return entity;
   108→  }
   109→
   110→  private hydrate<T>(entity: T, meta: EntityMetadata<T>, data: EntityData<T>, options: FactoryOptions): void {
   111→    if (options.initialized) {
   112→      this.hydrator.hydrate(entity, meta, data, this, 'full', options.newEntity, options.convertCustomTypes);
   113→    } else {
   114→      this.hydrator.hydrateReference(entity, meta, data, this, options.convertCustomTypes);
   115→    }
   116→  }
   117→
   118→  private findEntity<T>(data: EntityData<T>, meta: EntityMetadata<T>, convertCustomTypes?: boolean): T | undefined {
   119→    if (!meta.compositePK && !meta.properties[meta.primaryKeys[0]].customType) {
   120→      return this.unitOfWork.getById<T>(meta.name!, data[meta.primaryKeys[0]]);
   121→    }
   122→
   123→    if (meta.primaryKeys.some(pk => !Utils.isDefined(data[pk as keyof T], true))) {
   124→      return undefined;
   125→    }
   126→
   127→    const pks = Utils.getOrderedPrimaryKeys<T>(data as Dictionary, meta, this.platform, convertCustomTypes);
   128→
   129→    return this.unitOfWork.getById<T>(meta.name!, pks);
   130→  }
   131→
   132→  private processDiscriminatorColumn<T>(meta: EntityMetadata<T>, data: EntityData<T>): EntityMetadata<T> {
   133→    if (!meta.root.discriminatorColumn) {
   134→      return meta;
   135→    }
   136→
   137→    const prop = meta.properties[meta.root.discriminatorColumn];
   138→    const value = data[prop.name];
   139→    const type = meta.root.discriminatorMap![value];
   140→    meta = type ? this.metadata.find(type)! : meta;
   141→
   142→    // `prop.userDefined` is either `undefined` or `false`
   143→    if (prop.userDefined === false) {
   144→      delete data[prop.name];
   145→    }
   146→
   147→    return meta;
   148→  }
   149→
   150→  /**
   151→   * denormalize PK to value required by driver (e.g. ObjectId)
   152→   */
   153→  private denormalizePrimaryKey<T>(data: EntityData<T>, primaryKey: string, prop: EntityProperty<T>): void {
   154→    const pk = this.platform.getSerializedPrimaryKeyField(primaryKey);
   155→
   156→    if (Utils.isDefined(data[pk], true) || Utils.isDefined(data[primaryKey], true)) {
   157→      let id = data[pk] || data[primaryKey];
   158→
   159→      if (prop.type.toLowerCase() === 'objectid') {
   160→        id = this.platform.denormalizePrimaryKey(id);
   161→      }
   162→
   163→      delete data[pk];
   164→      data[primaryKey as keyof T] = id as Primary<T> & T[keyof T];
   165→    }
   166→  }
   167→
   168→  /**
   169→   * returns parameters for entity constructor, creating references from plain ids
   170→   */
   171→  private extractConstructorParams<T>(meta: EntityMetadata<T>, data: EntityData<T>): T[keyof T][] {
   172→    return meta.constructorParams.map(k => {
   173→      if (meta.properties[k] && [ReferenceType.MANY_TO_ONE, ReferenceType.ONE_TO_ONE].includes(meta.properties[k].reference) && data[k]) {
   174→        const entity = this.unitOfWork.getById(meta.properties[k].type, data[k]) as T[keyof T];
   175→
   176→        if (entity) {
   177→          return entity;
   178→        }
   179→
   180→        if (Utils.isEntity<T>(data[k])) {
   181→          return data[k];
   182→        }
   183→
   184→        return this.createReference(meta.properties[k].type, data[k]);
   185→      }
   186→
   187→      if (!meta.properties[k]) {
   188→        return data;
   189→      }
   190→
   191→      return data[k];
   192→    });
   193→  }
   194→
   195→}
