   211→  private async findChildren<T extends AnyEntity<T>>(entities: T[], prop: EntityProperty, populate: PopulateOptions<T>, options: Required<Options<T>>): Promise<AnyEntity[]> {
   212→    const children = this.getChildReferences<T>(entities, prop, options.refresh);
   213→    const meta = this.metadata.find(prop.type)!;
   214→    let fk = Utils.getPrimaryKeyHash(meta.primaryKeys);
