   326→  private getChildReferences<T extends AnyEntity<T>>(entities: T[], prop: EntityProperty<T>, refresh: boolean): AnyEntity[] {
   327→    const filtered = this.filterCollections(entities, prop.name, refresh);
   328→    const children: AnyEntity[] = [];
   329→
   330→    if (prop.reference === ReferenceType.ONE_TO_MANY) {
   331→      children.push(...filtered.map(e => (e[prop.name] as unknown as Collection<T>).owner));
   332→    } else if (prop.reference === ReferenceType.MANY_TO_MANY && prop.owner) {
