   379→          strategy: this.em.config.get('loadStrategy'),
   380→        });
   381→      }
   382→    });
   383→
   384→    return ret;
   385→  }
   386→
   387→  private lookupEagerLoadedRelationships<T>(entityName: string, populate: PopulateOptions<T>[], prefix = '', visited: string[] = []): PopulateOptions<T>[] {
   388→    if (visited.includes(entityName)) {
   389→      return [];
   390→    }
   391→
   392→    visited.push(entityName);
   393→    const meta = this.metadata.find(entityName)!;
