   304→        for (UniqueConstraint uniqueConstraint : statement.getUniqueConstraints()) {
   305→            if (uniqueConstraint.getConstraintName() == null) {  // Only combine uniqueConstraints that have a name.
   306→                unnamedUniqueConstraints.add(uniqueConstraint);
   307→            } else {
   308→                String constraintName = uniqueConstraint.getConstraintName();
   309→                UniqueConstraint existingConstraint = namedUniqueConstraints.get(constraintName);
   310→
   311→                if (existingConstraint != null) {
   312→                    if (uniqueConstraint.shouldValidateUnique()) {
   313→                        //if validateUnique = true on only one column, make sure it is true
   314→                        existingConstraint.setValidateUnique(true);
   315→                    }
   316→
   317→                    existingConstraint.getColumns().addAll(uniqueConstraint.getColumns());
   318→                } else {
   319→                    // if we haven't seen the constraint before put it in the map.
   320→                    namedUniqueConstraints.put(constraintName, uniqueConstraint);
   321→                }
   322→            }
   323→        }
   324→
   325→        unnamedUniqueConstraints.addAll(namedUniqueConstraints.values());
   326→
   327→        for (UniqueConstraint uniqueConstraint : unnamedUniqueConstraints) {
   328→            if (uniqueConstraint.getConstraintName() != null) {
   329→                buffer.append(" CONSTRAINT ");
   330→                buffer.append(database.escapeConstraintName(uniqueConstraint.getConstraintName()));
   331→            }
   332→            buffer.append(" UNIQUE (");
   333→            buffer.append(database.escapeColumnNameList(StringUtil.join(uniqueConstraint.getColumns(), ", ")));
   334→            buffer.append(")");
   335→            if (database instanceof OracleDatabase) {
   336→                buffer.append(!uniqueConstraint.shouldValidateUnique() ? " ENABLE NOVALIDATE " : "");
   337→            }
   338→            buffer.append(",");
   339→        }
   340→
   341→        /*
   342→         * Here, the list of columns and constraints in the form
   343→         * ( column1, ..., columnN, constraint1, ..., constraintN,
   344→         * ends. We cannot leave an expression like ", )", so we remove the last comma.
   345→         */
   346→        String sql = buffer.toString().replaceFirst(",\\s*$", "") + ")";
   347→
   348→        if ((database instanceof MySQLDatabase) && (mysqlTableOptionStartWith != null)) {
   349→            Scope.getCurrentScope().getLog(getClass()).info("[MySQL] Using last startWith statement ("+mysqlTableOptionStartWith.toString()+") as table option.");
