   365→        }
   366→        additionalSql.add(0, new UnparsedSql(sql, getAffectedTable(statement)));
   367→        return additionalSql.toArray(new Sql[additionalSql.size()]);
   368→    }
   369→
   370→    protected Relation getAffectedTable(CreateTableStatement statement) {
   371→        return new Table().setName(statement.getTableName()).setSchema(new Schema(statement.getCatalogName(), statement.getSchemaName()));
   372→    }
