import liquibase.change.ConstraintsConfig;
import liquibase.change.core.CreateTableChange;
import liquibase.change.ColumnConfig;
import liquibase.database.core.PostgresDatabase;
import liquibase.statement.SqlStatement;
import liquibase.sqlgenerator.SqlGeneratorFactory;
import liquibase.sql.Sql;

public class test_constraints_config {
    public static void main(String[] args) throws Exception {
        // Create a CreateTableChange like it would be from XML
        CreateTableChange change = new CreateTableChange();
        change.setTableName("abc");

        // Create a column with constraints
        ColumnConfig column = new ColumnConfig();
        column.setName("id");
        column.setType("INTEGER");

        // Create constraints config with deferrable and initiallyDeferred
        ConstraintsConfig constraints = new ConstraintsConfig();
        constraints.setNullable(false);
        constraints.setPrimaryKey(true);
        constraints.setPrimaryKeyName("abc_PK");
        constraints.setDeferrable(true);
        constraints.setInitiallyDeferred(true);

        column.setConstraints(constraints);
        change.addColumn(column);

        // Generate statements
        PostgresDatabase database = new PostgresDatabase();
        SqlStatement[] statements = change.generateStatements(database);

        // Generate SQL
        for (SqlStatement statement : statements) {
            Sql[] sqls = SqlGeneratorFactory.getInstance().generateSql(statement, database);
            for (Sql sql : sqls) {
                String sqlText = sql.toSql();
                System.out.println("Generated SQL: " + sqlText);

                // Check if the SQL contains DEFERRABLE and INITIALLY DEFERRED
                if (sqlText.contains("DEFERRABLE") && sqlText.contains("INITIALLY DEFERRED")) {
                    System.out.println("\n✓ SUCCESS: XML constraints properly flow through to SQL generation");
                } else {
                    System.out.println("\n✗ FAILURE: XML constraints not properly mapped");
                }
            }
        }
    }
}
