}

void test_8_elements() {
  // Test with exactly 8 elements (1 byte, no padding)
  AlignedData<2> segment1 = {{
      0x01, 0x00, 0x00, 0x00, 0x51, 0x00, 0x00, 0x00, // eight bit-sized elements
      0xff, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
