const mongoose = require('./lib');
const { Schema } = mongoose;

// This test simulates the exact scenario from the issue description
function testOriginalIssue() {
    const baseNestedDiscriminated = new Schema({
        type: { type: Number, required: true },
    }, { discriminatorKey: "type" });

    class BaseClass {
        type = 1;

        whoAmI() {
            return "I am baseNestedDiscriminated";
        }
    }

    baseNestedDiscriminated.loadClass(BaseClass);

    class NumberTyped extends BaseClass {
        type = 3;

        whoAmI() {
            return "I am NumberTyped";
        }
    }

    class StringTyped extends BaseClass {
        type = 4;

        whoAmI() {
            return "I am StringTyped";
        }
    }

    baseNestedDiscriminated.discriminator(1, new Schema({}).loadClass(NumberTyped));
    baseNestedDiscriminated.discriminator("3", new Schema({}).loadClass(StringTyped));

    const containsNestedSchema = new Schema({
        nestedDiscriminatedTypes: { type: [baseNestedDiscriminated], required: true },
    });

    class ContainsNested {
        nestedDiscriminatedTypes = [];
        type = 1;

        whoAmI() {
            return "I am ContainsNested";
        }
    }
    containsNestedSchema.loadClass(ContainsNested);

    // Test that discriminators are properly applied
    const nestedPath = containsNestedSchema.path("nestedDiscriminatedTypes");
    const discriminators = nestedPath.caster.discriminators || {};

    console.log("✅ Test 1: Checking discriminator keys are present");
    if (!discriminators["1"] || !discriminators["3"]) {
        throw new Error("❌ Expected discriminators not found on nested path caster");
    }

    console.log("✅ Test 2: Testing discriminator constructor instantiation");
    const testInstance1 = new discriminators["1"]();
    const testInstance3 = new discriminators["3"]();

    if (testInstance1.whoAmI() !== "I am NumberTyped") {
        throw new Error(`❌ Expected "I am NumberTyped", got "${testInstance1.whoAmI()}"`);
    }

    if (testInstance3.whoAmI() !== "I am StringTyped") {
        throw new Error(`❌ Expected "I am StringTyped", got "${testInstance3.whoAmI()}"`);
    }

    console.log("✅ Test 3: Testing instance types");
    if (testInstance1.type !== 3) {
        throw new Error(`❌ Expected type 3, got ${testInstance1.type}`);
    }

    if (testInstance3.type !== 4) {
        throw new Error(`❌ Expected type 4, got ${testInstance3.type}`);
    }

    // Test that both direct array usage and nested object usage work
    const directArraySchema = new Schema({items: [baseNestedDiscriminated]});
    const directArrayPath = directArraySchema.path("items");
    const directDiscriminators = directArrayPath.caster.discriminators || {};

    console.log("✅ Test 4: Testing direct array discriminators still work");
    if (!directDiscriminators["1"] || !directDiscriminators["3"]) {
        throw new Error("❌ Direct array discriminators not working");
    }

    const directTestInstance1 = new directDiscriminators["1"]();
    const directTestInstance3 = new directDiscriminators["3"]();

    if (directTestInstance1.whoAmI() !== "I am NumberTyped" ||
        directTestInstance3.whoAmI() !== "I am StringTyped") {
        throw new Error("❌ Direct array discriminator instances not working correctly");
    }

    console.log("🎉 All tests passed! The original issue has been fixed.");
}

try {
    testOriginalIssue();
} catch (error) {
    console.error("❌ Test failed:", error.message);
    process.exit(1);
}"}

