	defer cancel()

	done := make(chan bool)
	go func() {
		fmt.Println("=== Testing InsecureUseHTTP Configuration ===")

		// Test 1: Default value should be false
		fmt.Println("\nTest 1: Default configuration (should be false)")
		v := viper.New()
		opts := &config.CliOnlyOptions{
			ConfigPath: "",
			Verbosity:  0,
		}
		cfg, err := config.LoadConfigFromFile(v, opts)
		if err != nil {
			fmt.Printf("Failed to load config: %v\n", err)
			done <- false
			return
		}

		registryOpts := cfg.Registry.ToOptions()
		fmt.Printf("InsecureUseHTTP: %v (expected: false)\n", registryOpts.InsecureUseHTTP)
		if registryOpts.InsecureUseHTTP != false {
			fmt.Printf("FAIL: Expected InsecureUseHTTP to be false, got %v\n", registryOpts.InsecureUseHTTP)
			done <- false
			return
		}
		fmt.Println("✓ PASS: Default InsecureUseHTTP is false")

		// Test 2: Set via environment variable
		fmt.Println("\nTest 2: Set via environment variable GRYPE_REGISTRY_INSECURE_USE_HTTP=true")
		os.Setenv("GRYPE_REGISTRY_INSECURE_USE_HTTP", "true")
		defer os.Unsetenv("GRYPE_REGISTRY_INSECURE_USE_HTTP")

		v2 := viper.New()
		opts2 := &config.CliOnlyOptions{
			ConfigPath: "",
			Verbosity:  0,
		}
		cfg2, err := config.LoadConfigFromFile(v2, opts2)
		if err != nil {
			fmt.Printf("Failed to load config: %v\n", err)
			done <- false
			return
		}

		registryOpts2 := cfg2.Registry.ToOptions()
		fmt.Printf("InsecureUseHTTP: %v (expected: true)\n", registryOpts2.InsecureUseHTTP)
		if registryOpts2.InsecureUseHTTP != true {
			fmt.Printf("FAIL: Expected InsecureUseHTTP to be true, got %v\n", registryOpts2.InsecureUseHTTP)
			done <- false
			return
		}
		fmt.Println("✓ PASS: InsecureUseHTTP is true when set via environment variable")

		// Test 3: Verify InsecureSkipTLSVerify still works
		fmt.Println("\nTest 3: Verify InsecureSkipTLSVerify still works")
		os.Setenv("GRYPE_REGISTRY_INSECURE_SKIP_TLS_VERIFY", "true")
		defer os.Unsetenv("GRYPE_REGISTRY_INSECURE_SKIP_TLS_VERIFY")

		v3 := viper.New()
		opts3 := &config.CliOnlyOptions{
			ConfigPath: "",
			Verbosity:  0,
		}
		cfg3, err := config.LoadConfigFromFile(v3, opts3)
		if err != nil {
			fmt.Printf("Failed to load config: %v\n", err)
			done <- false
			return
		}

		registryOpts3 := cfg3.Registry.ToOptions()
		fmt.Printf("InsecureSkipTLSVerify: %v (expected: true)\n", registryOpts3.InsecureSkipTLSVerify)
		fmt.Printf("InsecureUseHTTP: %v (expected: true)\n", registryOpts3.InsecureUseHTTP)
		if registryOpts3.InsecureSkipTLSVerify != true {
			fmt.Printf("FAIL: Expected InsecureSkipTLSVerify to be true, got %v\n", registryOpts3.InsecureSkipTLSVerify)
			done <- false
			return
		}
		if registryOpts3.InsecureUseHTTP != true {
			fmt.Printf("FAIL: Expected InsecureUseHTTP to be true, got %v\n", registryOpts3.InsecureUseHTTP)
			done <- false
			return
		}
		fmt.Println("✓ PASS: Both InsecureSkipTLSVerify and InsecureUseHTTP work together")

		fmt.Println("\n=== All Tests Passed! ===")
		done <- true
	}()

	select {
	case <-ctx.Done():
		fmt.Println("\n!!! TIMEOUT: Tests took more than 60 seconds !!!")
		os.Exit(1)
	case success := <-done:
		if !success {
			fmt.Println("\n!!! Tests Failed !!!")
			os.Exit(1)
		}
		os.Exit(0)
	}
}
"}

