   196→	}
   197→
   198→	if a.Reader == nil {
   199→		a.Reader = os.Stdin
   200→	}
   201→
   202→	if a.Writer == nil {
   203→		a.Writer = os.Stdout
   204→	}
   205→
   206→	if a.ErrWriter == nil {
   207→		a.ErrWriter = os.Stderr
   208→	}
   209→
   210→	if a.AllowExtFlags {
   211→		// add global flags added by other packages
   212→		flag.VisitAll(func(f *flag.Flag) {
   213→			// skip test flags
