   220→	if len(a.SliceFlagSeparator) != 0 {
   221→		a.separator.customized = true
   222→		a.separator.sep = a.SliceFlagSeparator
   223→	}
   224→
   225→	if a.DisableSliceFlagSeparator {
   226→		a.separator.customized = true
   227→		a.separator.disabled = true
   228→	}
   229→
   230→	var newCommands []*Command
   231→
   232→	for _, c := range a.Commands {
   233→		cname := c.Name
   234→		if c.HelpName != "" {
   235→			cname = c.HelpName
   236→		}
   237→		c.separator = a.separator
   238→		c.HelpName = fmt.Sprintf("%s %s", a.HelpName, cname)
   239→		c.flagCategories = newFlagCategoriesFromFlags(c.Flags)
   240→		newCommands = append(newCommands, c)
   241→	}
