   312→// RunContext is like Run except it takes a Context that will be
   313→// passed to its commands and sub-commands. Through this, you can
   314→// propagate timeouts and cancellation requests
   315→func (a *App) RunContext(ctx context.Context, arguments []string) (err error) {
   316→	a.Setup()
   317→
   318→	// handle the completion flag separately from the flagset since
   319→	// completion could be attempted after a flag, but before its value was put
   320→	// on the command line. this causes the flagset to interpret the completion
   321→	// flag name as the value of the flag before it which is undesirable
   322→	// note that we can only do this because the shell autocomplete function
   323→	// always appends the completion flag at the end of the command
   324→	shellComplete, arguments := checkShellCompleteFlag(a, arguments)
   325→
   326→	cCtx := NewContext(a, nil, &Context{Context: ctx})
   327→	cCtx.shellComplete = shellComplete
   328→
   329→	a.rootCommand = a.newRootCommand()
   330→	cCtx.Command = a.rootCommand
   331→
   332→	if err := checkDuplicatedCmds(a.rootCommand); err != nil {
   333→		return err
   334→	}
   335→	return a.rootCommand.Run(cCtx, arguments...)
   336→}
