   338→// RunAsSubcommand is for legacy/compatibility purposes only. New code should only
   339→// use App.RunContext. This function is slated to be removed in v3.
   340→func (a *App) RunAsSubcommand(ctx *Context) (err error) {
   341→	a.Setup()
   342→
   343→	cCtx := NewContext(a, nil, ctx)
   344→	cCtx.shellComplete = ctx.shellComplete
   345→
   346→	a.rootCommand = a.newRootCommand()
   347→	cCtx.Command = a.rootCommand
   348→
   349→	return a.rootCommand.Run(cCtx, ctx.Args().Slice()...)
   350→}
