   352→func (a *App) suggestFlagFromError(err error, command string) (string, error) {
   353→	flag, parseErr := flagFromError(err)
   354→	if parseErr != nil {
   355→		return "", err
   356→	}
   357→
   358→	flags := a.Flags
   359→	hideHelp := a.HideHelp
   360→	if command != "" {
   361→		cmd := a.Command(command)
   362→		if cmd == nil {
   363→			return "", err
   364→		}
   365→		flags = cmd.Flags
   366→		hideHelp = hideHelp \|\| cmd.HideHelp
   367→	}
   368→
   369→	suggestion := SuggestFlag(flags, flag, hideHelp)
   370→	if len(suggestion) == 0 {
   371→		return "", err
   372→	}
   373→
   374→	return fmt.Sprintf(SuggestDidYouMeanTemplate+"\n\n", suggestion), nil
   375→}
