   472→func runFlagActions(c *Context, fs []Flag) error {
   473→	for _, f := range fs {
   474→		isSet := false
   475→		for _, name := range f.Names() {
   476→			if c.IsSet(name) {
   477→				isSet = true
   478→				break
   479→			}
   480→		}
   481→		if isSet {
   482→			if af, ok := f.(ActionableFlag); ok {
   483→				if err := af.RunAction(c); err != nil {
   484→					return err
   485→				}
   486→			}
   487→		}
   488→	}
   489→	return nil
   490→}
