   508→// HandleAction attempts to figure out which Action signature was used.  If
   509→// it's an ActionFunc or a func with the legacy signature for Action, the func
   510→// is run!
   511→func HandleAction(action interface{}, cCtx *Context) (err error) {
   512→	switch a := action.(type) {
   513→	case ActionFunc:
   514→		return a(cCtx)
   515→	case func(*Context) error:
   516→		return a(cCtx)
   517→	case func(*Context): // deprecated function signature
   518→		a(cCtx)
   519→		return nil
   520→	}
   521→
   522→	return errInvalidActionType
   523→}
