     1→import React, { Children, forwardRef, useCallback, useState } from 'react';
     2→import { AccordionPropTypes } from './propTypes';
     3→import { Box } from '../Box';
     4→
     5→import { AccordionContext } from './AccordionContext';
     6→
     7→const activeAsArray = (active) =>
     8→  typeof active === 'number' ? [active] : active;
     9→
    10→const Accordion = forwardRef(
    11→  (
    12→    { activeIndex, animate = true, children, multiple, onActive, ...rest },
    13→    ref,
    14→  ) => {
    15→    const [activeIndexes, setActiveIndexes] = useState([]);
    16→    const [stateActiveIndex, setStateActiveIndex] = useState();
    17→
    18→    // Derived state from props
    19→    // https://reactjs.org/docs/hooks-faq.html#how-do-i-implement-getderivedstatefromprops
    20→    const derivedActiveIndexes = activeAsArray(activeIndex) || [];
    21→    if (
    22→      (typeof activeIndex !== 'undefined' ||
    23→        activeIndex !== stateActiveIndex) &&
    24→      derivedActiveIndexes.join() !== activeIndexes.join()
    25→    ) {
    26→      setActiveIndexes(derivedActiveIndexes);
    27→      setStateActiveIndex(activeIndex);
    28→    }
    29→
    30→    const getAccordionContext = useCallback(
    31→      (index) => {
    32→        const onPanelChange = (nextIndex) => {
    33→          let nextActiveIndexes = [...(activeIndexes || [])];
    34→
    35→          const nextActiveIndex = nextActiveIndexes.indexOf(nextIndex);
    36→          if (nextActiveIndex > -1) {
    37→            nextActiveIndexes.splice(nextActiveIndex, 1);
    38→          } else if (multiple) {
    39→            nextActiveIndexes.push(nextIndex);
    40→          } else {
    41→            nextActiveIndexes = [nextIndex];
    42→          }
    43→
    44→          setActiveIndexes(nextActiveIndexes);
    45→          if (onActive) {
    46→            onActive(nextActiveIndexes);
    47→          }
    48→        };
    49→
    50→        return {
    51→          active: activeIndexes.indexOf(index) > -1,
    52→          animate,
    53→          onPanelChange: () => onPanelChange(index),
    54→        };
    55→      },
    56→      [activeIndexes, animate, multiple, onActive],
    57→    );
    58→
    59→    return (
    60→      <Box ref={ref} {...rest}>
    61→        {Children.toArray(children)
    62→          .filter((child) => child)
    63→          .map((child, index) => (
    64→            <AccordionContext.Provider
    65→              // eslint-disable-next-line react/no-array-index-key
    66→              key={index}
    67→              value={getAccordionContext(index)}
    68→            >
    69→              {child}
    70→            </AccordionContext.Provider>
    71→          ))}
    72→      </Box>
    73→    );
    74→  },
    75→);
    76→
