   392→  @Override
   393→  @SuppressWarnings({"PMD.CyclomaticComplexity", "PMD.NPathComplexity", "PMD.ExcessiveMethodLength"})
   394→  public String toString() {
   395→
   396→    StringBuilder b = new StringBuilder();
   397→
   398→    if (operation== AlterOperation.UNSPECIFIC) {
   399→        b.append(optionalSpecifier);
   400→    } else if (operation== AlterOperation.RENAME_TABLE) {
   401→
   402→      b.append("RENAME TO ").append(newTableName);
   403→    } else if (operation== AlterOperation.DROP_PRIMARY_KEY) {
   404→
   405→      b.append("DROP PRIMARY KEY ");
   406→    } else if (operation== AlterOperation.DROP_UNIQUE) {
   407→
   408→      b.append("DROP UNIQUE (").append(PlainSelect.getStringList(pkColumns)).append(')');
   409→    } else if (operation== AlterOperation.DROP_FOREIGN_KEY) {
   410→
   411→      b.append("DROP FOREIGN KEY (").append(PlainSelect.getStringList(pkColumns)).append(')');
   412→    } else if (operation== AlterOperation.DROP && columnName==null && pkColumns!=null && pkColumns.size()>0) {
   413→      // Oracle Multi Column Drop
   414→      b.append("DROP (").append(PlainSelect.getStringList(pkColumns)).append(')');
   415→    } else {
   416→        b.append(operation).append(" ");
   417→
   418→        if (commentText != null) {
   419→          if (columnName != null) {
   420→            b.append(columnName).append(" COMMENT ");
   421→          }
   422→          b.append(commentText);
   423→        } else if (columnName != null) {
   424→          if (hasColumn) {
   425→            b.append("COLUMN ");
   426→          }
   427→          if (usingIfExists) {
   428→            b.append("IF EXISTS ");
   429→          }
   430→          if (operation == AlterOperation.RENAME) {
   431→            b.append(columnOldName).append(" TO ");
   432→          }
   433→          b.append(columnName);
   434→        } else if (getColDataTypeList() != null) {
   435→          if (operation == AlterOperation.CHANGE) {
   436→            if (optionalSpecifier != null) {
   437→              b.append(optionalSpecifier).append(" ");
   438→            }
   439→            b.append(columnOldName).append(" ");
   440→          } else if (colDataTypeList.size() > 1) {
   441→            b.append("(");
   442→          } else {
   443→            if (hasColumn) {
   444→              b.append("COLUMN ");
   445→            }
   446→          }
   447→          if (useBrackets && colDataTypeList.size() == 1){
   448→            b.append(" ( ");
   449→          }
   450→          b.append(PlainSelect.getStringList(colDataTypeList));
   451→          if (useBrackets && colDataTypeList.size() == 1 ){
   452→            b.append(" ) ");
   453→          }
   454→          if (colDataTypeList.size() > 1) {
   455→            b.append(")");
   456→          }
   457→        } else if (getColumnDropNotNullList() != null) {
   458→          b.append("COLUMN ");
   459→          b.append(PlainSelect.getStringList(columnDropNotNullList));
   460→        } else if ( columnDropDefaultList != null && !columnDropDefaultList.isEmpty() ) {
   461→          b.append("COLUMN ");
   462→          b.append(PlainSelect.getStringList(columnDropDefaultList));
   463→        } else if (constraintName != null) {
   464→          b.append("CONSTRAINT ");
   465→          if (usingIfExists) {
   466→            b.append("IF EXISTS ");
   467→          }
   468→          b.append(constraintName);
   469→        } else if (pkColumns != null) {
   470→          b.append("PRIMARY KEY (").append(PlainSelect.getStringList(pkColumns)).append(')');
   471→        } else if (ukColumns != null) {
   472→          b.append("UNIQUE");
   473→          if (ukName != null) {
   474→            if (getUk()) {
   475→              b.append(" KEY ");
   476→            } else {
   477→              b.append(" INDEX ");
   478→            }
   479→            b.append(ukName);
   480→          }
   481→          b.append(" (").append(PlainSelect.getStringList(ukColumns)).append(")");
   482→        } else if (fkColumns != null) {
   483→          b.append("FOREIGN KEY (")
   484→              .append(PlainSelect.getStringList(fkColumns))
   485→              .append(") REFERENCES ")
   486→              .append(
   487→                  fkSourceSchema != null && fkSourceSchema.trim().length() > 0
   488→                      ? fkSourceSchema + "."
   489→                      : "")
   490→              .append(fkSourceTable)
   491→              .append(" (")
   492→              .append(PlainSelect.getStringList(fkSourceColumns))
   493→              .append(")");
   494→          referentialActions.forEach(b::append);
   495→        } else if (index != null) {
   496→          b.append(index);
   497→        }
   498→
   499→
   500→        if (getConstraints() != null && !getConstraints().isEmpty()) {
   501→          b.append(' ').append(PlainSelect.getStringList(constraints, false, false));
   502→        }
   503→        if (getUseEqual()) {
   504→          b.append('=');
   505→        }
   506→    }
   507→
   508→    if (parameters != null && !parameters.isEmpty()) {
   509→      b.append(' ').append(PlainSelect.getStringList(parameters, false, false));
   510→    }
   511→
   512→    return b.toString();
   513→  }
