{"file_path": "/workspace/JSqlParser/reproduce_issue.java", "content": "import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.alter.Alter;
import net.sf.jsqlparser.statement.alter.AlterExpression;

public class reproduce_issue {
    public static void main(String[] args) {
        long startTime = System.currentTimeMillis();
        long timeout = 60000; // 60 seconds timeout

        System.out.println("Testing MySQL ALTER TABLE ADD KEY with COMMENT clause...");

        String[] testCases = {
            "alter table `student` add key `idx_name` (`name`) comment 'index name'",
            "alter table student add index idx_name (name) comment 'index comment'",
            "alter table student add unique key idx_name (name) comment 'unique index'",
            "alter table student add key idx_multi (name, age) comment 'multi-column index'",
            "alter table student add unique index idx_name (name) comment 'unique index'",
            "alter table student add constraint idx_name unique key (name) comment 'constraint unique'"
        };

        for (int i = 0; i < testCases.length; i++) {
            if (System.currentTimeMillis() - startTime > timeout) {
                System.out.println("TIMEOUT: Script exceeded 60 seconds");
                System.exit(1);
            }

            String sql = testCases[i];
            System.out.println("\nTest " + (i+1) + ": " + sql);
            try {
                Statement stmt = CCJSqlParserUtil.parse(sql);
                Alter alter = (Alter) stmt;
                System.out.println("✓ SUCCESS: Parsed successfully");
                System.out.println("  Result: " + stmt);

                // Check if comment is present
                if (alter.getAlterExpressions() != null && !alter.getAlterExpressions().isEmpty()) {
                    AlterExpression exp = alter.getAlterExpressions().get(0);
                    if (exp.getIndex() != null) {
                        System.out.println("  Index: " + exp.getIndex());
                    }
                    System.out.println("  Comment: " + exp.getCommentText());
                }
            } catch (Exception e) {
                System.out.println("✗ FAILED: " + e.getClass().getSimpleName() + ": " + e.getMessage());
                e.printStackTrace();
            }
        }

        long elapsed = System.currentTimeMillis() - startTime;
        System.out.println("\n\nCompleted in " + elapsed + "ms");
    }
}
"}

