{"file_path": "/workspace/JSqlParser/test_edge_cases.java", "content": "import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.alter.Alter;
import net.sf.jsqlparser.statement.alter.AlterExpression;

public class test_edge_cases {
    public static void main(String[] args) {
        long startTime = System.currentTimeMillis();
        long timeout = 60000; // 60 seconds timeout

        System.out.println("Testing edge cases for ALTER TABLE ADD KEY with COMMENT...");

        String[] testCases = {
            // Basic tests from the issue
            "alter table `student` add key `idx_name` (`name`) comment 'index name'",

            // Different comment formats
            "alter table student add key idx_name (name) comment \"double quoted\"",
            "alter table student add key idx_name (name) comment 'comment with ''escaped quote'''",

            // Case variations
            "ALTER TABLE student ADD KEY idx_name (name) COMMENT 'uppercase'",

            // PRIMARY KEY with comment
            "alter table student add primary key (id) comment 'primary key comment'",
            "alter table student add constraint pk_student primary key (id) comment 'pk comment'",

            // Multi-column index
            "alter table student add key idx_multi (name, age, grade) comment 'three columns'",
            "alter table student add unique key idx_multi (name, age) comment 'unique multi-column'",

            // Without comment (should still work)
            "alter table student add key idx_plain (name)",
            "alter table student add unique key idx_plain (name)",

            // With USING clause
            "alter table student add key idx_name (name) using btree comment 'with using'",

            // Fulltext and spatial
            "alter table student add fulltext key idx_fulltext (name) comment 'fulltext index'",
            "alter table student add spatial key idx_spatial (location) comment 'spatial index'"
        };

        int passed = 0;
        int failed = 0;

        for (int i = 0; i < testCases.length; i++) {
            if (System.currentTimeMillis() - startTime > timeout) {
                System.out.println("TIMEOUT: Script exceeded 60 seconds");
                System.exit(1);
            }

            String sql = testCases[i];
            System.out.println("\nTest " + (i+1) + ": " + sql);
            try {
                Statement stmt = CCJSqlParserUtil.parse(sql);
                System.out.println("✓ SUCCESS");
                System.out.println("  Result: " + stmt);
                passed++;
            } catch (Exception e) {
                System.out.println("✗ FAILED: " + e.getMessage());
                failed++;
            }
        }

        long elapsed = System.currentTimeMillis() - startTime;
        System.out.println("\n\n=== Summary ===");
        System.out.println("Passed: " + passed + "/" + testCases.length);
        System.out.println("Failed: " + failed + "/" + testCases.length);
        System.out.println("Completed in " + elapsed + "ms");

        if (failed > 0) {
            System.exit(1);
        }
    }
}
"}

