     7→import * as fs from 'fs/promises';
     8→import * as path from 'path';
     9→import { PartListUnion, PartUnion } from '@google/genai';
    10→import {
    11→  Config,
    12→  getErrorMessage,
    13→  isNodeError,
    14→  unescapePath,
    15→} from '@google/gemini-cli-core';
    16→import {
    17→  HistoryItem,
    18→  IndividualToolCallDisplay,
    19→  ToolCallStatus,
    20→} from '../types.js';
    21→import { UseHistoryManagerReturn } from './useHistoryManager.js';
    22→
    23→interface HandleAtCommandParams {
    24→  query: string;
    25→  config: Config;
    26→  addItem: UseHistoryManagerReturn['addItem'];
    27→  onDebugMessage: (message: string) => void;
    28→  messageId: number;
    29→  signal: AbortSignal;
    30→}
    31→
    32→interface HandleAtCommandResult {
    33→  processedQuery: PartListUnion | null;
    34→  shouldProceed: boolean;
    35→}
    36→
    37→interface AtCommandPart {
    38→  type: 'text' | 'atPath';
    39→  content: string;
    40→}
    41→
    42→/**
    43→ * Parses a query string to find all '@<path>' commands and text segments.
    44→ * Handles \ escaped spaces within paths.
    45→ */
    46→function parseAllAtCommands(query: string): AtCommandPart[] {
    47→  const parts: AtCommandPart[] = [];
    48→  let currentIndex = 0;
    49→
    50→  while (currentIndex < query.length) {
    51→    let atIndex = -1;
    52→    let nextSearchIndex = currentIndex;
    53→    // Find next unescaped '@'
    54→    while (nextSearchIndex < query.length) {
    55→      if (
    56→        query[nextSearchIndex] === '@' &&
    57→        (nextSearchIndex === 0 || query[nextSearchIndex - 1] !== '\\')
    58→      ) {
    59→        atIndex = nextSearchIndex;
    60→        break;
    61→      }
    62→      nextSearchIndex++;
    63→    }
    64→
    65→    if (atIndex === -1) {
    66→      // No more @
    67→      if (currentIndex < query.length) {
    68→        parts.push({ type: 'text', content: query.substring(currentIndex) });
    69→      }
    70→      break;
    71→    }
    72→
    73→    // Add text before @
    74→    if (atIndex > currentIndex) {
    75→      parts.push({
    76→        type: 'text',
    77→        content: query.substring(currentIndex, atIndex),
    78→      });
    79→    }
    80→
    81→    // Parse @path
    82→    let pathEndIndex = atIndex + 1;
    83→    let inEscape = false;
    84→    while (pathEndIndex < query.length) {
    85→      const char = query[pathEndIndex];
    86→      if (inEscape) {
    87→        inEscape = false;
    88→      } else if (char === '\\') {
    89→        inEscape = true;
    90→      } else if (/\s/.test(char)) {
    91→        // Path ends at first whitespace not escaped
    92→        break;
    93→      }
    94→      pathEndIndex++;
    95→    }
    96→    const rawAtPath = query.substring(atIndex, pathEndIndex);
    97→    // unescapePath expects the @ symbol to be present, and will handle it.
    98→    const atPath = unescapePath(rawAtPath);
    99→    parts.push({ type: 'atPath', content: atPath });
   100→    currentIndex = pathEndIndex;
   101→  }
   102→  // Filter out empty text parts that might result from consecutive @paths or leading/trailing spaces
   103→  return parts.filter(
   104→    (part) => !(part.type === 'text' && part.content.trim() === ''),
   105→  );
   106→}
   107→
   108→/**
   109→ * Processes user input potentially containing one or more '@<path>' commands.
   110→ * If found, it attempts to read the specified files/directories using the
   111→ * 'read_many_files' tool. The user query is modified to include resolved paths,
   112→ * and the content of the files is appended in a structured block.
   113→ *
   114→ * @returns An object indicating whether the main hook should proceed with an
   115→ *          LLM call and the processed query parts (including file content).
   116→ */
   117→export async function handleAtCommand({
   118→  query,
   119→  config,
   120→  addItem,
   121→  onDebugMessage,
   122→  messageId: userMessageTimestamp,
   123→  signal,
   124→}: HandleAtCommandParams): Promise<HandleAtCommandResult> {
   125→  const commandParts = parseAllAtCommands(query);
   126→  const atPathCommandParts = commandParts.filter(
   127→    (part) => part.type === 'atPath',
   128→  );
   129→
   130→  if (atPathCommandParts.length === 0) {
   131→    addItem({ type: 'user', text: query }, userMessageTimestamp);
   132→    return { processedQuery: [{ text: query }], shouldProceed: true };
   133→  }
   134→
   135→  addItem({ type: 'user', text: query }, userMessageTimestamp);
   136→
   137→  // Get centralized file discovery service
   138→  const fileDiscovery = config.getFileService();
   139→  const respectGitIgnore = config.getFileFilteringRespectGitIgnore();
   140→
   141→  const pathSpecsToRead: string[] = [];
   142→  const atPathToResolvedSpecMap = new Map<string, string>();
   143→  const contentLabelsForDisplay: string[] = [];
   144→  const ignoredPaths: string[] = [];
   145→
   146→  const toolRegistry = await config.getToolRegistry();
   147→  const readManyFilesTool = toolRegistry.getTool('read_many_files');
   148→  const globTool = toolRegistry.getTool('glob');
   149→
   150→  if (!readManyFilesTool) {
   151→    addItem(
   152→      { type: 'error', text: 'Error: read_many_files tool not found.' },
   153→      userMessageTimestamp,
   154→    );
   155→    return { processedQuery: null, shouldProceed: false };
   156→  }
   157→
   158→  for (const atPathPart of atPathCommandParts) {
   159→    const originalAtPath = atPathPart.content; // e.g., "@file.txt" or "@"
   160→
   161→    if (originalAtPath === '@') {
   162→      onDebugMessage(
   163→        'Lone @ detected, will be treated as text in the modified query.',
   164→      );
   165→      continue;
   166→    }
   167→
   168→    const pathName = originalAtPath.substring(1);
   169→    if (!pathName) {
   170→      // This case should ideally not be hit if parseAllAtCommands ensures content after @
   171→      // but as a safeguard:
   172→      addItem(
   173→        {
   174→          type: 'error',
   175→          text: `Error: Invalid @ command '${originalAtPath}'. No path specified.`,
   176→        },
   177→        userMessageTimestamp,
   178→      );
   179→      // Decide if this is a fatal error for the whole command or just skip this @ part
   180→      // For now, let's be strict and fail the command if one @path is malformed.
   181→      return { processedQuery: null, shouldProceed: false };
   182→    }
   183→
   184→    // Check if path should be ignored by git
   185→    if (fileDiscovery.shouldGitIgnoreFile(pathName)) {
   186→      const reason = respectGitIgnore
   187→        ? 'git-ignored and will be skipped'
   188→        : 'ignored by custom patterns';
   189→      onDebugMessage(`Path ${pathName} is ${reason}.`);
   190→      ignoredPaths.push(pathName);
   191→      continue;
   192→    }
   193→
   194→    let currentPathSpec = pathName;
   195→    let resolvedSuccessfully = false;
   196→
   197→    try {
   198→      const absolutePath = path.resolve(config.getTargetDir(), pathName);
   199→      const stats = await fs.stat(absolutePath);
   200→      if (stats.isDirectory()) {
   201→        currentPathSpec = pathName.endsWith('/')
   202→          ? `${pathName}**`
   203→          : `${pathName}/**`;
   204→        onDebugMessage(
   205→          `Path ${pathName} resolved to directory, using glob: ${currentPathSpec}`,
   206→        );
   207→      } else {
   208→        onDebugMessage(`Path ${pathName} resolved to file: ${currentPathSpec}`);
   209→      }
   210→      resolvedSuccessfully = true;
   211→    } catch (error) {
   212→      if (isNodeError(error) && error.code === 'ENOENT') {
   213→        if (config.getEnableRecursiveFileSearch() && globTool) {
   214→          onDebugMessage(
   215→            `Path ${pathName} not found directly, attempting glob search.`,
   216→          );
   217→          try {
   218→            const globResult = await globTool.execute(
   219→              { pattern: `**/*${pathName}*`, path: config.getTargetDir() },
   220→              signal,
   221→            );
   222→            if (
   223→              globResult.llmContent &&
   224→              typeof globResult.llmContent === 'string' &&
   225→              !globResult.llmContent.startsWith('No files found') &&
   226→              !globResult.llmContent.startsWith('Error:')
   227→            ) {
   228→              const lines = globResult.llmContent.split('\n');
   229→              if (lines.length > 1 && lines[1]) {
   230→                const firstMatchAbsolute = lines[1].trim();
   231→                currentPathSpec = path.relative(
   232→                  config.getTargetDir(),
   233→                  firstMatchAbsolute,
   234→                );
   235→                onDebugMessage(
   236→                  `Glob search for ${pathName} found ${firstMatchAbsolute}, using relative path: ${currentPathSpec}`,
   237→                );
   238→                resolvedSuccessfully = true;
   239→              } else {
   240→                onDebugMessage(
   241→                  `Glob search for '**/*${pathName}*' did not return a usable path. Path ${pathName} will be skipped.`,
   242→                );
   243→              }
   244→            } else {
   245→              onDebugMessage(
   246→                `Glob search for '**/*${pathName}*' found no files or an error. Path ${pathName} will be skipped.`,
   247→              );
   248→            }
   249→          } catch (globError) {
   250→            console.error(
   251→              `Error during glob search for ${pathName}: ${getErrorMessage(globError)}`,
   252→            );
   253→            onDebugMessage(
   254→              `Error during glob search for ${pathName}. Path ${pathName} will be skipped.`,
   255→            );
   256→          }
   257→        } else {
   258→          onDebugMessage(
   259→            `Glob tool not found. Path ${pathName} will be skipped.`,
   260→          );
   261→        }
   262→      } else {
   263→        console.error(
   264→          `Error stating path ${pathName}: ${getErrorMessage(error)}`,
   265→        );
   266→        onDebugMessage(
   267→          `Error stating path ${pathName}. Path ${pathName} will be skipped.`,
   268→        );
   269→      }
   270→    }
   271→
   272→    if (resolvedSuccessfully) {
   273→      pathSpecsToRead.push(currentPathSpec);
   274→      atPathToResolvedSpecMap.set(originalAtPath, currentPathSpec);
   275→      contentLabelsForDisplay.push(pathName);
   276→    }
   277→  }
   278→
   279→  // Construct the initial part of the query for the LLM
   280→  let initialQueryText = '';
   281→  for (let i = 0; i < commandParts.length; i++) {
   282→    const part = commandParts[i];
   283→    if (part.type === 'text') {
   284→      initialQueryText += part.content;
   285→    } else {
   286→      // type === 'atPath'
   287→      const resolvedSpec = atPathToResolvedSpecMap.get(part.content);
   288→      if (
   289→        i > 0 &&
   290→        initialQueryText.length > 0 &&
   291→        !initialQueryText.endsWith(' ') &&
   292→        resolvedSpec
   293→      ) {
   294→        // Add space if previous part was text and didn't end with space, or if previous was @path
   295→        const prevPart = commandParts[i - 1];
   296→        if (
   297→          prevPart.type === 'text' ||
   298→          (prevPart.type === 'atPath' &&
   299→            atPathToResolvedSpecMap.has(prevPart.content))
   300→        ) {
   301→          initialQueryText += ' ';
   302→        }
   303→      }
   304→      if (resolvedSpec) {
   305→        initialQueryText += `@${resolvedSpec}`;
   306→      } else {
   307→        // If not resolved for reading (e.g. lone @ or invalid path that was skipped),
   308→        // add the original @-string back, ensuring spacing if it's not the first element.
   309→        if (
   310→          i > 0 &&
   311→          initialQueryText.length > 0 &&
   312→          !initialQueryText.endsWith(' ') &&
   313→          !part.content.startsWith(' ')
   314→        ) {
   315→          initialQueryText += ' ';
   316→        }
   317→        initialQueryText += part.content;
   318→      }
   319→    }
   320→  }
   321→  initialQueryText = initialQueryText.trim();
   322→
   323→  // Inform user about ignored paths
   324→  if (ignoredPaths.length > 0) {
   325→    const ignoreType = respectGitIgnore ? 'git-ignored' : 'custom-ignored';
   326→    onDebugMessage(
   327→      `Ignored ${ignoredPaths.length} ${ignoreType} files: ${ignoredPaths.join(', ')}`,
   328→    );
   329→  }
   330→
   331→  // Fallback for lone "@" or completely invalid @-commands resulting in empty initialQueryText
   332→  if (pathSpecsToRead.length === 0) {
   333→    onDebugMessage('No valid file paths found in @ commands to read.');
   334→    if (initialQueryText === '@' && query.trim() === '@') {
   335→      // If the only thing was a lone @, pass original query (which might have spaces)
   336→      return { processedQuery: [{ text: query }], shouldProceed: true };
   337→    } else if (!initialQueryText && query) {
   338→      // If all @-commands were invalid and no surrounding text, pass original query
   339→      return { processedQuery: [{ text: query }], shouldProceed: true };
   340→    }
   341→    // Otherwise, proceed with the (potentially modified) query text that doesn't involve file reading
   342→    return {
   343→      processedQuery: [{ text: initialQueryText || query }],
   344→      shouldProceed: true,
   345→    };
   346→  }
   347→
   348→  const processedQueryParts: PartUnion[] = [{ text: initialQueryText }];
   349→
   350→  const toolArgs = {
   351→    paths: pathSpecsToRead,
   352→    respectGitIgnore, // Use configuration setting
   353→  };
   354→  let toolCallDisplay: IndividualToolCallDisplay;
   355→
   356→  try {
   357→    const result = await readManyFilesTool.execute(toolArgs, signal);
   358→    toolCallDisplay = {
   359→      callId: `client-read-${userMessageTimestamp}`,
   360→      name: readManyFilesTool.displayName,
   361→      description: readManyFilesTool.getDescription(toolArgs),
   362→      status: ToolCallStatus.Success,
   363→      resultDisplay:
   364→        result.returnDisplay ||
   365→        `Successfully read: ${contentLabelsForDisplay.join(', ')}`,
   366→      confirmationDetails: undefined,
   367→    };
   368→
   369→    if (Array.isArray(result.llmContent)) {
   370→      const fileContentRegex = /^--- (.*?) ---\n\n([\s\S]*?)\n\n$/;
   371→      processedQueryParts.push({
   372→        text: '\n--- Content from referenced files ---',
   373→      });
   374→      for (const part of result.llmContent) {
   375→        if (typeof part === 'string') {
   376→          const match = fileContentRegex.exec(part);
   377→          if (match) {
   378→            const filePathSpecInContent = match[1]; // This is a resolved pathSpec
   379→            const fileActualContent = match[2].trim();
   380→            processedQueryParts.push({
   381→              text: `\nContent from @${filePathSpecInContent}:\n`,
   382→            });
   383→            processedQueryParts.push({ text: fileActualContent });
   384→          } else {
   385→            processedQueryParts.push({ text: part });
   386→          }
   387→        } else {
   388→          // part is a Part object.
   389→          processedQueryParts.push(part);
   390→        }
   391→      }
   392→      processedQueryParts.push({ text: '\n--- End of content ---' });
   393→    } else {
   394→      onDebugMessage(
   395→        'read_many_files tool returned no content or empty content.',
   396→      );
   397→    }
   398→
   399→    addItem(
   400→      { type: 'tool_group', tools: [toolCallDisplay] } as Omit<
   401→        HistoryItem,
   402→        'id'
   403→      >,
   404→      userMessageTimestamp,
   405→    );
   406→    return { processedQuery: processedQueryParts, shouldProceed: true };
   407→  } catch (error: unknown) {
   408→    toolCallDisplay = {
   409→      callId: `client-read-${userMessageTimestamp}`,
   410→      name: readManyFilesTool.displayName,
   411→      description: readManyFilesTool.getDescription(toolArgs),
   412→      status: ToolCallStatus.Error,
   413→      resultDisplay: `Error reading files (${contentLabelsForDisplay.join(', ')}): ${getErrorMessage(error)}`,
   414→      confirmationDetails: undefined,
   415→    };
   416→    addItem(
   417→      { type: 'tool_group', tools: [toolCallDisplay] } as Omit<
   418→        HistoryItem,
   419→        'id'
   420→      >,
   421→      userMessageTimestamp,
   422→    );
   423→    return { processedQuery: null, shouldProceed: false };
   424→  }
   425→}
