   217→  const handleShellCommand = useCallback(
   218→    (rawQuery: PartListUnion, abortSignal: AbortSignal): boolean => {
   219→      if (typeof rawQuery !== 'string' || rawQuery.trim() === '') {
   220→        return false;
   221→      }
   222→
   223→      const userMessageTimestamp = Date.now();
   224→      addItemToHistory(
   225→        { type: 'user_shell', text: rawQuery },
   226→        userMessageTimestamp,
