   235→      if (!isWindows) {
   236→        let command = rawQuery.trim();
   237→        const pwdFileName = `shell_pwd_${crypto.randomBytes(6).toString('hex')}.tmp`;
   238→        pwdFilePath = path.join(os.tmpdir(), pwdFileName);
   239→        // Ensure command ends with a separator before adding our own.
   240→        if (!command.endsWith(';') && !command.endsWith('&')) {
   241→          command += ';';
   242→        }
   243→        commandToExecute = `{ ${command} }; __code=$?; pwd > "${pwdFilePath}"; exit $__code`;
   244→      }
   245→
   246→      const execPromise = new Promise<void>((resolve) => {
   247→        let lastUpdateTime = 0;
   248→
   249→        onDebugMessage(`Executing in ${targetDir}: ${commandToExecute}`);
   250→        executeShellCommand(
   251→          commandToExecute,
   252→          targetDir,
   253→          abortSignal,
   254→          (streamedOutput) => {
   255→            // Throttle pending UI updates to avoid excessive re-renders.
   256→            if (Date.now() - lastUpdateTime > OUTPUT_UPDATE_INTERVAL_MS) {
   257→              setPendingHistoryItem({ type: 'info', text: streamedOutput });
   258→              lastUpdateTime = Date.now();
   259→            }
   260→          },
   261→          onDebugMessage,
   262→        )
   263→          .then((result) => {
   264→            // TODO(abhipatel12) - Consider updating pending item and using timeout to ensure
   265→            // there is no jump where intermediate output is skipped.
   266→            setPendingHistoryItem(null);
   267→
   268→            let historyItemType: HistoryItemWithoutId['type'] = 'info';
   269→            let mainContent: string;
   270→
   271→            // The context sent to the model utilizes a text tokenizer which means raw binary data is
   272→            // cannot be parsed and understood and thus would only pollute the context window and waste
   273→            // tokens.
   274→            if (isBinary(result.rawOutput)) {
   275→              mainContent =
   276→                '[Command produced binary output, which is not shown.]';
   277→            } else {
   278→              mainContent =
   279→                result.output.trim() || '(Command produced no output)';
   280→            }
   281→
   282→            let finalOutput = mainContent;
   283→
   284→            if (result.error) {
   285→              historyItemType = 'error';
   286→              finalOutput = `${result.error.message}\n${finalOutput}`;
   287→            } else if (result.aborted) {
   288→              finalOutput = `Command was cancelled.\n${finalOutput}`;
   289→            } else if (result.signal) {
   290→              historyItemType = 'error';
   291→              finalOutput = `Command terminated by signal: ${result.signal}.\n${finalOutput}`;
   292→            } else if (result.exitCode !== 0) {
   293→              historyItemType = 'error';
   294→              finalOutput = `Command exited with code ${result.exitCode}.\n${finalOutput}`;
   295→            }
   296→
   297→            if (pwdFilePath && fs.existsSync(pwdFilePath)) {
   298→              const finalPwd = fs.readFileSync(pwdFilePath, 'utf8').trim();
   299→              if (finalPwd && finalPwd !== targetDir) {
   300→                const warning = `WARNING: shell mode is stateless; the directory change to '${finalPwd}' will not persist.`;
   301→                finalOutput = `${warning}\n\n${finalOutput}`;
   302→              }
   303→            }
   304→
   305→            // Add the complete, contextual result to the local UI history.
   306→            addItemToHistory(
   307→              { type: historyItemType, text: finalOutput },
   308→              userMessageTimestamp,
   309→            );
   310→
   311→            // Add the same complete, contextual result to the LLM's history.
   312→            addShellCommandToGeminiHistory(geminiClient, rawQuery, finalOutput);
   313→          })
   314→          .catch((err) => {
   315→            setPendingHistoryItem(null);
   316→            const errorMessage =
   317→              err instanceof Error ? err.message : String(err);
   318→            addItemToHistory(
   319→              {
   320→                type: 'error',
   321→                text: `An unexpected error occurred: ${errorMessage}`,
   322→              },
   323→              userMessageTimestamp,
   324→            );
   325→          })
   326→          .finally(() => {
   327→            if (pwdFilePath && fs.existsSync(pwdFilePath)) {
   328→              fs.unlinkSync(pwdFilePath);
   329→            }
   330→            resolve();
   331→          });
   332→      });
   333→
   334→      onExec(execPromise);
   335→      return true; // Command was initiated
   336→    },
   337→    [
   338→      config,
   339→      onDebugMessage,
   340→      addItemToHistory,
   341→      setPendingHistoryItem,
   342→      onExec,
   343→      geminiClient,
   344→    ],
   345→  );
   346→
   347→  return { handleShellCommand };
   348→};
