    89→  let row = 0;
    90→  while (row < initialLines.length) {
    91→    const lineLength = cpLen(initialLines[row]);
    92→    // Add 1 for the newline character (except for the last line)
    93→    const totalCharsInLineAndNewline =
    94→      lineLength + (row < initialLines.length - 1 ? 1 : 0);
    95→
    96→    if (remainingChars <= lineLength) {
    97→      // Cursor is on this line
    98→      return [row, remainingChars];
    99→    }
   100→    remainingChars -= totalCharsInLineAndNewline;
   101→    row++;
   102→  }
   103→  // Offset is beyond the text, place cursor at the end of the last line
   104→  if (initialLines.length > 0) {
   105→    const lastRow = initialLines.length - 1;
   106→    return [lastRow, cpLen(initialLines[lastRow])];
   107→  }
   108→  return [0, 0]; // Default for empty text
   109→}
   110→
   111→export function offsetToLogicalPos(
   112→  text: string,
   113→  offset: number,
   114→): [number, number] {
   115→  let row = 0;
   116→  let col = 0;
   117→  let currentOffset = 0;
   118→
   119→  if (offset === 0) return [0, 0];
   120→
   121→  const lines = text.split('\n');
   122→  for (let i = 0; i < lines.length; i++) {
   123→    const line = lines[i];
   124→    const lineLength = cpLen(line);
   125→    const lineLengthWithNewline = lineLength + (i < lines.length - 1 ? 1 : 0);
   126→
   127→    if (offset <= currentOffset + lineLength) {
   128→      // Check against lineLength first
   129→      row = i;
   130→      col = offset - currentOffset;
   131→      return [row, col];
   132→    } else if (offset <= currentOffset + lineLengthWithNewline) {
   133→      // Check if offset is the newline itself
   134→      row = i;
   135→      col = lineLength; // Position cursor at the end of the current line content
   136→      // If the offset IS the newline, and it's not the last line, advance to next line, col 0
   137→      if (
   138→        offset === currentOffset + lineLengthWithNewline &&
   139→        i < lines.length - 1
   140→      ) {
   141→        return [i + 1, 0];
   142→      }
   143→      return [row, col]; // Otherwise, it's at the end of the current line content
   144→    }
   145→    currentOffset += lineLengthWithNewline;
   146→  }
   147→
   148→  // If offset is beyond the text length, place cursor at the end of the last line
   149→  // or [0,0] if text is empty
   150→  if (lines.length > 0) {
   151→    row = lines.length - 1;
   152→    col = cpLen(lines[row]);
   153→  } else {
   154→    row = 0;
   155→    col = 0;
   156→  }
   157→  return [row, col];
   158→}
   159→
   160→// Helper to calculate visual lines and map cursor positions
   161→function calculateVisualLayout(
   162→  logicalLines: string[],
   163→  logicalCursor: [number, number],
   164→  viewportWidth: number,
   165→): {
   166→  visualLines: string[];
   167→  visualCursor: [number, number];
   168→  logicalToVisualMap: Array<Array<[number, number]>>; // For each logical line, an array of [visualLineIndex, startColInLogical]
   169→  visualToLogicalMap: Array<[number, number]>; // For each visual line, its [logicalLineIndex, startColInLogical]
   170→} {
   171→  const visualLines: string[] = [];
   172→  const logicalToVisualMap: Array<Array<[number, number]>> = [];
   173→  const visualToLogicalMap: Array<[number, number]> = [];
   174→  let currentVisualCursor: [number, number] = [0, 0];
   175→
   176→  logicalLines.forEach((logLine, logIndex) => {
   177→    logicalToVisualMap[logIndex] = [];
   178→    if (logLine.length === 0) {
   179→      // Handle empty logical line
   180→      logicalToVisualMap[logIndex].push([visualLines.length, 0]);
   181→      visualToLogicalMap.push([logIndex, 0]);
   182→      visualLines.push('');
   183→      if (logIndex === logicalCursor[0] && logicalCursor[1] === 0) {
   184→        currentVisualCursor = [visualLines.length - 1, 0];
   185→      }
   186→    } else {
   187→      // Non-empty logical line
   188→      let currentPosInLogLine = 0; // Tracks position within the current logical line (code point index)
   189→      const codePointsInLogLine = toCodePoints(logLine);
   190→
   191→      while (currentPosInLogLine < codePointsInLogLine.length) {
   192→        let currentChunk = '';
   193→        let currentChunkVisualWidth = 0;
   194→        let numCodePointsInChunk = 0;
   195→        let lastWordBreakPoint = -1; // Index in codePointsInLogLine for word break
   196→        let numCodePointsAtLastWordBreak = 0;
   197→
   198→        // Iterate through code points to build the current visual line (chunk)
   199→        for (let i = currentPosInLogLine; i < codePointsInLogLine.length; i++) {
   200→          const char = codePointsInLogLine[i];
   201→          const charVisualWidth = stringWidth(char);
   202→
   203→          if (currentChunkVisualWidth + charVisualWidth > viewportWidth) {
   204→            // Character would exceed viewport width
   205→            if (
   206→              lastWordBreakPoint !== -1 &&
   207→              numCodePointsAtLastWordBreak > 0 &&
   208→              currentPosInLogLine + numCodePointsAtLastWordBreak < i
   209→            ) {
   210→              // We have a valid word break point to use, and it's not the start of the current segment
   211→              currentChunk = codePointsInLogLine
   212→                .slice(
   213→                  currentPosInLogLine,
   214→                  currentPosInLogLine + numCodePointsAtLastWordBreak,
   215→                )
   216→                .join('');
   217→              numCodePointsInChunk = numCodePointsAtLastWordBreak;
   218→            } else {
   219→              // No word break, or word break is at the start of this potential chunk, or word break leads to empty chunk.
   220→              // Hard break: take characters up to viewportWidth, or just the current char if it alone is too wide.
   221→              if (
   222→                numCodePointsInChunk === 0 &&
   223→                charVisualWidth > viewportWidth
   224→              ) {
   225→                // Single character is wider than viewport, take it anyway
   226→                currentChunk = char;
   227→                numCodePointsInChunk = 1;
   228→              } else if (
   229→                numCodePointsInChunk === 0 &&
   230→                charVisualWidth <= viewportWidth
   231→              ) {
   232→                // This case should ideally be caught by the next iteration if the char fits.
   233→                // If it doesn't fit (because currentChunkVisualWidth was already > 0 from a previous char that filled the line),
   234→                // then numCodePointsInChunk would not be 0.
   235→                // This branch means the current char *itself* doesn't fit an empty line, which is handled by the above.
   236→                // If we are here, it means the loop should break and the current chunk (which is empty) is finalized.
   237→              }
   238→            }
   239→            break; // Break from inner loop to finalize this chunk
   240→          }
   241→
   242→          currentChunk += char;
   243→          currentChunkVisualWidth += charVisualWidth;
   244→          numCodePointsInChunk++;
   245→
   246→          // Check for word break opportunity (space)
   247→          if (char === ' ') {
   248→            lastWordBreakPoint = i; // Store code point index of the space
   249→            // Store the state *before* adding the space, if we decide to break here.
   250→            numCodePointsAtLastWordBreak = numCodePointsInChunk - 1; // Chars *before* the space
   251→          }
   252→        }
   253→
   254→        // If the inner loop completed without breaking (i.e., remaining text fits)
   255→        // or if the loop broke but numCodePointsInChunk is still 0 (e.g. first char too wide for empty line)
   256→        if (
   257→          numCodePointsInChunk === 0 &&
   258→          currentPosInLogLine < codePointsInLogLine.length
   259→        ) {
   260→          // This can happen if the very first character considered for a new visual line is wider than the viewport.
   261→          // In this case, we take that single character.
   262→          const firstChar = codePointsInLogLine[currentPosInLogLine];
   263→          currentChunk = firstChar;
   264→          numCodePointsInChunk = 1; // Ensure we advance
   265→        }
   266→
   267→        // If after everything, numCodePointsInChunk is still 0 but we haven't processed the whole logical line,
   268→        // it implies an issue, like viewportWidth being 0 or less. Avoid infinite loop.
   269→        if (
   270→          numCodePointsInChunk === 0 &&
   271→          currentPosInLogLine < codePointsInLogLine.length
   272→        ) {
   273→          // Force advance by one character to prevent infinite loop if something went wrong
   274→          currentChunk = codePointsInLogLine[currentPosInLogLine];
   275→          numCodePointsInChunk = 1;
   276→        }
   277→
   278→        logicalToVisualMap[logIndex].push([
   279→          visualLines.length,
   280→          currentPosInLogLine,
   281→        ]);
   282→        visualToLogicalMap.push([logIndex, currentPosInLogLine]);
   283→        visualLines.push(currentChunk);
   284→
   285→        // Cursor mapping logic
   286→        // Note: currentPosInLogLine here is the start of the currentChunk within the logical line.
   287→        if (logIndex === logicalCursor[0]) {
   288→          const cursorLogCol = logicalCursor[1]; // This is a code point index
   289→          if (
   290→            cursorLogCol >= currentPosInLogLine &&
   291→            cursorLogCol < currentPosInLogLine + numCodePointsInChunk // Cursor is within this chunk
   292→          ) {
   293→            currentVisualCursor = [
   294→              visualLines.length - 1,
   295→              cursorLogCol - currentPosInLogLine, // Visual col is also code point index within visual line
   296→            ];
   297→          } else if (
   298→            cursorLogCol === currentPosInLogLine + numCodePointsInChunk &&
   299→            numCodePointsInChunk > 0
   300→          ) {
   301→            // Cursor is exactly at the end of this non-empty chunk
   302→            currentVisualCursor = [
   303→              visualLines.length - 1,
   304→              numCodePointsInChunk,
   305→            ];
   306→          }
   307→        }
   308→
   309→        const logicalStartOfThisChunk = currentPosInLogLine;
   310→        currentPosInLogLine += numCodePointsInChunk;
   311→
   312→        // If the chunk processed did not consume the entire logical line,
   313→        // and the character immediately following the chunk is a space,
   314→        // advance past this space as it acted as a delimiter for word wrapping.
   315→        if (
   316→          logicalStartOfThisChunk + numCodePointsInChunk <
   317→            codePointsInLogLine.length &&
   318→          currentPosInLogLine < codePointsInLogLine.length && // Redundant if previous is true, but safe
   319→          codePointsInLogLine[currentPosInLogLine] === ' '
   320→        ) {
   321→          currentPosInLogLine++;
   322→        }
   323→      }
   324→      // After all chunks of a non-empty logical line are processed,
   325→      // if the cursor is at the very end of this logical line, update visual cursor.
   326→      if (
   327→        logIndex === logicalCursor[0] &&
   328→        logicalCursor[1] === codePointsInLogLine.length // Cursor at end of logical line
   329→      ) {
   330→        const lastVisualLineIdx = visualLines.length - 1;
   331→        if (
   332→          lastVisualLineIdx >= 0 &&
   333→          visualLines[lastVisualLineIdx] !== undefined
   334→        ) {
   335→          currentVisualCursor = [
   336→            lastVisualLineIdx,
   337→            cpLen(visualLines[lastVisualLineIdx]), // Cursor at end of last visual line for this logical line
   338→          ];
   339→        }
   340→      }
   341→    }
   342→  });
   343→
   344→  // If the entire logical text was empty, ensure there's one empty visual line.
   345→  if (
   346→    logicalLines.length === 0 \|\|
   347→    (logicalLines.length === 1 && logicalLines[0] === '')
   348→  ) {
   349→    if (visualLines.length === 0) {
   350→      visualLines.push('');
   351→      if (!logicalToVisualMap[0]) logicalToVisualMap[0] = [];
   352→      logicalToVisualMap[0].push([0, 0]);
   353→      visualToLogicalMap.push([0, 0]);
   354→    }
   355→    currentVisualCursor = [0, 0];
   356→  }
   357→  // Handle cursor at the very end of the text (after all processing)
   358→  // This case might be covered by the loop end condition now, but kept for safety.
   359→  else if (
   360→    logicalCursor[0] === logicalLines.length - 1 &&
   361→    logicalCursor[1] === cpLen(logicalLines[logicalLines.length - 1]) &&
   362→    visualLines.length > 0
   363→  ) {
   364→    const lastVisLineIdx = visualLines.length - 1;
   365→    currentVisualCursor = [lastVisLineIdx, cpLen(visualLines[lastVisLineIdx])];
   366→  }
   367→
   368→  return {
   369→    visualLines,
   370→    visualCursor: currentVisualCursor,
   371→    logicalToVisualMap,
   372→    visualToLogicalMap,
   373→  };
   374→}
   375→
   376→// --- Start of reducer logic ---
   377→
   378→interface TextBufferState {
   379→  lines: string[];
   380→  cursorRow: number;
   381→  cursorCol: number;
   382→  preferredCol: number \| null; // This is visual preferred col
   383→  undoStack: UndoHistoryEntry[];
   384→  redoStack: UndoHistoryEntry[];
   385→  clipboard: string \| null;
   386→  selectionAnchor: [number, number] \| null;
   387→  viewportWidth: number;
   388→}
   389→
   390→const historyLimit = 100;
   391→
   392→type TextBufferAction =
   393→  \| { type: 'set_text'; payload: string; pushToUndo?: boolean }
   394→  \| { type: 'insert'; payload: string }
   395→  \| { type: 'backspace' }
   396→  \| {
   397→      type: 'move';
   398→      payload: {
   399→        dir: Direction;
   400→      };
   401→    }
   402→  \| { type: 'delete' }
   403→  \| { type: 'delete_word_left' }
   404→  \| { type: 'delete_word_right' }
   405→  \| { type: 'kill_line_right' }
   406→  \| { type: 'kill_line_left' }
   407→  \| { type: 'undo' }
   408→  \| { type: 'redo' }
   409→  \| {
   410→      type: 'replace_range';
   411→      payload: {
   412→        startRow: number;
   413→        startCol: number;
   414→        endRow: number;
   415→        endCol: number;
   416→        text: string;
   417→      };
   418→    }
   419→  \| { type: 'move_to_offset'; payload: { offset: number } }
   420→  \| { type: 'create_undo_snapshot' }
   421→  \| { type: 'set_viewport_width'; payload: number };
   422→
   423→export function textBufferReducer(
   424→  state: TextBufferState,
   425→  action: TextBufferAction,
   426→): TextBufferState {
   427→  const pushUndo = (currentState: TextBufferState): TextBufferState => {
   428→    const snapshot = {
   429→      lines: [...currentState.lines],
   430→      cursorRow: currentState.cursorRow,
   431→      cursorCol: currentState.cursorCol,
   432→    };
   433→    const newStack = [...currentState.undoStack, snapshot];
   434→    if (newStack.length > historyLimit) {
   435→      newStack.shift();
   436→    }
   437→    return { ...currentState, undoStack: newStack, redoStack: [] };
   438→  };
   439→
   440→  const currentLine = (r: number): string => state.lines[r] ?? '';
   441→  const currentLineLen = (r: number): number => cpLen(currentLine(r));
   442→
   443→  switch (action.type) {
   444→    case 'set_text': {
   445→      let nextState = state;
   446→      if (action.pushToUndo !== false) {
   447→        nextState = pushUndo(state);
   448→      }
   449→      const newContentLines = action.payload
   450→        .replace(/\r\n?/g, '\n')
   451→        .split('\n');
   452→      const lines = newContentLines.length === 0 ? [''] : newContentLines;
   453→      const lastNewLineIndex = lines.length - 1;
   454→      return {
   455→        ...nextState,
   456→        lines,
   457→        cursorRow: lastNewLineIndex,
   458→        cursorCol: cpLen(lines[lastNewLineIndex] ?? ''),
   459→        preferredCol: null,
   460→      };
   461→    }
   462→
   463→    case 'insert': {
   464→      const nextState = pushUndo(state);
   465→      const newLines = [...nextState.lines];
   466→      let newCursorRow = nextState.cursorRow;
   467→      let newCursorCol = nextState.cursorCol;
   468→
   469→      const currentLine = (r: number) => newLines[r] ?? '';
   470→
   471→      const str = stripUnsafeCharacters(
   472→        action.payload.replace(/\r\n/g, '\n').replace(/\r/g, '\n'),
   473→      );
   474→      const parts = str.split('\n');
   475→      const lineContent = currentLine(newCursorRow);
   476→      const before = cpSlice(lineContent, 0, newCursorCol);
   477→      const after = cpSlice(lineContent, newCursorCol);
   478→
   479→      if (parts.length > 1) {
   480→        newLines[newCursorRow] = before + parts[0];
   481→        const remainingParts = parts.slice(1);
   482→        const lastPartOriginal = remainingParts.pop() ?? '';
   483→        newLines.splice(newCursorRow + 1, 0, ...remainingParts);
   484→        newLines.splice(
   485→          newCursorRow + parts.length - 1,
   486→          0,
   487→          lastPartOriginal + after,
   488→        );
   489→        newCursorRow = newCursorRow + parts.length - 1;
   490→        newCursorCol = cpLen(lastPartOriginal);
   491→      } else {
   492→        newLines[newCursorRow] = before + parts[0] + after;
   493→        newCursorCol = cpLen(before) + cpLen(parts[0]);
   494→      }
   495→
   496→      return {
   497→        ...nextState,
   498→        lines: newLines,
   499→        cursorRow: newCursorRow,
   500→        cursorCol: newCursorCol,
   501→        preferredCol: null,
   502→      };
   503→    }
   504→
   505→    case 'backspace': {
   506→      const nextState = pushUndo(state);
   507→      const newLines = [...nextState.lines];
   508→      let newCursorRow = nextState.cursorRow;
   509→      let newCursorCol = nextState.cursorCol;
   510→
   511→      const currentLine = (r: number) => newLines[r] ?? '';
   512→
   513→      if (newCursorCol === 0 && newCursorRow === 0) return state;
   514→
   515→      if (newCursorCol > 0) {
   516→        const lineContent = currentLine(newCursorRow);
   517→        newLines[newCursorRow] =
   518→          cpSlice(lineContent, 0, newCursorCol - 1) +
   519→          cpSlice(lineContent, newCursorCol);
   520→        newCursorCol--;
   521→      } else if (newCursorRow > 0) {
   522→        const prevLineContent = currentLine(newCursorRow - 1);
   523→        const currentLineContentVal = currentLine(newCursorRow);
   524→        const newCol = cpLen(prevLineContent);
   525→        newLines[newCursorRow - 1] = prevLineContent + currentLineContentVal;
   526→        newLines.splice(newCursorRow, 1);
   527→        newCursorRow--;
   528→        newCursorCol = newCol;
   529→      }
   530→
   531→      return {
   532→        ...nextState,
   533→        lines: newLines,
   534→        cursorRow: newCursorRow,
   535→        cursorCol: newCursorCol,
   536→        preferredCol: null,
   537→      };
   538→    }
   539→
   540→    case 'set_viewport_width': {
   541→      if (action.payload === state.viewportWidth) {
   542→        return state;
   543→      }
   544→      return { ...state, viewportWidth: action.payload };
   545→    }
   546→
   547→    case 'move': {
   548→      const { dir } = action.payload;
   549→      const { lines, cursorRow, cursorCol, viewportWidth } = state;
   550→      const visualLayout = calculateVisualLayout(
   551→        lines,
   552→        [cursorRow, cursorCol],
   553→        viewportWidth,
   554→      );
   555→      const { visualLines, visualCursor, visualToLogicalMap } = visualLayout;
   556→
   557→      let newVisualRow = visualCursor[0];
   558→      let newVisualCol = visualCursor[1];
   559→      let newPreferredCol = state.preferredCol;
   560→
   561→      const currentVisLineLen = cpLen(visualLines[newVisualRow] ?? '');
   562→
   563→      switch (dir) {
   564→        case 'left':
   565→          newPreferredCol = null;
   566→          if (newVisualCol > 0) {
   567→            newVisualCol--;
   568→          } else if (newVisualRow > 0) {
   569→            newVisualRow--;
   570→            newVisualCol = cpLen(visualLines[newVisualRow] ?? '');
   571→          }
   572→          break;
   573→        case 'right':
   574→          newPreferredCol = null;
   575→          if (newVisualCol < currentVisLineLen) {
   576→            newVisualCol++;
   577→          } else if (newVisualRow < visualLines.length - 1) {
   578→            newVisualRow++;
   579→            newVisualCol = 0;
   580→          }
   581→          break;
   582→        case 'up':
   583→          if (newVisualRow > 0) {
   584→            if (newPreferredCol === null) newPreferredCol = newVisualCol;
   585→            newVisualRow--;
   586→            newVisualCol = clamp(
   587→              newPreferredCol,
   588→              0,
   589→              cpLen(visualLines[newVisualRow] ?? ''),
   590→            );
   591→          }
   592→          break;
   593→        case 'down':
   594→          if (newVisualRow < visualLines.length - 1) {
   595→            if (newPreferredCol === null) newPreferredCol = newVisualCol;
   596→            newVisualRow++;
   597→            newVisualCol = clamp(
   598→              newPreferredCol,
   599→              0,
   600→              cpLen(visualLines[newVisualRow] ?? ''),
   601→            );
   602→          }
   603→          break;
   604→        case 'home':
   605→          newPreferredCol = null;
   606→          newVisualCol = 0;
   607→          break;
   608→        case 'end':
   609→          newPreferredCol = null;
   610→          newVisualCol = currentVisLineLen;
   611→          break;
   612→        case 'wordLeft': {
   613→          const { cursorRow, cursorCol, lines } = state;
   614→          if (cursorCol === 0 && cursorRow === 0) return state;
   615→
   616→          let newCursorRow = cursorRow;
   617→          let newCursorCol = cursorCol;
   618→
   619→          if (cursorCol === 0) {
   620→            newCursorRow--;
   621→            newCursorCol = cpLen(lines[newCursorRow] ?? '');
   622→          } else {
   623→            const lineContent = lines[cursorRow];
   624→            const arr = toCodePoints(lineContent);
   625→            let start = cursorCol;
   626→            let onlySpaces = true;
   627→            for (let i = 0; i < start; i++) {
   628→              if (isWordChar(arr[i])) {
   629→                onlySpaces = false;
   630→                break;
   631→              }
   632→            }
   633→            if (onlySpaces && start > 0) {
   634→              start--;
   635→            } else {
   636→              while (start > 0 && !isWordChar(arr[start - 1])) start--;
   637→              while (start > 0 && isWordChar(arr[start - 1])) start--;
   638→            }
   639→            newCursorCol = start;
   640→          }
   641→          return {
   642→            ...state,
   643→            cursorRow: newCursorRow,
   644→            cursorCol: newCursorCol,
   645→            preferredCol: null,
   646→          };
   647→        }
   648→        case 'wordRight': {
   649→          const { cursorRow, cursorCol, lines } = state;
   650→          if (
   651→            cursorRow === lines.length - 1 &&
   652→            cursorCol === cpLen(lines[cursorRow] ?? '')
   653→          ) {
   654→            return state;
   655→          }
   656→
   657→          let newCursorRow = cursorRow;
   658→          let newCursorCol = cursorCol;
   659→          const lineContent = lines[cursorRow] ?? '';
   660→          const arr = toCodePoints(lineContent);
   661→
   662→          if (cursorCol >= arr.length) {
   663→            newCursorRow++;
   664→            newCursorCol = 0;
   665→          } else {
   666→            let end = cursorCol;
   667→            while (end < arr.length && !isWordChar(arr[end])) end++;
   668→            while (end < arr.length && isWordChar(arr[end])) end++;
   669→            newCursorCol = end;
   670→          }
   671→          return {
   672→            ...state,
   673→            cursorRow: newCursorRow,
   674→            cursorCol: newCursorCol,
   675→            preferredCol: null,
   676→          };
   677→        }
   678→        default:
   679→          break;
   680→      }
   681→
   682→      if (visualToLogicalMap[newVisualRow]) {
   683→        const [logRow, logStartCol] = visualToLogicalMap[newVisualRow];
   684→        return {
   685→          ...state,
   686→          cursorRow: logRow,
   687→          cursorCol: clamp(
   688→            logStartCol + newVisualCol,
   689→            0,
   690→            cpLen(state.lines[logRow] ?? ''),
   691→          ),
   692→          preferredCol: newPreferredCol,
   693→        };
   694→      }
   695→      return state;
   696→    }
   697→
   698→    case 'delete': {
   699→      const { cursorRow, cursorCol, lines } = state;
   700→      const lineContent = currentLine(cursorRow);
   701→      if (cursorCol < currentLineLen(cursorRow)) {
   702→        const nextState = pushUndo(state);
   703→        const newLines = [...nextState.lines];
   704→        newLines[cursorRow] =
   705→          cpSlice(lineContent, 0, cursorCol) +
   706→          cpSlice(lineContent, cursorCol + 1);
   707→        return { ...nextState, lines: newLines, preferredCol: null };
   708→      } else if (cursorRow < lines.length - 1) {
   709→        const nextState = pushUndo(state);
   710→        const nextLineContent = currentLine(cursorRow + 1);
   711→        const newLines = [...nextState.lines];
   712→        newLines[cursorRow] = lineContent + nextLineContent;
   713→        newLines.splice(cursorRow + 1, 1);
   714→        return { ...nextState, lines: newLines, preferredCol: null };
   715→      }
   716→      return state;
   717→    }
   718→
   719→    case 'delete_word_left': {
   720→      const { cursorRow, cursorCol } = state;
   721→      if (cursorCol === 0 && cursorRow === 0) return state;
   722→      if (cursorCol === 0) {
   723→        // Act as a backspace
   724→        const nextState = pushUndo(state);
   725→        const prevLineContent = currentLine(cursorRow - 1);
   726→        const currentLineContentVal = currentLine(cursorRow);
   727→        const newCol = cpLen(prevLineContent);
   728→        const newLines = [...nextState.lines];
   729→        newLines[cursorRow - 1] = prevLineContent + currentLineContentVal;
   730→        newLines.splice(cursorRow, 1);
   731→        return {
   732→          ...nextState,
   733→          lines: newLines,
   734→          cursorRow: cursorRow - 1,
   735→          cursorCol: newCol,
   736→          preferredCol: null,
   737→        };
   738→      }
   739→      const nextState = pushUndo(state);
   740→      const lineContent = currentLine(cursorRow);
   741→      const arr = toCodePoints(lineContent);
   742→      let start = cursorCol;
   743→      let onlySpaces = true;
   744→      for (let i = 0; i < start; i++) {
   745→        if (isWordChar(arr[i])) {
   746→          onlySpaces = false;
   747→          break;
   748→        }
   749→      }
   750→      if (onlySpaces && start > 0) {
   751→        start--;
   752→      } else {
   753→        while (start > 0 && !isWordChar(arr[start - 1])) start--;
   754→        while (start > 0 && isWordChar(arr[start - 1])) start--;
   755→      }
   756→      const newLines = [...nextState.lines];
   757→      newLines[cursorRow] =
   758→        cpSlice(lineContent, 0, start) + cpSlice(lineContent, cursorCol);
   759→      return {
   760→        ...nextState,
   761→        lines: newLines,
   762→        cursorCol: start,
   763→        preferredCol: null,
   764→      };
   765→    }
   766→
   767→    case 'delete_word_right': {
   768→      const { cursorRow, cursorCol, lines } = state;
   769→      const lineContent = currentLine(cursorRow);
   770→      const arr = toCodePoints(lineContent);
   771→      if (cursorCol >= arr.length && cursorRow === lines.length - 1)
   772→        return state;
   773→      if (cursorCol >= arr.length) {
   774→        // Act as a delete
   775→        const nextState = pushUndo(state);
   776→        const nextLineContent = currentLine(cursorRow + 1);
   777→        const newLines = [...nextState.lines];
   778→        newLines[cursorRow] = lineContent + nextLineContent;
   779→        newLines.splice(cursorRow + 1, 1);
   780→        return { ...nextState, lines: newLines, preferredCol: null };
   781→      }
   782→      const nextState = pushUndo(state);
   783→      let end = cursorCol;
   784→      while (end < arr.length && !isWordChar(arr[end])) end++;
   785→      while (end < arr.length && isWordChar(arr[end])) end++;
   786→      const newLines = [...nextState.lines];
   787→      newLines[cursorRow] =
   788→        cpSlice(lineContent, 0, cursorCol) + cpSlice(lineContent, end);
   789→      return { ...nextState, lines: newLines, preferredCol: null };
   790→    }
   791→
   792→    case 'kill_line_right': {
   793→      const { cursorRow, cursorCol, lines } = state;
   794→      const lineContent = currentLine(cursorRow);
   795→      if (cursorCol < currentLineLen(cursorRow)) {
   796→        const nextState = pushUndo(state);
   797→        const newLines = [...nextState.lines];
   798→        newLines[cursorRow] = cpSlice(lineContent, 0, cursorCol);
   799→        return { ...nextState, lines: newLines };
   800→      } else if (cursorRow < lines.length - 1) {
   801→        // Act as a delete
   802→        const nextState = pushUndo(state);
   803→        const nextLineContent = currentLine(cursorRow + 1);
   804→        const newLines = [...nextState.lines];
   805→        newLines[cursorRow] = lineContent + nextLineContent;
   806→        newLines.splice(cursorRow + 1, 1);
   807→        return { ...nextState, lines: newLines, preferredCol: null };
   808→      }
   809→      return state;
   810→    }
   811→
   812→    case 'kill_line_left': {
   813→      const { cursorRow, cursorCol } = state;
   814→      if (cursorCol > 0) {
   815→        const nextState = pushUndo(state);
   816→        const lineContent = currentLine(cursorRow);
   817→        const newLines = [...nextState.lines];
   818→        newLines[cursorRow] = cpSlice(lineContent, cursorCol);
   819→        return {
   820→          ...nextState,
   821→          lines: newLines,
   822→          cursorCol: 0,
   823→          preferredCol: null,
   824→        };
   825→      }
   826→      return state;
   827→    }
   828→
   829→    case 'undo': {
   830→      const stateToRestore = state.undoStack[state.undoStack.length - 1];
   831→      if (!stateToRestore) return state;
   832→
   833→      const currentSnapshot = {
   834→        lines: [...state.lines],
   835→        cursorRow: state.cursorRow,
   836→        cursorCol: state.cursorCol,
   837→      };
   838→      return {
   839→        ...state,
   840→        ...stateToRestore,
   841→        undoStack: state.undoStack.slice(0, -1),
   842→        redoStack: [...state.redoStack, currentSnapshot],
   843→      };
   844→    }
   845→
   846→    case 'redo': {
   847→      const stateToRestore = state.redoStack[state.redoStack.length - 1];
   848→      if (!stateToRestore) return state;
   849→
   850→      const currentSnapshot = {
   851→        lines: [...state.lines],
   852→        cursorRow: state.cursorRow,
   853→        cursorCol: state.cursorCol,
   854→      };
   855→      return {
   856→        ...state,
   857→        ...stateToRestore,
   858→        redoStack: state.redoStack.slice(0, -1),
   859→        undoStack: [...state.undoStack, currentSnapshot],
   860→      };
   861→    }
   862→
   863→    case 'replace_range': {
   864→      const { startRow, startCol, endRow, endCol, text } = action.payload;
   865→      if (
   866→        startRow > endRow \|\|
   867→        (startRow === endRow && startCol > endCol) \|\|
   868→        startRow < 0 \|\|
   869→        startCol < 0 \|\|
   870→        endRow >= state.lines.length \|\|
   871→        (endRow < state.lines.length && endCol > currentLineLen(endRow))
   872→      ) {
   873→        return state; // Invalid range
   874→      }
   875→
   876→      const nextState = pushUndo(state);
   877→      const newLines = [...nextState.lines];
   878→
   879→      const sCol = clamp(startCol, 0, currentLineLen(startRow));
   880→      const eCol = clamp(endCol, 0, currentLineLen(endRow));
   881→
   882→      const prefix = cpSlice(currentLine(startRow), 0, sCol);
   883→      const suffix = cpSlice(currentLine(endRow), eCol);
   884→
   885→      const normalisedReplacement = text
   886→        .replace(/\r\n/g, '\n')
   887→        .replace(/\r/g, '\n');
   888→      const replacementParts = normalisedReplacement.split('\n');
   889→
   890→      // Replace the content
   891→      if (startRow === endRow) {
   892→        newLines[startRow] = prefix + normalisedReplacement + suffix;
   893→      } else {
   894→        const firstLine = prefix + replacementParts[0];
   895→        if (replacementParts.length === 1) {
   896→          // Single line of replacement text, but spanning multiple original lines
   897→          newLines.splice(startRow, endRow - startRow + 1, firstLine + suffix);
   898→        } else {
   899→          // Multi-line replacement text
   900→          const lastLine =
   901→            replacementParts[replacementParts.length - 1] + suffix;
   902→          const middleLines = replacementParts.slice(1, -1);
   903→          newLines.splice(
   904→            startRow,
   905→            endRow - startRow + 1,
   906→            firstLine,
   907→            ...middleLines,
   908→            lastLine,
   909→          );
   910→        }
   911→      }
   912→
   913→      const finalCursorRow = startRow + replacementParts.length - 1;
   914→      const finalCursorCol =
   915→        (replacementParts.length > 1 ? 0 : sCol) +
   916→        cpLen(replacementParts[replacementParts.length - 1]);
   917→
   918→      return {
   919→        ...nextState,
   920→        lines: newLines,
   921→        cursorRow: finalCursorRow,
   922→        cursorCol: finalCursorCol,
   923→        preferredCol: null,
   924→      };
   925→    }
   926→
   927→    case 'move_to_offset': {
   928→      const { offset } = action.payload;
   929→      const [newRow, newCol] = offsetToLogicalPos(
   930→        state.lines.join('\n'),
   931→        offset,
   932→      );
   933→      return {
   934→        ...state,
   935→        cursorRow: newRow,
   936→        cursorCol: newCol,
   937→        preferredCol: null,
   938→      };
   939→    }
   940→
   941→    case 'create_undo_snapshot': {
   942→      return pushUndo(state);
   943→    }
   944→
   945→    default: {
   946→      const exhaustiveCheck: never = action;
   947→      console.error(`Unknown action encountered: ${exhaustiveCheck}`);
   948→      return state;
   949→    }
   950→  }
   951→}
   952→
   953→// --- End of reducer logic ---
   954→
   955→export function useTextBuffer({
   956→  initialText = '',
   957→  initialCursorOffset = 0,
   958→  viewport,
   959→  stdin,
   960→  setRawMode,
   961→  onChange,
   962→  isValidPath,
   963→}: UseTextBufferProps): TextBuffer {
   964→  const initialState = useMemo((): TextBufferState => {
   965→    const lines = initialText.split('\n');
   966→    const [initialCursorRow, initialCursorCol] = calculateInitialCursorPosition(
   967→      lines.length === 0 ? [''] : lines,
   968→      initialCursorOffset,
   969→    );
   970→    return {
   971→      lines: lines.length === 0 ? [''] : lines,
   972→      cursorRow: initialCursorRow,
   973→      cursorCol: initialCursorCol,
   974→      preferredCol: null,
   975→      undoStack: [],
   976→      redoStack: [],
   977→      clipboard: null,
   978→      selectionAnchor: null,
   979→      viewportWidth: viewport.width,
   980→    };
   981→  }, [initialText, initialCursorOffset, viewport.width]);
   982→
   983→  const [state, dispatch] = useReducer(textBufferReducer, initialState);
   984→  const { lines, cursorRow, cursorCol, preferredCol, selectionAnchor } = state;
   985→
   986→  const text = useMemo(() => lines.join('\n'), [lines]);
   987→
   988→  const visualLayout = useMemo(
   989→    () =>
   990→      calculateVisualLayout(lines, [cursorRow, cursorCol], state.viewportWidth),
   991→    [lines, cursorRow, cursorCol, state.viewportWidth],
   992→  );
   993→
   994→  const { visualLines, visualCursor } = visualLayout;
   995→
   996→  const [visualScrollRow, setVisualScrollRow] = useState<number>(0);
   997→
   998→  useEffect(() => {
   999→    if (onChange) {
  1000→      onChange(text);
  1001→    }
  1002→  }, [text, onChange]);
  1003→
  1004→  useEffect(() => {
  1005→    dispatch({ type: 'set_viewport_width', payload: viewport.width });
  1006→  }, [viewport.width]);
  1007→
  1008→  // Update visual scroll (vertical)
  1009→  useEffect(() => {
  1010→    const { height } = viewport;
  1011→    let newVisualScrollRow = visualScrollRow;
  1012→
  1013→    if (visualCursor[0] < visualScrollRow) {
  1014→      newVisualScrollRow = visualCursor[0];
  1015→    } else if (visualCursor[0] >= visualScrollRow + height) {
  1016→      newVisualScrollRow = visualCursor[0] - height + 1;
  1017→    }
  1018→    if (newVisualScrollRow !== visualScrollRow) {
  1019→      setVisualScrollRow(newVisualScrollRow);
  1020→    }
  1021→  }, [visualCursor, visualScrollRow, viewport]);
  1022→
  1023→  const insert = useCallback(
  1024→    (ch: string): void => {
  1025→      if (/[\n\r]/.test(ch)) {
  1026→        dispatch({ type: 'insert', payload: ch });
  1027→        return;
  1028→      }
  1029→
  1030→      const minLengthToInferAsDragDrop = 3;
  1031→      if (ch.length >= minLengthToInferAsDragDrop) {
  1032→        let potentialPath = ch;
  1033→        if (
  1034→          potentialPath.length > 2 &&
  1035→          potentialPath.startsWith("'") &&
  1036→          potentialPath.endsWith("'")
  1037→        ) {
  1038→          potentialPath = ch.slice(1, -1);
  1039→        }
  1040→
  1041→        potentialPath = potentialPath.trim();
  1042→        if (isValidPath(unescapePath(potentialPath))) {
  1043→          ch = `@${potentialPath}`;
  1044→        }
  1045→      }
  1046→
  1047→      let currentText = '';
  1048→      for (const char of toCodePoints(ch)) {
  1049→        if (char.codePointAt(0) === 127) {
  1050→          if (currentText.length > 0) {
  1051→            dispatch({ type: 'insert', payload: currentText });
  1052→            currentText = '';
  1053→          }
  1054→          dispatch({ type: 'backspace' });
  1055→        } else {
  1056→          currentText += char;
  1057→        }
  1058→      }
  1059→      if (currentText.length > 0) {
  1060→        dispatch({ type: 'insert', payload: currentText });
  1061→      }
  1062→    },
  1063→    [isValidPath],
  1064→  );
  1065→
  1066→  const newline = useCallback((): void => {
  1067→    dispatch({ type: 'insert', payload: '\n' });
  1068→  }, []);
  1069→
  1070→  const backspace = useCallback((): void => {
  1071→    dispatch({ type: 'backspace' });
  1072→  }, []);
  1073→
  1074→  const del = useCallback((): void => {
  1075→    dispatch({ type: 'delete' });
  1076→  }, []);
  1077→
  1078→  const move = useCallback((dir: Direction): void => {
  1079→    dispatch({ type: 'move', payload: { dir } });
  1080→  }, []);
  1081→
  1082→  const undo = useCallback((): void => {
  1083→    dispatch({ type: 'undo' });
  1084→  }, []);
  1085→
  1086→  const redo = useCallback((): void => {
  1087→    dispatch({ type: 'redo' });
  1088→  }, []);
  1089→
  1090→  const setText = useCallback((newText: string): void => {
  1091→    dispatch({ type: 'set_text', payload: newText });
  1092→  }, []);
  1093→
  1094→  const deleteWordLeft = useCallback((): void => {
  1095→    dispatch({ type: 'delete_word_left' });
  1096→  }, []);
  1097→
  1098→  const deleteWordRight = useCallback((): void => {
  1099→    dispatch({ type: 'delete_word_right' });
  1100→  }, []);
  1101→
  1102→  const killLineRight = useCallback((): void => {
  1103→    dispatch({ type: 'kill_line_right' });
  1104→  }, []);
  1105→
  1106→  const killLineLeft = useCallback((): void => {
  1107→    dispatch({ type: 'kill_line_left' });
  1108→  }, []);
  1109→
  1110→  const openInExternalEditor = useCallback(
  1111→    async (opts: { editor?: string } = {}): Promise<void> => {
  1112→      const editor =
  1113→        opts.editor ??
  1114→        process.env['VISUAL'] ??
  1115→        process.env['EDITOR'] ??
  1116→        (process.platform === 'win32' ? 'notepad' : 'vi');
  1117→      const tmpDir = fs.mkdtempSync(pathMod.join(os.tmpdir(), 'gemini-edit-'));
  1118→      const filePath = pathMod.join(tmpDir, 'buffer.txt');
  1119→      fs.writeFileSync(filePath, text, 'utf8');
  1120→
  1121→      dispatch({ type: 'create_undo_snapshot' });
  1122→
  1123→      const wasRaw = stdin?.isRaw ?? false;
  1124→      try {
  1125→        setRawMode?.(false);
  1126→        const { status, error } = spawnSync(editor, [filePath], {
  1127→          stdio: 'inherit',
  1128→        });
  1129→        if (error) throw error;
  1130→        if (typeof status === 'number' && status !== 0)
  1131→          throw new Error(`External editor exited with status ${status}`);
  1132→
  1133→        let newText = fs.readFileSync(filePath, 'utf8');
  1134→        newText = newText.replace(/\r\n?/g, '\n');
  1135→        dispatch({ type: 'set_text', payload: newText, pushToUndo: false });
  1136→      } catch (err) {
  1137→        console.error('[useTextBuffer] external editor error', err);
  1138→      } finally {
  1139→        if (wasRaw) setRawMode?.(true);
  1140→        try {
  1141→          fs.unlinkSync(filePath);
  1142→        } catch {
  1143→          /* ignore */
  1144→        }
  1145→        try {
  1146→          fs.rmdirSync(tmpDir);
  1147→        } catch {
  1148→          /* ignore */
  1149→        }
  1150→      }
  1151→    },
  1152→    [text, stdin, setRawMode],
  1153→  );
  1154→
  1155→  const handleInput = useCallback(
  1156→    (key: {
  1157→      name: string;
  1158→      ctrl: boolean;
  1159→      meta: boolean;
  1160→      shift: boolean;
  1161→      paste: boolean;
  1162→      sequence: string;
  1163→    }): void => {
  1164→      const { sequence: input } = key;
  1165→
  1166→      if (
  1167→        key.name === 'return' \|\|
  1168→        input === '\r' \|\|
  1169→        input === '\n' \|\|
  1170→        input === '\\\r' // VSCode terminal represents shift + enter this way
  1171→      )
  1172→        newline();
  1173→      else if (key.name === 'left' && !key.meta && !key.ctrl) move('left');
  1174→      else if (key.ctrl && key.name === 'b') move('left');
  1175→      else if (key.name === 'right' && !key.meta && !key.ctrl) move('right');
  1176→      else if (key.ctrl && key.name === 'f') move('right');
  1177→      else if (key.name === 'up') move('up');
  1178→      else if (key.name === 'down') move('down');
  1179→      else if ((key.ctrl \|\| key.meta) && key.name === 'left') move('wordLeft');
  1180→      else if (key.meta && key.name === 'b') move('wordLeft');
  1181→      else if ((key.ctrl \|\| key.meta) && key.name === 'right')
  1182→        move('wordRight');
  1183→      else if (key.meta && key.name === 'f') move('wordRight');
  1184→      else if (key.name === 'home') move('home');
  1185→      else if (key.ctrl && key.name === 'a') move('home');
  1186→      else if (key.name === 'end') move('end');
  1187→      else if (key.ctrl && key.name === 'e') move('end');
  1188→      else if (key.ctrl && key.name === 'w') deleteWordLeft();
  1189→      else if (
  1190→        (key.meta \|\| key.ctrl) &&
  1191→        (key.name === 'backspace' \|\| input === '\x7f')
  1192→      )
  1193→        deleteWordLeft();
  1194→      else if ((key.meta \|\| key.ctrl) && key.name === 'delete')
  1195→        deleteWordRight();
  1196→      else if (
  1197→        key.name === 'backspace' \|\|
  1198→        input === '\x7f' \|\|
  1199→        (key.ctrl && key.name === 'h')
  1200→      )
  1201→        backspace();
  1202→      else if (key.name === 'delete' \|\| (key.ctrl && key.name === 'd')) del();
  1203→      else if (input && !key.ctrl && !key.meta) {
  1204→        insert(input);
  1205→      }
  1206→    },
  1207→    [newline, move, deleteWordLeft, deleteWordRight, backspace, del, insert],
  1208→  );
  1209→
  1210→  const renderedVisualLines = useMemo(
  1211→    () => visualLines.slice(visualScrollRow, visualScrollRow + viewport.height),
  1212→    [visualLines, visualScrollRow, viewport.height],
  1213→  );
  1214→
  1215→  const replaceRange = useCallback(
  1216→    (
  1217→      startRow: number,
  1218→      startCol: number,
  1219→      endRow: number,
  1220→      endCol: number,
  1221→      text: string,
  1222→    ): void => {
  1223→      dispatch({
  1224→        type: 'replace_range',
  1225→        payload: { startRow, startCol, endRow, endCol, text },
  1226→      });
  1227→    },
  1228→    [],
  1229→  );
  1230→
  1231→  const replaceRangeByOffset = useCallback(
  1232→    (startOffset: number, endOffset: number, replacementText: string): void => {
  1233→      const [startRow, startCol] = offsetToLogicalPos(text, startOffset);
  1234→      const [endRow, endCol] = offsetToLogicalPos(text, endOffset);
  1235→      replaceRange(startRow, startCol, endRow, endCol, replacementText);
  1236→    },
  1237→    [text, replaceRange],
  1238→  );
  1239→
  1240→  const moveToOffset = useCallback((offset: number): void => {
  1241→    dispatch({ type: 'move_to_offset', payload: { offset } });
  1242→  }, []);
  1243→
  1244→  const returnValue: TextBuffer = {
  1245→    lines,
  1246→    text,
  1247→    cursor: [cursorRow, cursorCol],
  1248→    preferredCol,
  1249→    selectionAnchor,
  1250→
  1251→    allVisualLines: visualLines,
  1252→    viewportVisualLines: renderedVisualLines,
  1253→    visualCursor,
  1254→    visualScrollRow,
  1255→
  1256→    setText,
  1257→    insert,
  1258→    newline,
  1259→    backspace,
  1260→    del,
  1261→    move,
  1262→    undo,
  1263→    redo,
  1264→    replaceRange,
  1265→    replaceRangeByOffset,
  1266→    moveToOffset,
  1267→    deleteWordLeft,
  1268→    deleteWordRight,
  1269→    killLineRight,
  1270→    killLineLeft,
  1271→    handleInput,
  1272→    openInExternalEditor,
  1273→  };
  1274→  return returnValue;
  1275→}
  1276→
  1277→export interface TextBuffer {
  1278→  // State
