console.log('🔍 Reproducing the Gemini CLI shell mode @ prefix issue...\n');

// Simplified mock of the problematic logic
function currentBehavior(inputText, shellModeActive) {
  const minLength = 3;

  if (inputText.length >= minLength) {
    let potentialPath = inputText.trim();

    // Simple path check - if it has typical path characters
    const looksLikePath = potentialPath.includes('.') || potentialPath.includes('/');

    if (looksLikePath) {
      // ISSUE: Always adds @ regardless of shell mode
      return `@${potentialPath}`;
    }
  }

  return inputText;
}

function proposedFix(inputText, shellModeActive) {
  const minLength = 3;

  if (inputText.length >= minLength) {
    let potentialPath = inputText.trim();

    // Simple path check
    const looksLikePath = potentialPath.includes('.') || potentialPath.includes('/');

    // FIX: Only add @ when NOT in shell mode
    if (looksLikePath && !shellModeActive) {
      return `@${potentialPath}`;
    }
  }

  return inputText;
}

const testInputs = [
  'file.txt',
  './src/main.js',
  '/usr/bin/node',
  'package.json'
];

console.log('=== CURRENT BEHAVIOR (ISSUE) ===');
testInputs.forEach(input => {
  const normal = currentBehavior(input, false);
  const shell = currentBehavior(input, true);
  console.log(`"${input}" -> Normal: "${normal}", Shell: "${shell}" ${shell.startsWith('@') ? '❌ ISSUE!' : '✅'}`);
});

console.log('\n=== PROPOSED FIX ===');
testInputs.forEach(input => {
  const normal = proposedFix(input, false);
  const shell = proposedFix(input, true);
  console.log(`"${input}" -> Normal: "${normal}", Shell: "${shell}" ${!shell.startsWith('@') ? '✅ FIXED!' : '❌'}`);
});

console.log('\n✅ Reproduction completed!');
