function mockTextBufferInsert(inputText, isValidPath, shellModeActive = false) {
  const minLengthToInferAsDragDrop = 3;
  let ch = inputText;

  if (ch.length >= minLengthToInferAsDragDrop) {
    let potentialPath = ch;

    // Handle quoted paths
    if (
      potentialPath.length > 2 &&
      potentialPath.startsWith("'") &&
      potentialPath.endsWith("'")
    ) {
      potentialPath = ch.slice(1, -1);
    }

    potentialPath = potentialPath.trim();

    // FIXED: Only add @ when NOT in shell mode
    if (!shellModeActive && isValidPath(potentialPath)) {
      ch = `@${potentialPath}`;
    }
  }

  return ch;
}

// Simple path validation (mocked)
function isValidPath(path) {
  return path.includes('.') || path.includes('/') || path.includes('\\');
}

