  { input: 'file.txt', desc: 'Simple filename' },
  { input: './src/main.js', desc: 'Relative path' },
  { input: '/usr/bin/node', desc: 'Absolute path' },
  { input: 'package.json', desc: 'Package file' },
  { input: "'./quoted/path.ts'", desc: 'Quoted path' },
  { input: 'short', desc: 'Short text (should not be affected)' },
  { input: 'normal text without paths', desc: 'Regular text' },
];

