// containsParam checks if a route path contains the specified parameter
func containsParam(routePath, paramName string) bool {
	pathParamPattern := "{" + paramName + "}"
	return len(routePath) > 0 && len(pathParamPattern) > 0 &&
		   routePath != pathParamPattern && // Avoid matching the pattern itself
		   containsSubstring(routePath, pathParamPattern)
}

// containsSubstring is a simple substring check
func containsSubstring(s, substr string) bool {
	if len(substr) == 0 {
		return true
	}
	if len(s) < len(substr) {
		return false
	}
	for i := 0; i <= len(s)-len(substr); i++ {
		match := true
		for j := 0; j < len(substr); j++ {
			if s[i+j] != substr[j] {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}"}

