// Test the filterParametersForRoute function logic with various edge cases

// Simulate Parameter struct for testing
type Parameter struct {
	Name string
	In   string
}

// filterParametersForRoute implementation (copied from our fix)
func filterParametersForRoute(parameters []Parameter, routePath string) []Parameter {
	var filteredParams []Parameter

	for _, param := range parameters {
		// For non-path parameters, always include them
		if param.In != "path" {
			filteredParams = append(filteredParams, param)
			continue
		}

		// For path parameters, only include if the parameter name exists in the route path
		pathParamPattern := "{" + param.Name + "}"
		if strings.Contains(routePath, pathParamPattern) {
			filteredParams = append(filteredParams, param)
		}
	}

	return filteredParams
}

func testCase(name string, parameters []Parameter, routePath string) {
	fmt.Printf("=== Test Case: %s ===\n", name)
	fmt.Printf("Route: %s\n", routePath)
	fmt.Printf("Original Parameters:\n")
	for _, p := range parameters {
		fmt.Printf("  - %s (%s)\n", p.Name, p.In)
	}

	filtered := filterParametersForRoute(parameters, routePath)
	fmt.Printf("Filtered Parameters:\n")
	for _, p := range filtered {
		fmt.Printf("  - %s (%s)\n", p.Name, p.In)
	}
	fmt.Println()
}

func main() {
	fmt.Println("=== Testing Edge Cases for filterParametersForRoute ===")
	fmt.Println()

	// Test case 1: Basic multiple routes with different path params
	testCase("Basic Multiple Routes",
		[]Parameter{
			{"group_id", "path"},
			{"user_id", "path"},
			{"limit", "query"},
		},
		"/examples/user/{user_id}/address")

	// Test case 2: Route with no path params
	testCase("Route with No Path Params",
		[]Parameter{
			{"group_id", "path"},
			{"user_id", "path"},
			{"limit", "query"},
			{"format", "header"},
		},
		"/examples/static/endpoint")

	// Test case 3: Route with all path params
	testCase("Route with All Path Params",
		[]Parameter{
			{"group_id", "path"},
			{"user_id", "path"},
			{"limit", "query"},
		},
		"/examples/groups/{group_id}/user/{user_id}/address")

	// Test case 4: Similar parameter names (edge case for substring matching)
	testCase("Similar Parameter Names",
		[]Parameter{
			{"id", "path"},
			{"user_id", "path"},
			{"group_id", "path"},
		},
		"/examples/user/{user_id}/details")

	// Test case 5: Parameter name at the end of route
	testCase("Parameter at End of Route",
		[]Parameter{
			{"resource_id", "path"},
			{"action", "path"},
		},
		"/api/resource/{resource_id}")

	// Test case 6: Multiple occurrences of same parameter pattern
	testCase("Multiple Occurrences Edge Case",
		[]Parameter{
			{"id", "path"},
			{"category", "path"},
		},
		"/api/category/{category}/item/{id}/category/{category}")

	// Test case 7: Empty route
	testCase("Empty Route",
		[]Parameter{
			{"id", "path"},
		},
		"")

	// Test case 8: Route with no curly braces
