   186→
   187→        // hex to binary
   188→        count   = 0 ;
   189→        byte* r = result.pData_;
   190→        int   n = 0 ; // nibble
   191→        for ( long i = 0 ; i < length ; i++ ) {
   192→            if ( value[p[i]] ) {
   193→                int v = value[p[i]]-1 ;
   194→                if ( ++count % 2 ) n = v*16 ; // leading digit
   195→                else *r++ =        n + v    ; // trailing
   196→            }
   197→        }
   198→        return true;
   199→    }
   200→
   201→    std::string upper(const std::string& str)
   202→    {
   203→        std::string result;
   204→        transform(str.begin(), str.end(), std::back_inserter(result), toupper);
   205→        return result;
   206→    }
   207→
   208→    std::string::size_type findi(const std::string& str, const std::string& substr)
   209→    {
   210→        return upper(str).find(upper(substr) );
   211→    }
   212→
   213→    void PngImage::printStructure(std::ostream& out, PrintStructureOption option, int depth)
   214→    {
   215→        if (io_->open() != 0) {
   216→            throw Error(kerDataSourceOpenFailed, io_->path(), strError());
   217→        }
   218→        // Ensure that this is the correct image type
   219→        if (!isPngType(*io_, true)) {
   220→            if (io_->error() || io_->eof()) throw Error(kerFailedToReadImageData);
   221→            throw Error(kerNotAnImage, "PNG");
   222→        }
   223→
   224→        char    chType[5];
   225→        chType[0]=0;
   226→        chType[4]=0;
   227→
   228→        if ( option == kpsBasic || option == kpsXMP || option == kpsIccProfile || option == kpsRecursive ) {
   229→
   230→            const std::string xmpKey  = "XML:com.adobe.xmp";
   231→            const std::string exifKey = "Raw profile type exif";
   232→            const std::string app1Key = "Raw profile type APP1";
   233→            const std::string iptcKey = "Raw profile type iptc";
   234→            const std::string iccKey  = "icc";
   235→            const std::string softKey = "Software";
   236→            const std::string commKey = "Comment";
   237→            const std::string descKey = "Description";
   238→
   239→            bool bPrint = option == kpsBasic || option == kpsRecursive ;
   240→            if ( bPrint ) {
   241→                out << "STRUCTURE OF PNG FILE: " << io_->path() << std::endl;
   242→                out << " address | chunk |  length | data                           | checksum" << std::endl;
   243→            }
   244→
   245→            const long imgSize = (long) io_->size();
   246→            DataBuf    cheaderBuf(8);
   247→
   248→            while( !io_->eof() && ::strcmp(chType,"IEND") ) {
   249→                size_t address = io_->tell();
   250→
   251→                std::memset(cheaderBuf.pData_, 0x0, cheaderBuf.size_);
   252→                long bufRead = io_->read(cheaderBuf.pData_, cheaderBuf.size_);
   253→                if (io_->error()) throw Error(kerFailedToReadImageData);
   254→                if (bufRead != cheaderBuf.size_) throw Error(kerInputDataReadFailed);
   255→
   256→                // Decode chunk data length.
   257→                uint32_t dataOffset = Exiv2::getULong(cheaderBuf.pData_, Exiv2::bigEndian);
   258→                for (int i = 4; i < 8; i++) {
   259→                    chType[i-4]=cheaderBuf.pData_[i];
   260→                }
   261→
   262→                // test that we haven't hit EOF, or wanting to read excessive data
   263→                long restore = io_->tell();
   264→                if(  restore == -1
   265→                ||  dataOffset > uint32_t(0x7FFFFFFF)
   266→                ||  static_cast<long>(dataOffset) > imgSize - restore
   267→                ){
   268→                    throw Exiv2::Error(kerFailedToReadImageData);
   269→                }
   270→
   271→                DataBuf   buff(dataOffset);
   272→                io_->read(buff.pData_,dataOffset);
   273→                io_->seek(restore, BasicIo::beg);
   274→
   275→                // format output
   276→                const int    iMax = 30 ;
   277→                const uint32_t blen = dataOffset > iMax ? iMax : dataOffset ;
   278→                std::string dataString = "";
   279→                // if blen == 0 => slice construction fails
   280→                if (blen > 0) {
   281→                    std::stringstream ss;
   282→                    ss << Internal::binaryToString(makeSlice(buff, 0, blen));
   283→                    dataString = ss.str();
   284→                }
   285→                while (      dataString.size() < iMax ) dataString += ' ';
   286→                dataString = dataString.substr(0,iMax);
   287→
   288→                if ( bPrint ) {
   289→                    io_->seek(dataOffset, BasicIo::cur);// jump to checksum
   290→                    byte checksum[4];
   291→                    io_->read(checksum,4);
   292→                    io_->seek(restore, BasicIo::beg)   ;// restore file pointer
   293→
   294→                    out << Internal::stringFormat("%8d | %-5s |%8d | "
   295→                                                  ,(uint32_t)address, chType,dataOffset)
   296→                        << dataString
   297→                        << Internal::stringFormat(" | 0x%02x%02x%02x%02x"
   298→                                                   ,checksum[0],checksum[1],checksum[2],checksum[3])
   299→                        << std::endl;
   300→                }
   301→
   302→                // chunk type
   303→                bool tEXt  = std::strcmp(chType,"tEXt")== 0;
   304→                bool zTXt  = std::strcmp(chType,"zTXt")== 0;
   305→                bool iCCP  = std::strcmp(chType,"iCCP")== 0;
   306→                bool iTXt  = std::strcmp(chType,"iTXt")== 0;
   307→
   308→                // for XMP, ICC etc: read and format data
   309→                bool bXMP  = option == kpsXMP        && findi(dataString,xmpKey)==0;
   310→                bool bICC  = option == kpsIccProfile && findi(dataString,iccKey)==0;
   311→                bool bExif = option == kpsRecursive  &&(findi(dataString,exifKey)==0 || findi(dataString,app1Key)==0);
   312→                bool bIptc = option == kpsRecursive  && findi(dataString,iptcKey)==0;
   313→                bool bSoft = option == kpsRecursive  && findi(dataString,softKey)==0;
   314→                bool bComm = option == kpsRecursive  && findi(dataString,commKey)==0;
   315→                bool bDesc = option == kpsRecursive  && findi(dataString,descKey)==0;
   316→                bool bDump = bXMP || bICC || bExif || bIptc || bSoft || bComm || bDesc ;
   317→
   318→                if( bDump ) {
   319→                    DataBuf   dataBuf;
   320→                    byte*     data   = new byte[dataOffset+1];
   321→                    data[dataOffset] = 0;
   322→                    io_->read(data,dataOffset);
   323→                    io_->seek(restore, BasicIo::beg);
   324→                    uint32_t  name_l = (uint32_t) std::strlen((const char*)data)+1; // leading string length
   325→                    uint32_t  start  = name_l;
   326→                    bool      bLF    = false;
   327→
   328→                    // decode the chunk
   329→                    bool bGood = false;
   330→                    if ( tEXt ) {
   331→                        bGood = tEXtToDataBuf(data+name_l,dataOffset-name_l,dataBuf);
   332→                    }
   333→                    if ( zTXt || iCCP ) {
   334→                        bGood = zlibToDataBuf(data+name_l+1,dataOffset-name_l-1,dataBuf); // +1 = 'compressed' flag
   335→                    }
   336→                    if ( iTXt ) {
   337→                        bGood = (start+3) < dataOffset ;    // good if not a nul chunk
   338→                    }
   339→
   340→                    // format is content dependent
   341→                    if ( bGood ) {
   342→                        if ( bXMP ) {
   343→                            while ( !data[start] && start < dataOffset) start++; // skip leading nul bytes
   344→                            out <<  data+start;             // output the xmp
   345→                        }
   346→
   347→                        if ( bExif || bIptc ) {
   348→                            DataBuf parsedBuf = PngChunk::readRawProfile(dataBuf,tEXt);
   349→#if DEBUG
   350→                            std::cerr << Exiv2::Internal::binaryToString(parsedBuf.pData_, parsedBuf.size_>50?50:parsedBuf.size_,0) << std::endl;
   351→#endif
   352→                            if ( parsedBuf.size_ ) {
   353→                                if ( bExif ) {
   354→                                    // create memio object with the data, then print the structure
   355→                                    BasicIo::AutoPtr p = BasicIo::AutoPtr(new MemIo(parsedBuf.pData_+6,parsedBuf.size_-6));
   356→                                    printTiffStructure(*p,out,option,depth);
   357→                                }
   358→                                if ( bIptc ) {
   359→                                    IptcData::printStructure(out, makeSlice(parsedBuf.pData_, 0, parsedBuf.size_), depth);
   360→                                }
   361→                            }
   362→                        }
   363→
   364→                        if ( bSoft && dataBuf.size_ > 0) {
   365→                            DataBuf     s(dataBuf.size_+1);               // allocate buffer with an extra byte
   366→                            memcpy(s.pData_,dataBuf.pData_,dataBuf.size_);// copy in the dataBuf
   367→                            s.pData_[dataBuf.size_] = 0 ;                 // nul terminate it
   368→                            const char* str = (const char*) s.pData_;     // give it name
   369→                            out << Internal::indent(depth) << (const char*) buff.pData_ << ": " << str ;
   370→                            bLF=true;
   371→                        }
   372→
   373→                        if ( bICC || bComm ) {
   374→                            out.write((const char*) dataBuf.pData_,dataBuf.size_);
   375→                            bLF = bComm ;
   376→                        }
   377→
   378→                        if ( bDesc && iTXt ) {
   379→                            DataBuf decoded = PngChunk::decodeTXTChunk(buff,PngChunk::iTXt_Chunk );
   380→                            out.write((const char*)decoded.pData_,decoded.size_);
   381→                            bLF = true;
   382→                        }
   383→
   384→                        if ( bLF ) out << std::endl;
   385→                    }
   386→                    delete[] data;
   387→                }
   388→                io_->seek(dataOffset+4, BasicIo::cur);// jump past checksum
   389→                if (io_->error()) throw Error(kerFailedToReadImageData);
   390→            }
   391→        }
   392→    }
   393→
   394→    void PngImage::readMetadata()
   395→    {
   396→#ifdef DEBUG
   397→        std::cerr << "Exiv2::PngImage::readMetadata: Reading PNG file " << io_->path() << std::endl;
   398→#endif
   399→        if (io_->open() != 0)
   400→        {
   401→            throw Error(kerDataSourceOpenFailed, io_->path(), strError());
   402→        }
   403→        IoCloser closer(*io_);
   404→        // Ensure that this is the correct image type
   405→        if (!isPngType(*io_, true))
   406→        {
   407→            if (io_->error() || io_->eof()) throw Error(kerFailedToReadImageData);
   408→            throw Error(kerNotAnImage, "PNG");
   409→        }
   410→        clearMetadata();
   411→
   412→        const long imgSize = (long) io_->size();
   413→        DataBuf cheaderBuf(8);       // Chunk header size : 4 bytes (data size) + 4 bytes (chunk type).
   414→
   415→        while(!io_->eof())
   416→        {
   417→            // Read chunk header.
   418→
   419→#ifdef DEBUG
   420→            std::cout << "Exiv2::PngImage::readMetadata: Position: " << io_->tell() << std::endl;
   421→#endif
   422→            std::memset(cheaderBuf.pData_, 0x0, cheaderBuf.size_);
   423→            long bufRead = io_->read(cheaderBuf.pData_, cheaderBuf.size_);
   424→            if (io_->error()) {
   425→                throw Error(kerFailedToReadImageData);
   426→            }
   427→            if (bufRead != cheaderBuf.size_) {
   428→                throw Error(kerInputDataReadFailed);
   429→            }
   430→
   431→            // Decode chunk data length.
   432→            uint32_t dataOffset = Exiv2::getULong(cheaderBuf.pData_, Exiv2::bigEndian);
   433→            long pos = io_->tell();
   434→            if (pos == -1 ||
   435→                dataOffset > uint32_t(0x7FFFFFFF) ||
   436→                static_cast<long>(dataOffset) > imgSize - pos) {
   437→                throw Exiv2::Error(kerFailedToReadImageData);
   438→            }
   439→
   440→#ifdef DEBUG
   441→            std::string chunkName(reinterpret_cast<char *>(cheaderBuf.pData_) + 4, 4);
   442→            std::cout << "Exiv2::PngImage::readMetadata: chunk name: " << chunkName << std::endl;
   443→#endif
   444→
   445→            // Perform a chunk triage for item that we need.
   446→            if (!memcmp(cheaderBuf.pData_ + 4, "IEND", 4) ||
   447→                !memcmp(cheaderBuf.pData_ + 4, "IHDR", 4) ||
   448→                !memcmp(cheaderBuf.pData_ + 4, "tEXt", 4) ||
   449→                !memcmp(cheaderBuf.pData_ + 4, "zTXt", 4) ||
   450→                !memcmp(cheaderBuf.pData_ + 4, "iTXt", 4) ||
   451→                !memcmp(cheaderBuf.pData_ + 4, "iCCP", 4))
   452→            {
   453→                // Extract chunk data.
   454→
   455→                DataBuf cdataBuf(dataOffset);
   456→                bufRead = io_->read(cdataBuf.pData_, dataOffset);
   457→                if (io_->error()) {
   458→                    throw Error(kerFailedToReadImageData);
   459→                }
   460→                if (bufRead != (long)dataOffset) {
   461→                    throw Error(kerInputDataReadFailed);
   462→                }
   463→
   464→                if (!memcmp(cheaderBuf.pData_ + 4, "IEND", 4))
   465→                {
   466→                    // Last chunk found: we stop parsing.
   467→#ifdef DEBUG
   468→                    std::cout << "Exiv2::PngImage::readMetadata: Found IEND chunk with length: " << dataOffset << std::endl;
   469→#endif
   470→                    return;
   471→                }
   472→                else if (!memcmp(cheaderBuf.pData_ + 4, "IHDR", 4))
   473→                {
   474→#ifdef DEBUG
   475→                    std::cout << "Exiv2::PngImage::readMetadata: Found IHDR chunk with length: " << dataOffset << std::endl;
   476→#endif
   477→                    if (cdataBuf.size_ >= 8) {
   478→                        PngChunk::decodeIHDRChunk(cdataBuf, &pixelWidth_, &pixelHeight_);
   479→                    }
   480→                }
   481→                else if (!memcmp(cheaderBuf.pData_ + 4, "tEXt", 4))
   482→                {
   483→#ifdef DEBUG
   484→                    std::cout << "Exiv2::PngImage::readMetadata: Found tEXt chunk with length: " << dataOffset << std::endl;
   485→#endif
   486→                    PngChunk::decodeTXTChunk(this, cdataBuf, PngChunk::tEXt_Chunk);
   487→                }
   488→                else if (!memcmp(cheaderBuf.pData_ + 4, "zTXt", 4))
   489→                {
   490→#ifdef DEBUG
   491→                    std::cout << "Exiv2::PngImage::readMetadata: Found zTXt chunk with length: " << dataOffset << std::endl;
   492→#endif
   493→                    PngChunk::decodeTXTChunk(this, cdataBuf, PngChunk::zTXt_Chunk);
   494→                }
   495→                else if (!memcmp(cheaderBuf.pData_ + 4, "iTXt", 4))
   496→                {
   497→#ifdef DEBUG
   498→                    std::cout << "Exiv2::PngImage::readMetadata: Found iTXt chunk with length: " << dataOffset << std::endl;
   499→#endif
   500→                    PngChunk::decodeTXTChunk(this, cdataBuf, PngChunk::iTXt_Chunk);
   501→                }
   502→                else if (!memcmp(cheaderBuf.pData_ + 4, "iCCP", 4))
   503→                {
   504→                    zlibToDataBuf(cdataBuf.pData_ +12+1,dataOffset-13,iccProfile_); // +1 = 'compressed' flag
   505→#ifdef DEBUG
   506→                    std::cout << "Exiv2::PngImage::readMetadata: Found iCCP chunk length: " << dataOffset  << std::endl;
   507→                    std::cout << "Exiv2::PngImage::readMetadata: iccProfile.size_ : " << iccProfile_.size_ << std::endl;
   508→#endif
   509→                }
   510→
   511→                // Set dataOffset to null like chunk data have been extracted previously.
   512→                dataOffset = 0;
   513→            }
   514→
   515→            // Move to the next chunk: chunk data size + 4 CRC bytes.
   516→#ifdef DEBUG
   517→            std::cout << "Exiv2::PngImage::readMetadata: Seek to offset: " << dataOffset + 4 << std::endl;
   518→#endif
   519→            io_->seek(dataOffset + 4 , BasicIo::cur);
   520→            if (io_->error() || io_->eof()) {
   521→                throw Error(kerFailedToReadImageData);
   522→            }
   523→        }
   524→
   525→    } // PngImage::readMetadata
