   527→    void PngImage::writeMetadata()
   528→    {
   529→        if (io_->open() != 0)
   530→        {
   531→            throw Error(kerDataSourceOpenFailed, io_->path(), strError());
   532→        }
   533→        IoCloser closer(*io_);
   534→        BasicIo::AutoPtr tempIo(new MemIo);
   535→        assert (tempIo.get() != 0);
   536→
   537→        doWriteMetadata(*tempIo); // may throw
   538→        io_->close();
   539→        io_->transfer(*tempIo); // may throw
   540→
