   542→
   543→    void PngImage::doWriteMetadata(BasicIo& outIo)
   544→    {
   545→        if (!io_->isopen()) throw Error(kerInputDataReadFailed);
   546→        if (!outIo.isopen()) throw Error(kerImageWriteFailed);
   547→
   548→#ifdef DEBUG
   549→        std::cout << "Exiv2::PngImage::doWriteMetadata: Writing PNG file " << io_->path() << "\n";
   550→        std::cout << "Exiv2::PngImage::doWriteMetadata: tmp file created " << outIo.path() << "\n";
   551→#endif
   552→
   553→        // Ensure that this is the correct image type
   554→        if (!isPngType(*io_, true))
   555→        {
   556→            if (io_->error() || io_->eof()) throw Error(kerInputDataReadFailed);
   557→            throw Error(kerNoImageInInputData);
   558→        }
   559→
   560→        // Write PNG Signature.
   561→        if (outIo.write(pngSignature, 8) != 8) throw Error(kerImageWriteFailed);
   562→
   563→        DataBuf cheaderBuf(8);       // Chunk header : 4 bytes (data size) + 4 bytes (chunk type).
   564→
   565→        while(!io_->eof())
   566→        {
   567→            // Read chunk header.
   568→
   569→            std::memset(cheaderBuf.pData_, 0x00, cheaderBuf.size_);
   570→            long bufRead = io_->read(cheaderBuf.pData_, cheaderBuf.size_);
   571→            if (io_->error()) throw Error(kerFailedToReadImageData);
   572→            if (bufRead != cheaderBuf.size_) throw Error(kerInputDataReadFailed);
   573→
   574→            // Decode chunk data length.
   575→
   576→            uint32_t dataOffset = getULong(cheaderBuf.pData_, bigEndian);
   577→            if (dataOffset > 0x7FFFFFFF) throw Exiv2::Error(kerFailedToReadImageData);
   578→
   579→            // Read whole chunk : Chunk header + Chunk data (not fixed size - can be null) + CRC (4 bytes).
   580→
   581→            DataBuf chunkBuf(8 + dataOffset + 4);                     // Chunk header (8 bytes) + Chunk data + CRC (4 bytes).
   582→            memcpy(chunkBuf.pData_, cheaderBuf.pData_, 8);            // Copy header.
   583→            bufRead = io_->read(chunkBuf.pData_ + 8, dataOffset + 4); // Extract chunk data + CRC
   584→            if (io_->error()) throw Error(kerFailedToReadImageData);
   585→            if (bufRead != (long)(dataOffset + 4)) throw Error(kerInputDataReadFailed);
   586→
   587→            char szChunk[5];
   588→            memcpy(szChunk,cheaderBuf.pData_ + 4,4);
   589→            szChunk[4]  = 0;
   590→
   591→            if (!memcmp(cheaderBuf.pData_ + 4, "IEND", 4))
   592→            {
   593→                // Last chunk found: we write it and done.
   594→#ifdef DEBUG
   595→                std::cout << "Exiv2::PngImage::doWriteMetadata: Write IEND chunk (length: " << dataOffset << ")\n";
   596→#endif
   597→                if (outIo.write(chunkBuf.pData_, chunkBuf.size_) != chunkBuf.size_) throw Error(kerImageWriteFailed);
   598→                return;
   599→            }
   600→            else if (!memcmp(cheaderBuf.pData_ + 4, "IHDR", 4))
   601→            {
   602→#ifdef DEBUG
   603→                std::cout << "Exiv2::PngImage::doWriteMetadata: Write IHDR chunk (length: " << dataOffset << ")\n";
   604→#endif
   605→                if (outIo.write(chunkBuf.pData_, chunkBuf.size_) != chunkBuf.size_) throw Error(kerImageWriteFailed);
   606→
   607→                // Write all updated metadata here, just after IHDR.
   608→                if (!comment_.empty())
   609→                {
   610→                    // Update Comment data to a new PNG chunk
   611→                    std::string chunk = PngChunk::makeMetadataChunk(comment_, mdComment);
   612→                    if (outIo.write((const byte*)chunk.data(), static_cast<long>(chunk.size())) != (long)chunk.size())
   613→                    {
   614→                        throw Error(kerImageWriteFailed);
   615→                    }
   616→                }
   617→
   618→                if (exifData_.count() > 0)
   619→                {
   620→                    // Update Exif data to a new PNG chunk
   621→                    Blob blob;
   622→                    ExifParser::encode(blob, littleEndian, exifData_);
   623→                    if (blob.size() > 0)
   624→                    {
   625→                        static const char exifHeader[] = { 0x45, 0x78, 0x69, 0x66, 0x00, 0x00 };
   626→                        std::string rawExif =   std::string(exifHeader, 6)
   627→                                              + std::string((const char*)&blob[0], blob.size());
   628→                        std::string chunk = PngChunk::makeMetadataChunk(rawExif, mdExif);
   629→                        if (outIo.write((const byte*)chunk.data(), static_cast<long>(chunk.size())) != (long)chunk.size())
   630→                        {
   631→                            throw Error(kerImageWriteFailed);
   632→                        }
   633→                    }
   634→                }
   635→
   636→                if (iptcData_.count() > 0)
   637→                {
   638→                    // Update IPTC data to a new PNG chunk
   639→                    DataBuf newPsData = Photoshop::setIptcIrb(0, 0, iptcData_);
   640→                    if (newPsData.size_ > 0)
   641→                    {
   642→                        std::string rawIptc((const char*)newPsData.pData_, newPsData.size_);
   643→                        std::string chunk = PngChunk::makeMetadataChunk(rawIptc, mdIptc);
   644→                        if (outIo.write((const byte*)chunk.data(), static_cast<long>(chunk.size())) != (long)chunk.size())
   645→                        {
   646→                            throw Error(kerImageWriteFailed);
   647→                        }
   648→                    }
   649→                }
   650→
   651→                if ( iccProfileDefined() ) {
   652→                    DataBuf compressed;
   653→                    if ( zlibToCompressed(iccProfile_.pData_,iccProfile_.size_,compressed) ) {
   654→
   655→                        const byte* header   = (const byte*) "ICC PROFILE\0\0" ; // \0 = default compression
   656→                        const byte*  type    = (const byte*) "iCCP";
   657→                        uint32_t headerLen   = 13 ;
   658→                        uint32_t typeLen     = 4;
   659→                        uint32_t chunkLength = headerLen + compressed.size_ ;
   660→                        byte     length[4];
   661→                        ul2Data (length,chunkLength,bigEndian);
   662→
   663→                        // calculate CRC
   664→                        uLong   tmp = crc32(0L, Z_NULL, 0);
   665→                        tmp         = crc32(tmp, (const Bytef*)header           ,headerLen);
   666→                        tmp         = crc32(tmp, (const Bytef*)compressed.pData_,compressed.size_);
   667→                        byte    crc[4];
   668→                        ul2Data(crc, tmp, bigEndian);
   669→
   670→                        if( outIo.write(length,4)         != 4
   671→                        ||  outIo.write(type  ,typeLen)   != (long) typeLen
   672→                        ||  outIo.write(header,headerLen) != (long) headerLen
   673→                        ||  outIo.write (compressed.pData_,compressed.size_) != compressed.size_
   674→                        ||  outIo.write(crc,4)            != 4
   675→                        ){
   676→                            throw Error(kerImageWriteFailed);
   677→                        }
   678→#ifdef DEBUG
   679→                        std::cout << "Exiv2::PngImage::doWriteMetadata: build iCCP"
   680→                        << " chunk (length: " << compressed.size_ + headerLen << ")" << std::endl;
   681→#endif
   682→                    }
   683→                }
   684→
   685→                if (writeXmpFromPacket() == false) {
