#include <exiv2/exiv2.hpp>
#include <iostream>
#include <fstream>
#include <cstring>
#include <signal.h>
#include <unistd.h>

// Timeout handler
void timeout_handler(int signum) {
    std::cerr << "TIMEOUT: Script took more than 60 seconds" << std::endl;
    exit(124);
}

// Create a minimal PNG file with a custom ICC profile name
void createTestPNG(const std::string& filename, const std::string& profileName) {
    // PNG signature
    const unsigned char pngSig[8] = {0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A};

    // IHDR chunk (13 bytes data + 12 bytes header/crc)
    const unsigned char ihdr[] = {
        0x00, 0x00, 0x00, 0x0D,  // Length: 13
        0x49, 0x48, 0x44, 0x52,  // Type: IHDR
        0x00, 0x00, 0x00, 0x01,  // Width: 1
        0x00, 0x00, 0x00, 0x01,  // Height: 1
        0x08, 0x02, 0x00, 0x00, 0x00,  // Bit depth, color type, etc.
        0x90, 0x77, 0x53, 0xDE   // CRC
    };

    // Create a simple ICC profile (minimal profile data)
    unsigned char simpleProfile[128];
    memset(simpleProfile, 0, 128);
    // Set profile size in header (bytes 0-3, big endian)
    simpleProfile[0] = 0x00;
    simpleProfile[1] = 0x00;
    simpleProfile[2] = 0x00;
    simpleProfile[3] = 0x80;  // 128 bytes

    // Compress the profile
    unsigned long compSize = 256;
    unsigned char compProfile[256];
    int ret = compress(compProfile, &compSize, simpleProfile, 128);
    if (ret != Z_OK) {
        std::cerr << "Failed to compress profile" << std::endl;
        return;
    }

    // Create iCCP chunk with custom profile name
    std::vector<unsigned char> iccpData;
    // Add profile name
    for (size_t i = 0; i < profileName.length(); i++) {
        iccpData.push_back(profileName[i]);
    }
    iccpData.push_back(0);  // Null terminator
    iccpData.push_back(0);  // Compression method (0 = zlib)
    // Add compressed profile
    for (unsigned long i = 0; i < compSize; i++) {
        iccpData.push_back(compProfile[i]);
    }

    // Calculate CRC for iCCP chunk (includes type + data)
    unsigned long crc = crc32(0L, Z_NULL, 0);
    const unsigned char iccpType[4] = {0x69, 0x43, 0x43, 0x50};  // "iCCP"
    crc = crc32(crc, iccpType, 4);
    crc = crc32(crc, &iccpData[0], iccpData.size());

    // IDAT chunk (minimal image data)
    const unsigned char idat[] = {
        0x00, 0x00, 0x00, 0x0C,  // Length: 12
        0x49, 0x44, 0x41, 0x54,  // Type: IDAT
        0x08, 0xD7, 0x63, 0xF8, 0xFF, 0xFF, 0x3F, 0x00, 0x05, 0xFE, 0x02, 0xFE,
        0xDC, 0xCC, 0x59, 0xE7   // CRC
    };

    // IEND chunk
    const unsigned char iend[] = {
        0x00, 0x00, 0x00, 0x00,  // Length: 0
        0x49, 0x45, 0x4E, 0x44,  // Type: IEND
        0xAE, 0x42, 0x60, 0x82   // CRC
    };

    // Write PNG file
    std::ofstream out(filename.c_str(), std::ios::binary);
    out.write(reinterpret_cast<const char*>(pngSig), 8);
    out.write(reinterpret_cast<const char*>(ihdr), sizeof(ihdr));

    // Write iCCP chunk
    unsigned int dataLen = iccpData.size();
    unsigned char lenBytes[4] = {
        (unsigned char)((dataLen >> 24) & 0xFF),
        (unsigned char)((dataLen >> 16) & 0xFF),
        (unsigned char)((dataLen >> 8) & 0xFF),
        (unsigned char)(dataLen & 0xFF)
    };
    out.write(reinterpret_cast<const char*>(lenBytes), 4);
    out.write(reinterpret_cast<const char*>(iccpType), 4);
    out.write(reinterpret_cast<const char*>(&iccpData[0]), iccpData.size());
    unsigned char crcBytes[4] = {
        (unsigned char)((crc >> 24) & 0xFF),
        (unsigned char)((crc >> 16) & 0xFF),
        (unsigned char)((crc >> 8) & 0xFF),
        (unsigned char)(crc & 0xFF)
    };
    out.write(reinterpret_cast<const char*>(crcBytes), 4);

    out.write(reinterpret_cast<const char*>(idat), sizeof(idat));
    out.write(reinterpret_cast<const char*>(iend), sizeof(iend));
    out.close();

    std::cout << "Created test PNG: " << filename << " with profile name: '" << profileName << "'" << std::endl;
}

int main() {
    // Set timeout alarm for 60 seconds
    signal(SIGALRM, timeout_handler);
    alarm(60);

    try {
        std::cout << "=== Testing ICC Profile Name Preservation ===" << std::endl;

        // Test 1: Create a PNG with a custom profile name "ICC profile" (lowercase)
        std::string testFile = "/tmp/test_icc_profile.png";
        std::string outputFile = "/tmp/test_icc_profile_output.png";

        createTestPNG(testFile, "ICC profile");

        // Read the PNG
        std::cout << "\nReading test PNG file..." << std::endl;
        Exiv2::Image::AutoPtr image = Exiv2::ImageFactory::open(testFile);
        if (image.get() == 0) {
            std::cerr << "Failed to open image" << std::endl;
            return 1;
        }

        image->readMetadata();
        std::cout << "Successfully read metadata" << std::endl;

        // Check if ICC profile was read
        if (image->iccProfile() && image->iccProfile()->size_ > 0) {
            std::cout << "ICC profile found, size: " << image->iccProfile()->size_ << " bytes" << std::endl;
        } else {
            std::cout << "No ICC profile found" << std::endl;
        }

        // Write the PNG back out
        std::cout << "\nWriting PNG back out..." << std::endl;
        Exiv2::Image::AutoPtr image2 = Exiv2::ImageFactory::open(testFile);
        image2->readMetadata();

        // Copy to output file
        Exiv2::Image::AutoPtr outputImage = Exiv2::ImageFactory::create(Exiv2::ImageType::png, outputFile);
        if (outputImage.get() == 0) {
            std::cerr << "Failed to create output image" << std::endl;
            return 1;
        }

        outputImage->setExifData(image2->exifData());
        outputImage->setIptcData(image2->iptcData());
        outputImage->setXmpData(image2->xmpData());
        outputImage->setComment(image2->comment());
        // Copy ICC profile
        if (image2->iccProfile() && image2->iccProfile()->size_ > 0) {
            outputImage->setIccProfile(*(image2->iccProfile()));
        }
        outputImage->writeMetadata();

        std::cout << "Successfully wrote output file" << std::endl;

        // Now check the output file structure
        std::cout << "\n=== Checking output file structure ===" << std::endl;
        std::ifstream inFile(outputFile.c_str(), std::ios::binary);
        if (!inFile) {
            std::cerr << "Failed to open output file for inspection" << std::endl;
            return 1;
        }

        // Skip PNG signature and IHDR chunk
        unsigned char buffer[1024];
        inFile.read(reinterpret_cast<char*>(buffer), 8 + 25);  // signature + IHDR

        // Read next chunk (should be iCCP)
        inFile.read(reinterpret_cast<char*>(buffer), 8);  // length + type
        unsigned int chunkLen = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
        char chunkType[5] = {(char)buffer[4], (char)buffer[5], (char)buffer[6], (char)buffer[7], 0};

        std::cout << "Next chunk type: " << chunkType << ", length: " << chunkLen << std::endl;

        if (strcmp(chunkType, "iCCP") == 0) {
            // Read chunk data to get profile name
            inFile.read(reinterpret_cast<char*>(buffer), chunkLen);

            // Extract profile name (null-terminated string)
            std::string readProfileName;
            for (unsigned int i = 0; i < chunkLen && buffer[i] != 0; i++) {
                readProfileName += buffer[i];
            }

            std::cout << "Profile name in output: '" << readProfileName << "'" << std::endl;

            // Check if profile name was preserved
            if (readProfileName == "ICC profile") {
                std::cout << "\n✓ SUCCESS: Profile name was preserved!" << std::endl;
                return 0;
            } else {
                std::cout << "\n✗ FAIL: Profile name was changed to: '" << readProfileName << "'" << std::endl;
                std::cout << "Expected: 'ICC profile', Got: '" << readProfileName << "'" << std::endl;
                return 1;
            }
        } else {
            std::cout << "iCCP chunk not found where expected" << std::endl;
            return 1;
        }

    } catch (Exiv2::Error& e) {
        std::cerr << "Exiv2 exception: " << e.what() << std::endl;
        return 1;
    } catch (std::exception& e) {
        std::cerr << "Standard exception: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
