use std::time::{Duration, Instant};
use std::collections::HashMap;
use std::sync::Arc;

// Simple in-memory storage for testing
#[derive(Debug)]
pub struct MemoryStorage {
    data: HashMap<String, Vec<Row>>,
    schemas: HashMap<String, Schema>,
}

impl MemoryStorage {
    pub fn new() -> Self {
        Self {
            data: HashMap::new(),
            schemas: HashMap::new(),
        }
    }
}

impl Store for MemoryStorage {
    fn fetch_schema(&self, table_name: &str) -> Result<Option<Schema>> {
        Ok(self.schemas.get(table_name).cloned())
    }

    fn scan_data(&self, table_name: &str) -> Result<Box<dyn Iterator<Item = Result<Row>>>> {
        match self.data.get(table_name) {
            Some(rows) => Ok(Box::new(rows.iter().cloned().map(Ok))),
            None => Ok(Box::new(std::iter::empty())),
        }
    }
}

impl StoreMut for MemoryStorage {
    fn generate_id(&mut self, _table_name: &str) -> Result<Value> {
        Ok(Value::I64(1))
    }

    fn insert_schema(&mut self, schema: &Schema) -> Result<()> {
        self.schemas.insert(schema.table_name.clone(), schema.clone());
        if !self.data.contains_key(&schema.table_name) {
            self.data.insert(schema.table_name.clone(), Vec::new());
        }
        Ok(())
    }

    fn delete_schema(&mut self, table_name: &str) -> Result<()> {
        self.schemas.remove(table_name);
        self.data.remove(table_name);
        Ok(())
    }

    fn insert_data(&mut self, table_name: &str, rows: Vec<Row>) -> Result<()> {
        self.data.entry(table_name.to_string()).or_insert_with(Vec::new).extend(rows);
        Ok(())
    }

    fn update_data(&mut self, _table_name: &str, _rows: Vec<(Value, Row)>) -> Result<()> {
        Ok(())
    }

    fn delete_data(&mut self, _table_name: &str, _keys: Vec<Value>) -> Result<()> {
        Ok(())
    }
}

fn run_test() -> Result<()> {
    let start_time = Instant::now();
    let timeout = Duration::from_secs(60);

    println!("Testing case-sensitive aggregation functions...");

    // Check for timeout
    if start_time.elapsed() > timeout {
        println!("TIMEOUT: Script exceeded 60 seconds!");
        return Ok(());
    }

    let mut storage = MemoryStorage::new();

    // Create a test table
    let sqls = vec![
        "CREATE TABLE TableA (id INTEGER, value INTEGER);",
        "INSERT INTO TableA VALUES (1, 10), (2, 20), (3, 30);",
    ];

    for sql in sqls {
        if start_time.elapsed() > timeout {
            println!("TIMEOUT: Script exceeded 60 seconds!");
            return Ok(());
        }

        let parsed = parse(sql)?;
        for query in parsed {
            execute(&mut storage, &query.0)?;
        }
    }

    // Test case-sensitive COUNT (uppercase) - should work
    println!("Testing uppercase COUNT...");
    let parsed = parse("SELECT COUNT(*) FROM TableA;")?;
    for query in parsed {
        if start_time.elapsed() > timeout {
            println!("TIMEOUT: Script exceeded 60 seconds!");
            return Ok(());
        }

        let result = execute(&mut storage, &query.0);
        match result {
            Ok(payload) => {
                println!("✓ Uppercase COUNT works: {:?}", payload);
            }
            Err(e) => {
                println!("✗ Uppercase COUNT failed: {:?}", e);
            }
        }
    }

    // Test case-insensitive count (lowercase) - should work but currently doesn't
    println!("Testing lowercase count...");
    let parsed = parse("SELECT count(*) FROM TableA;")?;
    for query in parsed {
        if start_time.elapsed() > timeout {
            println!("TIMEOUT: Script exceeded 60 seconds!");
            return Ok(());
        }

        let result = execute(&mut storage, &query.0);
        match result {
            Ok(payload) => {
                println!("✓ Lowercase count works: {:?}", payload);
            }
            Err(e) => {
                println!("✗ Lowercase count failed (expected): {:?}", e);
            }
        }
    }

    // Test mixed case
    println!("Testing mixed case Count...");
    let parsed = parse("SELECT Count(*) FROM TableA;")?;
    for query in parsed {
        if start_time.elapsed() > timeout {
            println!("TIMEOUT: Script exceeded 60 seconds!");
            return Ok(());
        }

        let result = execute(&mut storage, &query.0);
        match result {
            Ok(payload) => {
                println!("✓ Mixed case Count works: {:?}", payload);
            }
            Err(e) => {
                println!("✗ Mixed case Count failed (expected): {:?}", e);
            }
        }
    }

    println!("Total time elapsed: {:?}", start_time.elapsed());
    Ok(())
}

fn main() {
    if let Err(e) = run_test() {
        println!("Test failed: {:?}", e);
        std::process::exit(1);
    }
}"}

