import java.util.concurrent.*;

public class reproduce_issue {
    public static void main(String[] args) {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<Integer> future = executor.submit(() -> {
            try {
                System.out.println("Testing MATCH...AGAINST with JDBC parameter...");

                // Test case 1: MATCH with JDBC parameter in SELECT clause
                String sql1 = "SELECT match (name) against (?) as full_text FROM commodity c WHERE match (name) against (?) and c.deleted = 0 ORDER BY full_text DESC";
                System.out.println("SQL 1: " + sql1);
                try {
                    Statement stmt = CCJSqlParserUtil.parse(sql1);
                    System.out.println("✓ SUCCESS: Parsed SQL with JDBC parameter");
                    System.out.println("Parsed statement: " + stmt);
                } catch (Exception e) {
                    System.out.println("✗ FAILED: " + e.getMessage());
                }

                System.out.println();

                // Test case 2: MATCH with named parameter
                String sql2 = "SELECT MATCH (column) AGAINST (:param) FROM table";
                System.out.println("SQL 2: " + sql2);
                try {
                    Statement stmt = CCJSqlParserUtil.parse(sql2);
                    System.out.println("✓ SUCCESS: Parsed SQL with named parameter");
                    System.out.println("Parsed statement: " + stmt);
                } catch (Exception e) {
                    System.out.println("✗ FAILED: " + e.getMessage());
                }

                System.out.println();

                // Test case 3: MATCH with string literal (should work currently)
                String sql3 = "SELECT MATCH (name) AGAINST ('search term') FROM commodity";
                System.out.println("SQL 3: " + sql3);
                try {
                    Statement stmt = CCJSqlParserUtil.parse(sql3);
                    System.out.println("✓ SUCCESS: Parsed SQL with string literal");
                    System.out.println("Parsed statement: " + stmt);
                } catch (Exception e) {
                    System.out.println("✗ FAILED: " + e.getMessage());
                }

                System.out.println();

                // Test case 4: MATCH with expression
                String sql4 = "SELECT MATCH (name) AGAINST (CONCAT('test', ' ', 'value')) FROM commodity";
                System.out.println("SQL 4: " + sql4);
                try {
                    Statement stmt = CCJSqlParserUtil.parse(sql4);
                    System.out.println("✓ SUCCESS: Parsed SQL with expression");
                    System.out.println("Parsed statement: " + stmt);
                } catch (Exception e) {
                    System.out.println("✗ FAILED: " + e.getMessage());
                }

                return 0;
            } catch (Exception e) {
                System.out.println("Unexpected error: " + e.getMessage());
                e.printStackTrace();
                return 1;
            }
        });

        try {
            // Wait for up to 60 seconds
            future.get(60, TimeUnit.SECONDS);
        } catch (TimeoutException e) {
            System.out.println("TIMEOUT: Script execution exceeded 60 seconds");
            future.cancel(true);
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
            e.printStackTrace();
        } finally {
            executor.shutdownNow();
        }
    }
}
