import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.statement.select.PlainSelect;
import net.sf.jsqlparser.expression.operators.relational.FullTextSearch;

public class test_fulltext_comprehensive {
    public static void main(String[] args) {
        try {
            System.out.println("Testing comprehensive MATCH...AGAINST scenarios:");
            System.out.println("=================================================\n");

            // Test 1: Original issue - JDBC parameter (?)
            String sql1 = "select c.*, match (name) against (?) as full_text from commodity c where match (name) against (?) and c.deleted = 0 order by full_text desc";
            System.out.println("Test 1: JDBC parameter");
            Statement stmt1 = CCJSqlParserUtil.parse(sql1);
            System.out.println("✓ PASS: " + stmt1);
            System.out.println();

            // Test 2: Named parameter (:name)
            String sql2 = "SELECT * FROM articles WHERE MATCH (title, body) AGAINST (:searchTerm IN NATURAL LANGUAGE MODE)";
            System.out.println("Test 2: Named parameter");
            Statement stmt2 = CCJSqlParserUtil.parse(sql2);
            System.out.println("✓ PASS: " + stmt2);
            System.out.println();

            // Test 3: String literal (original support)
            String sql3 = "SELECT * FROM articles WHERE MATCH (title) AGAINST ('database' IN BOOLEAN MODE)";
            System.out.println("Test 3: String literal");
            Statement stmt3 = CCJSqlParserUtil.parse(sql3);
            System.out.println("✓ PASS: " + stmt3);
            System.out.println();

            // Test 4: Function expression - CONCAT
            String sql4 = "SELECT MATCH (name) AGAINST (CONCAT('hello', ' ', 'world')) FROM table1";
            System.out.println("Test 4: CONCAT function");
            Statement stmt4 = CCJSqlParserUtil.parse(sql4);
            System.out.println("✓ PASS: " + stmt4);
            System.out.println();

            // Test 5: Column expression
            String sql5 = "SELECT * FROM table1 WHERE MATCH (name) AGAINST (search_column)";
            System.out.println("Test 5: Column expression");
            Statement stmt5 = CCJSqlParserUtil.parse(sql5);
            System.out.println("✓ PASS: " + stmt5);
            System.out.println();

            // Test 6: Multiple columns with search modifiers
            String sql6 = "SELECT MATCH (col1, col2, col3) AGAINST (? IN NATURAL LANGUAGE MODE WITH QUERY EXPANSION) AS score FROM tbl";
            System.out.println("Test 6: Multiple columns with search modifier");
            Statement stmt6 = CCJSqlParserUtil.parse(sql6);
            System.out.println("✓ PASS: " + stmt6);
            System.out.println();

            // Test 7: Arithmetic expression
            String sql7 = "SELECT * FROM articles WHERE MATCH (title) AGAINST (col1 + col2)";
            System.out.println("Test 7: Arithmetic expression");
            Statement stmt7 = CCJSqlParserUtil.parse(sql7);
            System.out.println("✓ PASS: " + stmt7);
            System.out.println();

            // Test 8: CASE expression
            String sql8 = "SELECT * FROM articles WHERE MATCH (title) AGAINST (CASE WHEN type = 1 THEN 'word1' ELSE 'word2' END)";
            System.out.println("Test 8: CASE expression");
            Statement stmt8 = CCJSqlParserUtil.parse(sql8);
            System.out.println("✓ PASS: " + stmt8);
            System.out.println();

            System.out.println("\n=================================================");
            System.out.println("All tests passed successfully!");
            System.out.println("=================================================");

        } catch (Exception e) {
            System.err.println("✗ FAIL: " + e.getMessage());
            e.printStackTrace();
            System.exit(1);
        }
    }
}
