   174→func cliArgContains(flagName string) bool {
   175→	for _, name := range strings.Split(flagName, ",") {
   176→		name = strings.TrimSpace(name)
   177→		count := utf8.RuneCountInString(name)
   178→		if count > 2 {
   179→			count = 2
   180→		}
   181→		flag := fmt.Sprintf("%s%s", strings.Repeat("-", count), name)
   182→		for _, a := range os.Args {
   183→			if a == flag {
   184→				return true
   185→			}
   186→		}
   187→	}
   188→	return false
