   193→	cur = strings.TrimPrefix(cur, "-")
   194→	for _, flag := range flags {
   195→		if bflag, ok := flag.(*BoolFlag); ok && bflag.Hidden {
   196→			continue
   197→		}
   198→		for _, name := range flag.Names() {
   199→			name = strings.TrimSpace(name)
   200→			// this will get total count utf8 letters in flag name
   201→			count := utf8.RuneCountInString(name)
   202→			if count > 2 {
