import { request, stream, pipeline, connect, upgrade } from './index'
import { Headers, UndiciHeaders } from './index'
import Dispatcher from './types/dispatcher'
import { Writable } from 'stream'

// Test that UndiciHeaders is exported and usable
const testHeaders1: UndiciHeaders = { 'content-type': 'application/json' }
const testHeaders2: UndiciHeaders = ['content-type', 'application/json']
const testHeaders3: UndiciHeaders = new Headers()
const testHeaders4: UndiciHeaders = new Map<string, string>()
const testHeaders5: UndiciHeaders = null

// Test with request function
async function testRequest() {
  // Headers instance
  await request('http://example.com', {
    headers: new Headers()
  })

  // Map instance
  await request('http://example.com', {
    headers: new Map<string, string>()
  })

  // Plain object
  await request('http://example.com', {
    headers: { 'content-type': 'application/json' }
  })

  // String array
  await request('http://example.com', {
    headers: ['content-type', 'application/json']
  })

  // Null
  await request('http://example.com', {
    headers: null
  })
}

// Test with stream function
async function testStream() {
  const factory = (data: Dispatcher.StreamFactoryData) => new Writable()

  await stream('http://example.com', {
    method: 'GET',
    headers: new Headers()
  }, factory)

  await stream('http://example.com', {
    method: 'GET',
    headers: new Map<string, string>()
  }, factory)
}

// Test with connect function
async function testConnect() {
  await connect('http://example.com', {
    headers: new Headers()
  })

  await connect('http://example.com', {
    headers: new Map<string, string>()
  })
}

// Test with upgrade function
async function testUpgrade() {
  await upgrade('http://example.com', {
    headers: new Headers()
  })

  await upgrade('http://example.com', {
    headers: new Map<string, string>()
  })
}

// Test with Dispatcher methods
async function testDispatcher() {
  const dispatcher = new Dispatcher()

  await dispatcher.request({
    origin: 'http://example.com',
    path: '/',
    method: 'GET',
    headers: new Headers()
  })

  await dispatcher.connect({
    origin: 'http://example.com',
    path: '/',
    headers: new Map<string, string>()
  })

  await dispatcher.upgrade({
    path: '/',
    headers: new Headers()
  })
}

console.log('✅ All type checks passed!')
"}

