   111→		// CSI driver needs to properly create and process the target path
   112→		if os.IsNotExist(err) {
   113→			if err = os.MkdirAll(targetPath, 0750); err != nil {
   114→				return nil, status.Errorf(codes.Internal, "failed to create target path %s, err: %v", targetPath, err)
   115→			}
   116→		} else {
   117→			errorReason = internalerrors.FailedToEnsureMountPoint
   118→			return nil, status.Errorf(codes.Internal, "failed to check if target path %s is mount point, err: %v", targetPath, err)
   119→		}
   120→	}
   121→	if mounted {
   122→		klog.InfoS("target path is already mounted", "targetPath", targetPath, "pod", klog.ObjectRef{Namespace: podNamespace, Name: podName})
   123→		return &csi.NodePublishVolumeResponse{}, nil
   124→	}
   125→
   126→	klog.V(2).InfoS("node publish volume", "target", targetPath, "volumeId", volumeID, "attributes", attrib, "mount flags", mountFlags)
   127→
   128→	if isMockProvider(providerName) {
   129→		// mock provider is used only for running sanity tests against the driver
   130→		err := ns.mounter.Mount("tmpfs", targetPath, "tmpfs", []string{})
   131→		if err != nil {
   132→			klog.ErrorS(err, "failed to mount", "pod", klog.ObjectRef{Namespace: podNamespace, Name: podName})
   133→			return nil, err
   134→		}
   135→		klog.Infof("skipping calling provider as it's mock")
   136→		return &csi.NodePublishVolumeResponse{}, nil
   137→	}
   138→
   139→	if secretProviderClass == "" {
   140→		return nil, fmt.Errorf("secretProviderClass is not set")
   141→	}
   142→
   143→	spc, err := getSecretProviderItem(ctx, ns.client, secretProviderClass, podNamespace)
   144→	if err != nil {
   145→		errorReason = internalerrors.SecretProviderClassNotFound
   146→		return nil, err
   147→	}
