   149→	if err != nil {
   150→		return nil, err
   151→	}
   152→	providerName = provider
   153→	parameters, err = getParametersFromSPC(spc)
   154→	if err != nil {
   155→		return nil, err
   156→	}
   157→	parameters[csipodname] = attrib[csipodname]
   158→	parameters[csipodnamespace] = attrib[csipodnamespace]
   159→	parameters[csipoduid] = attrib[csipoduid]
   160→	parameters[csipodsa] = attrib[csipodsa]
   161→
   162→	// ensure it's read-only
   163→	if !req.GetReadonly() {
   164→		return nil, status.Error(codes.InvalidArgument, "Readonly is not true in request")
   165→	}
   166→
   167→	parametersStr, err := json.Marshal(parameters)
   168→	if err != nil {
   169→		klog.ErrorS(err, "failed to marshal parameters", "pod", klog.ObjectRef{Namespace: podNamespace, Name: podName})
   170→		return nil, err
   171→	}
   172→	secretStr, err := json.Marshal(secrets)
   173→	if err != nil {
   174→		klog.ErrorS(err, "failed to marshal node publish secrets", "pod", klog.ObjectRef{Namespace: podNamespace, Name: podName})
   175→		return nil, err
   176→	}
   177→	permissionStr, err := json.Marshal(permission)
   178→	if err != nil {
   179→		klog.ErrorS(err, "failed to marshal file permission", "pod", klog.ObjectRef{Namespace: podNamespace, Name: podName})
   180→		return nil, err
   181→	}
   182→
   183→	// mount before providers can write content to it
   184→	// In linux Mount tmpfs mounts tmpfs to targetPath
   185→	// In windows Mount tmpfs checks if the targetPath exists and if not, will create the target path
   186→	// https://github.com/kubernetes/utils/blob/master/mount/mount_windows.go#L68-L71
   187→	err = ns.mounter.Mount("tmpfs", targetPath, "tmpfs", []string{})
