    14→
    15→package service // import "go.opentelemetry.io/collector/service"
    16→
    17→import (
    18→	"context"
    19→	"fmt"
    20→	"net/http"
    21→	"sort"
    22→
    23→	"go.uber.org/multierr"
    24→
    25→	"go.opentelemetry.io/collector/component"
    26→	"go.opentelemetry.io/collector/connector"
    27→	"go.opentelemetry.io/collector/consumer"
    28→	"go.opentelemetry.io/collector/exporter"
    29→	"go.opentelemetry.io/collector/processor"
    30→	"go.opentelemetry.io/collector/receiver"
    31→	"go.opentelemetry.io/collector/service/internal/capabilityconsumer"
    32→	"go.opentelemetry.io/collector/service/internal/components"
    33→	"go.opentelemetry.io/collector/service/internal/fanoutconsumer"
    34→	"go.opentelemetry.io/collector/service/internal/zpages"
    35→)
    36→
    37→const (
    38→	zPipelineName  = "zpipelinename"
    39→	zComponentName = "zcomponentname"
    40→	zComponentKind = "zcomponentkind"
    41→)
    42→
    43→type pipelines interface {
    44→	StartAll(ctx context.Context, host component.Host) error
    45→	ShutdownAll(ctx context.Context) error
    46→	GetExporters() map[component.DataType]map[component.ID]component.Component
    47→	HandleZPages(w http.ResponseWriter, r *http.Request)
    48→}
    49→
    50→var _ pipelines = (*builtPipelines)(nil)
    51→
    52→// baseConsumer redeclared here since not public in consumer package. May consider to make that public.
    53→type baseConsumer interface {
    54→	Capabilities() consumer.Capabilities
    55→}
    56→
    57→type builtComponent struct {
    58→	id   component.ID
    59→	comp component.Component
    60→}
    61→
    62→type builtPipeline struct {
    63→	lastConsumer baseConsumer
    64→
    65→	receivers  []builtComponent
    66→	processors []builtComponent
    67→	exporters  []builtComponent
    68→}
    69→
    70→// builtPipelines is set of all pipelines created from exporter configs.
    71→type builtPipelines struct {
    72→	telemetry component.TelemetrySettings
    73→
    74→	allReceivers map[component.DataType]map[component.ID]component.Component
    75→	allExporters map[component.DataType]map[component.ID]component.Component
    76→
    77→	pipelines map[component.ID]*builtPipeline
    78→}
    79→
    80→// StartAll starts all pipelines.
    81→//
    82→// Start with exporters, processors (in reverse configured order), then receivers.
    83→// This is important so that components that are earlier in the pipeline and reference components that are
    84→// later in the pipeline do not start sending data to later components which are not yet started.
    85→func (bps *builtPipelines) StartAll(ctx context.Context, host component.Host) error {
    86→	bps.telemetry.Logger.Info("Starting exporters...")
    87→	for dt, expByID := range bps.allExporters {
    88→		for expID, exp := range expByID {
    89→			expLogger := components.ExporterLogger(bps.telemetry.Logger, expID, dt)
    90→			expLogger.Info("Exporter is starting...")
    91→			if err := exp.Start(ctx, components.NewHostWrapper(host, expLogger)); err != nil {
    92→				return err
    93→			}
    94→			expLogger.Info("Exporter started.")
    95→		}
    96→	}
    97→
    98→	bps.telemetry.Logger.Info("Starting processors...")
    99→	for pipelineID, bp := range bps.pipelines {
   100→		for i := len(bp.processors) - 1; i >= 0; i-- {
   101→			procLogger := components.ProcessorLogger(bps.telemetry.Logger, bp.processors[i].id, pipelineID)
   102→			procLogger.Info("Processor is starting...")
   103→			if err := bp.processors[i].comp.Start(ctx, components.NewHostWrapper(host, procLogger)); err != nil {
   104→				return err
   105→			}
   106→			procLogger.Info("Processor started.")
   107→		}
   108→	}
   109→
   110→	bps.telemetry.Logger.Info("Starting receivers...")
   111→	for dt, recvByID := range bps.allReceivers {
   112→		for recvID, recv := range recvByID {
   113→			recvLogger := components.ReceiverLogger(bps.telemetry.Logger, recvID, dt)
   114→			recvLogger.Info("Receiver is starting...")
   115→			if err := recv.Start(ctx, components.NewHostWrapper(host, recvLogger)); err != nil {
   116→				return err
   117→			}
   118→			recvLogger.Info("Receiver started.")
   119→		}
   120→	}
   121→	return nil
   122→}
   123→
   124→// ShutdownAll stops all pipelines.
   125→//
   126→// Shutdown order is the reverse of starting: receivers, processors, then exporters.
   127→// This gives senders a chance to send all their data to a not "shutdown" component.
   128→func (bps *builtPipelines) ShutdownAll(ctx context.Context) error {
   129→	var errs error
   130→	bps.telemetry.Logger.Info("Stopping receivers...")
   131→	for _, recvByID := range bps.allReceivers {
   132→		for _, recv := range recvByID {
   133→			errs = multierr.Append(errs, recv.Shutdown(ctx))
   134→		}
   135→	}
   136→
   137→	bps.telemetry.Logger.Info("Stopping processors...")
   138→	for _, bp := range bps.pipelines {
   139→		for _, p := range bp.processors {
   140→			errs = multierr.Append(errs, p.comp.Shutdown(ctx))
   141→		}
   142→	}
   143→
   144→	bps.telemetry.Logger.Info("Stopping exporters...")
   145→	for _, expByID := range bps.allExporters {
   146→		for _, exp := range expByID {
   147→			errs = multierr.Append(errs, exp.Shutdown(ctx))
   148→		}
   149→	}
   150→
   151→	return errs
   152→}
   153→
   154→func (bps *builtPipelines) GetExporters() map[component.DataType]map[component.ID]component.Component {
   155→	exportersMap := make(map[component.DataType]map[component.ID]component.Component)
   156→
   157→	exportersMap[component.DataTypeTraces] = make(map[component.ID]component.Component, len(bps.allExporters[component.DataTypeTraces]))
   158→	exportersMap[component.DataTypeMetrics] = make(map[component.ID]component.Component, len(bps.allExporters[component.DataTypeMetrics]))
   159→	exportersMap[component.DataTypeLogs] = make(map[component.ID]component.Component, len(bps.allExporters[component.DataTypeLogs]))
   160→
   161→	for dt, expByID := range bps.allExporters {
   162→		for expID, exp := range expByID {
   163→			exportersMap[dt][expID] = exp
   164→		}
   165→	}
   166→
   167→	return exportersMap
   168→}
   169→
   170→func (bps *builtPipelines) HandleZPages(w http.ResponseWriter, r *http.Request) {
   171→	qValues := r.URL.Query()
   172→	pipelineName := qValues.Get(zPipelineName)
   173→	componentName := qValues.Get(zComponentName)
   174→	componentKind := qValues.Get(zComponentKind)
