   192→// pipelinesSettings holds configuration for building builtPipelines.
   193→type pipelinesSettings struct {
   194→	Telemetry component.TelemetrySettings
   195→	BuildInfo component.BuildInfo
   196→
   197→	Receivers  *receiver.Builder
   198→	Processors *processor.Builder
   199→	Exporters  *exporter.Builder
   200→	Connectors *connector.Builder
   201→
   202→	// PipelineConfigs is a map of component.ID to PipelineConfig.
   203→	PipelineConfigs map[component.ID]*PipelineConfig
   204→}
   205→
   206→// buildPipelines builds all pipelines from config.
   207→func buildPipelines(ctx context.Context, set pipelinesSettings) (pipelines, error) {
   208→	exps := &builtPipelines{
   209→		telemetry:    set.Telemetry,
   210→		allReceivers: make(map[component.DataType]map[component.ID]component.Component),
   211→		allExporters: make(map[component.DataType]map[component.ID]component.Component),
   212→		pipelines:    make(map[component.ID]*builtPipeline, len(set.PipelineConfigs)),
   213→	}
   214→
   215→	receiversConsumers := make(map[component.DataType]map[component.ID][]baseConsumer)
   216→
   217→	// Iterate over all pipelines, and create exporters, then processors.
   218→	// Receivers cannot be created since we need to know all consumers, a.k.a. we need all pipelines build up to the
   219→	// first processor.
   220→	for pipelineID, pipeline := range set.PipelineConfigs {
   221→		// The data type of the pipeline defines what data type each exporter is expected to receive.
   222→		if _, ok := exps.allExporters[pipelineID.Type()]; !ok {
   223→			exps.allExporters[pipelineID.Type()] = make(map[component.ID]component.Component)
   224→		}
   225→		expByID := exps.allExporters[pipelineID.Type()]
   226→
   227→		bp := &builtPipeline{
   228→			receivers:  make([]builtComponent, len(pipeline.Receivers)),
   229→			processors: make([]builtComponent, len(pipeline.Processors)),
   230→			exporters:  make([]builtComponent, len(pipeline.Exporters)),
   231→		}
   232→		exps.pipelines[pipelineID] = bp
   233→
   234→		// Iterate over all Exporters for this pipeline.
   235→		for i, expID := range pipeline.Exporters {
   236→			// If already created an exporter for this [DataType, ComponentID] nothing to do, will reuse this instance.
   237→			if exp, ok := expByID[expID]; ok {
   238→				bp.exporters[i] = builtComponent{id: expID, comp: exp}
   239→				continue
   240→			}
   241→
   242→			cSet := exporter.CreateSettings{
   243→				ID:                expID,
   244→				TelemetrySettings: set.Telemetry,
   245→				BuildInfo:         set.BuildInfo,
   246→			}
   247→			cSet.TelemetrySettings.Logger = components.ExporterLogger(set.Telemetry.Logger, expID, pipelineID.Type())
   248→			exp, err := buildExporter(ctx, cSet, set.Exporters, pipelineID)
   249→			if err != nil {
   250→				return nil, err
   251→			}
   252→
   253→			bp.exporters[i] = builtComponent{id: expID, comp: exp}
   254→			expByID[expID] = exp
   255→		}
   256→
   257→		// Build a fan out consumer to all exporters.
   258→		switch pipelineID.Type() {
   259→		case component.DataTypeTraces:
   260→			bp.lastConsumer = buildFanOutExportersTracesConsumer(bp.exporters)
   261→		case component.DataTypeMetrics:
   262→			bp.lastConsumer = buildFanOutExportersMetricsConsumer(bp.exporters)
   263→		case component.DataTypeLogs:
   264→			bp.lastConsumer = buildFanOutExportersLogsConsumer(bp.exporters)
   265→		default:
   266→			return nil, fmt.Errorf("create fan-out exporter in pipeline %q, data type %q is not supported", pipelineID, pipelineID.Type())
   267→		}
   268→
   269→		mutatesConsumedData := bp.lastConsumer.Capabilities().MutatesData
   270→		// Build the processors backwards, starting from the last one.
   271→		// The last processor points to fan out consumer to all Exporters, then the processor itself becomes a
   272→		// consumer for the one that precedes it in the pipeline and so on.
   273→		for i := len(pipeline.Processors) - 1; i >= 0; i-- {
   274→			procID := pipeline.Processors[i]
   275→
   276→			cSet := processor.CreateSettings{
   277→				ID:                procID,
   278→				TelemetrySettings: set.Telemetry,
   279→				BuildInfo:         set.BuildInfo,
   280→			}
   281→			cSet.TelemetrySettings.Logger = components.ProcessorLogger(set.Telemetry.Logger, procID, pipelineID)
   282→			proc, err := buildProcessor(ctx, cSet, set.Processors, pipelineID, bp.lastConsumer)
   283→			if err != nil {
   284→				return nil, err
   285→			}
   286→
   287→			bp.processors[i] = builtComponent{id: procID, comp: proc}
   288→			bp.lastConsumer = proc.(baseConsumer)
   289→			mutatesConsumedData = mutatesConsumedData || bp.lastConsumer.Capabilities().MutatesData
   290→		}
   291→
   292→		// Some consumers may not correctly implement the Capabilities, and ignore the next consumer when calculated the Capabilities.
   293→		// Because of this wrap the first consumer if any consumers in the pipeline mutate the data and the first says that it doesn't.
   294→		switch pipelineID.Type() {
   295→		case component.DataTypeTraces:
   296→			bp.lastConsumer = capabilityconsumer.NewTraces(bp.lastConsumer.(consumer.Traces), consumer.Capabilities{MutatesData: mutatesConsumedData})
   297→		case component.DataTypeMetrics:
   298→			bp.lastConsumer = capabilityconsumer.NewMetrics(bp.lastConsumer.(consumer.Metrics), consumer.Capabilities{MutatesData: mutatesConsumedData})
   299→		case component.DataTypeLogs:
   300→			bp.lastConsumer = capabilityconsumer.NewLogs(bp.lastConsumer.(consumer.Logs), consumer.Capabilities{MutatesData: mutatesConsumedData})
   301→		default:
   302→			return nil, fmt.Errorf("create cap consumer in pipeline %q, data type %q is not supported", pipelineID, pipelineID.Type())
   303→		}
   304→
   305→		// The data type of the pipeline defines what data type each exporter is expected to receive.
   306→		if _, ok := receiversConsumers[pipelineID.Type()]; !ok {
   307→			receiversConsumers[pipelineID.Type()] = make(map[component.ID][]baseConsumer)
   308→		}
   309→		recvConsByID := receiversConsumers[pipelineID.Type()]
   310→		// Iterate over all Receivers for this pipeline and just append the lastConsumer as a consumer for the receiver.
   311→		for _, recvID := range pipeline.Receivers {
   312→			recvConsByID[recvID] = append(recvConsByID[recvID], bp.lastConsumer)
   313→		}
   314→	}
   315→
   316→	// Now that we built the `receiversConsumers` map, we can build the receivers as well.
   317→	for pipelineID, pipeline := range set.PipelineConfigs {
   318→		// The data type of the pipeline defines what data type each exporter is expected to receive.
   319→		if _, ok := exps.allReceivers[pipelineID.Type()]; !ok {
   320→			exps.allReceivers[pipelineID.Type()] = make(map[component.ID]component.Component)
   321→		}
   322→		recvByID := exps.allReceivers[pipelineID.Type()]
   323→		bp := exps.pipelines[pipelineID]
   324→
   325→		// Iterate over all Receivers for this pipeline.
   326→		for i, recvID := range pipeline.Receivers {
   327→			// If already created a receiver for this [DataType, ComponentID] nothing to do.
   328→			if exp, ok := recvByID[recvID]; ok {
   329→				bp.receivers[i] = builtComponent{id: recvID, comp: exp}
   330→				continue
   331→			}
   332→
   333→			cSet := receiver.CreateSettings{
   334→				ID:                recvID,
   335→				TelemetrySettings: set.Telemetry,
   336→				BuildInfo:         set.BuildInfo,
   337→			}
   338→			cSet.TelemetrySettings.Logger = components.ReceiverLogger(set.Telemetry.Logger, recvID, pipelineID.Type())
   339→			recv, err := buildReceiver(ctx, cSet, set.Receivers, pipelineID, receiversConsumers[pipelineID.Type()][recvID])
   340→			if err != nil {
   341→				return nil, err
   342→			}
   343→
   344→			bp.receivers[i] = builtComponent{id: recvID, comp: recv}
   345→			recvByID[recvID] = recv
   346→		}
   347→	}
   348→	return exps, nil
   349→}
   350→
   351→func buildExporter(
   352→	ctx context.Context,
   353→	set exporter.CreateSettings,
   354→	builder *exporter.Builder,
   355→	pipelineID component.ID,
   356→) (exp component.Component, err error) {
   357→	switch pipelineID.Type() {
   358→	case component.DataTypeTraces:
   359→		exp, err = builder.CreateTraces(ctx, set)
   360→	case component.DataTypeMetrics:
   361→		exp, err = builder.CreateMetrics(ctx, set)
   362→	case component.DataTypeLogs:
   363→		exp, err = builder.CreateLogs(ctx, set)
   364→	default:
   365→		return nil, fmt.Errorf("error creating exporter %q in pipeline %q, data type %q is not supported", set.ID, pipelineID, pipelineID.Type())
   366→	}
   367→	if err != nil {
   368→		return nil, fmt.Errorf("failed to create %q exporter, in pipeline %q: %w", set.ID, pipelineID, err)
   369→	}
   370→	return exp, nil
   371→}
   372→
   373→func buildFanOutExportersTracesConsumer(exporters []builtComponent) consumer.Traces {
   374→	consumers := make([]consumer.Traces, 0, len(exporters))
   375→	for _, exp := range exporters {
   376→		consumers = append(consumers, exp.comp.(consumer.Traces))
   377→	}
   378→	// Create a junction point that fans out to all allExporters.
   379→	return fanoutconsumer.NewTraces(consumers)
   380→}
   381→
   382→func buildFanOutExportersMetricsConsumer(exporters []builtComponent) consumer.Metrics {
   383→	consumers := make([]consumer.Metrics, 0, len(exporters))
   384→	for _, exp := range exporters {
   385→		consumers = append(consumers, exp.comp.(consumer.Metrics))
   386→	}
   387→	// Create a junction point that fans out to all allExporters.
   388→	return fanoutconsumer.NewMetrics(consumers)
   389→}
   390→
   391→func buildFanOutExportersLogsConsumer(exporters []builtComponent) consumer.Logs {
   392→	consumers := make([]consumer.Logs, 0, len(exporters))
   393→	for _, exp := range exporters {
   394→		consumers = append(consumers, exp.comp.(consumer.Logs))
   395→	}
   396→	// Create a junction point that fans out to all allExporters.
   397→	return fanoutconsumer.NewLogs(consumers)
   398→}
