   400→func buildProcessor(ctx context.Context,
   401→	set processor.CreateSettings,
   402→	builder *processor.Builder,
   403→	pipelineID component.ID,
   404→	next baseConsumer,
   405→) (proc component.Component, err error) {
   406→	switch pipelineID.Type() {
   407→	case component.DataTypeTraces:
   408→		proc, err = builder.CreateTraces(ctx, set, next.(consumer.Traces))
   409→	case component.DataTypeMetrics:
   410→		proc, err = builder.CreateMetrics(ctx, set, next.(consumer.Metrics))
   411→	case component.DataTypeLogs:
   412→		proc, err = builder.CreateLogs(ctx, set, next.(consumer.Logs))
   413→	default:
   414→		return nil, fmt.Errorf("error creating processor %q in pipeline %q, data type %q is not supported", set.ID, pipelineID, pipelineID.Type())
   415→	}
   416→	if err != nil {
   417→		return nil, fmt.Errorf("failed to create %q processor, in pipeline %q: %w", set.ID, pipelineID, err)
   418→	}
   419→	return proc, nil
   420→}
   421→
   422→func buildReceiver(ctx context.Context,
   423→	set receiver.CreateSettings,
   424→	builder *receiver.Builder,
   425→	pipelineID component.ID,
   426→	nexts []baseConsumer,
   427→) (recv component.Component, err error) {
   428→	switch pipelineID.Type() {
   429→	case component.DataTypeTraces:
   430→		var consumers []consumer.Traces
   431→		for _, next := range nexts {
   432→			consumers = append(consumers, next.(consumer.Traces))
   433→		}
   434→		recv, err = builder.CreateTraces(ctx, set, fanoutconsumer.NewTraces(consumers))
   435→	case component.DataTypeMetrics:
   436→		var consumers []consumer.Metrics
   437→		for _, next := range nexts {
   438→			consumers = append(consumers, next.(consumer.Metrics))
   439→		}
   440→		recv, err = builder.CreateMetrics(ctx, set, fanoutconsumer.NewMetrics(consumers))
   441→	case component.DataTypeLogs:
   442→		var consumers []consumer.Logs
   443→		for _, next := range nexts {
   444→			consumers = append(consumers, next.(consumer.Logs))
   445→		}
   446→		recv, err = builder.CreateLogs(ctx, set, fanoutconsumer.NewLogs(consumers))
   447→	default:
   448→		return nil, fmt.Errorf("error creating receiver %q in pipeline %q, data type %q is not supported", set.ID, pipelineID, pipelineID.Type())
   449→	}
   450→	if err != nil {
   451→		return nil, fmt.Errorf("failed to create %q receiver, in pipeline %q: %w", set.ID, pipelineID, err)
   452→	}
   453→	return recv, nil
   454→}
