   456→func (bps *builtPipelines) getPipelinesSummaryTableData() zpages.SummaryPipelinesTableData {
   457→	sumData := zpages.SummaryPipelinesTableData{}
   458→	sumData.Rows = make([]zpages.SummaryPipelinesTableRowData, 0, len(bps.pipelines))
   459→	for c, p := range bps.pipelines {
   460→		// TODO: Change the template to use ID.
   461→		var recvs []string
   462→		for _, bRecv := range p.receivers {
   463→			recvs = append(recvs, bRecv.id.String())
   464→		}
   465→		var procs []string
   466→		for _, bProc := range p.processors {
   467→			procs = append(procs, bProc.id.String())
   468→		}
   469→		var exps []string
   470→		for _, bExp := range p.exporters {
   471→			exps = append(exps, bExp.id.String())
   472→		}
   473→		row := zpages.SummaryPipelinesTableRowData{
   474→			FullName:    c.String(),
   475→			InputType:   string(c.Type()),
   476→			MutatesData: p.lastConsumer.Capabilities().MutatesData,
   477→			Receivers:   recvs,
   478→			Processors:  procs,
   479→			Exporters:   exps,
   480→		}
   481→		sumData.Rows = append(sumData.Rows, row)
   482→	}
   483→
   484→	sort.Slice(sumData.Rows, func(i, j int) bool {
   485→		return sumData.Rows[i].FullName < sumData.Rows[j].FullName
   486→	})
   487→	return sumData
   488→}
