   542→	for _, word := range words[1:] {
   543→		if len(word)+1 > spaceLeft {
   544→			wrapped += "\n" + padding + word
   545→			spaceLeft = lineWidth - len(word)
   546→		} else {
   547→			wrapped += " " + word
   548→			spaceLeft -= 1 + len(word)
   549→		}
   550→	}
   551→
   552→	return wrapped
   553→}
