   559→// this function tries to find the max width of the names column
   560→// so say we have the following rows for help
   561→//
   562→//	foo1, foo2, foo3  some string here
   563→//	bar1, b2 some other string here
   564→//
   565→// We want to offset the 2nd row usage by some amount so that everything
   566→// is aligned
   567→//
   568→//	foo1, foo2, foo3  some string here
   569→//	bar1, b2          some other string here
   570→//
   571→// to find that offset we find the length of all the rows and use the max
   572→// to calculate the offset
   573→func offsetCommands(cmds []*Command, fixed int) int {
   574→	max := 0
   575→	for _, cmd := range cmds {
   576→		s := strings.Join(cmd.Names(), ", ")
   577→		if len(s) > max {
   578→			max = len(s)
   579→		}
   580→	}
   581→	return max + fixed
   582→}
