   220→// Returns the placeholder, if any, and the unquoted usage string.
   221→func unquoteUsage(usage string) (string, string) {
   222→	for i := 0; i < len(usage); i++ {
   223→		if usage[i] == '`' {
   224→			for j := i + 1; j < len(usage); j++ {
   225→				if usage[j] == '`' {
   226→					name := usage[i+1 : j]
   227→					usage = usage[:i] + name + usage[j+1:]
   228→					return name, usage
   229→				}
   230→			}
   231→			break
   232→		}
   233→	}
   234→	return "", usage
   235→}
