   302→func stringifyFlag(f Flag) string {
   303→	// enforce DocGeneration interface on flags to avoid reflection
   304→	df, ok := f.(DocGenerationFlag)
   305→	if !ok {
   306→		return ""
   307→	}
   308→
   309→	placeholder, usage := unquoteUsage(df.GetUsage())
   310→	needsPlaceholder := df.TakesValue()
   311→
   312→	if needsPlaceholder && placeholder == "" {
   313→		placeholder = defaultPlaceholder
   314→	}
   315→
   316→	defaultValueString := ""
   317→
   318→	// don't print default text for required flags
   319→	if rf, ok := f.(RequiredFlag); !ok || !rf.IsRequired() {
   320→		isVisible := df.IsDefaultVisible()
   321→		if s := df.GetDefaultText(); isVisible && s != "" {
   322→			defaultValueString = fmt.Sprintf(formatDefault("%s"), s)
   323→		}
   324→	}
   325→
   326→	usageWithDefault := strings.TrimSpace(usage + defaultValueString)
   327→
   328→	pn := prefixedNames(f.Names(), placeholder)
   329→	sliceFlag, ok := f.(DocGenerationMultiValueFlag)
   330→	if ok && sliceFlag.IsMultiValueFlag() {
   331→		pn = pn + " [ " + pn + " ]"
   332→	}
   333→
   334→	return withEnvHint(df.GetEnvVars(), fmt.Sprintf("%s\t%s", pn, usageWithDefault))
   335→}
