type roundTripper func(*http.Request) (*http.Response, error)

func (rt roundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	return rt(req)
}

func main() {
	fmt.Println("Testing HEAD request fix...")

	// Test case 1: HEAD request with 404 status and JSON content type (should NOT cause error)
	fmt.Println("\n1. Testing HEAD request with 404 and JSON content type:")

	ios, _, stdout, stderr := iostreams.Test()

	options := api.ApiOptions{
		IO:            ios,
		RequestMethod: "HEAD",
		RequestPath:   "repos/cli/cli/releases/tags/nonexistent",
		Config: func() (gh.Config, error) {
			return config.NewBlankConfig(), nil
		},
		HttpClient: func() (*http.Client, error) {
			var tr roundTripper = func(req *http.Request) (*http.Response, error) {
				resp := &http.Response{
					StatusCode: 404,
					Header: http.Header{
