		fmt.Printf("Stdout: %s\n", stdout.String())
		fmt.Printf("Stderr: %s\n", stderr.String())
	}

	// Test case 2: GET request with 404 status and JSON content type (should still parse errors)
	fmt.Println("\n2. Testing GET request with 404 and JSON content type (should still work):")

	ios2, _, stdout2, stderr2 := iostreams.Test()

	options2 := api.ApiOptions{
