   349→                    extra_apis.append(&mut innerty.extra_apis);
   350→                    GenericArgument::Type(innerty.ty)
   351→                }
   352→                _ => arg,
   353→            });
   354→        }
   355→        Ok(Annotated::new(
   356→            new_pun,
   357→            types_encountered,
   358→            extra_apis,
   359→            TypeKind::Regular,
   360→        ))
   361→    }
