   363→    fn resolve_typedef<'b>(&'b self, tn: &QualifiedName) -> Result<Option<&'b Type>, ConvertError> {
   364→        let mut encountered = HashSet::new();
   365→        let mut tn = tn.clone();
   366→        let mut previous_typ = None;
   367→        loop {
   368→            let r = self.typedefs.get(&tn);
   369→            match r {
   370→                Some(Type::Path(typ)) => {
   371→                    previous_typ = r;
   372→                    let new_tn = QualifiedName::from_type_path(typ);
   373→                    if encountered.contains(&new_tn) {
   374→                        return Err(ConvertError::InfinitelyRecursiveTypedef(tn.clone()));
   375→                    }
   376→                    encountered.insert(new_tn.clone());
   377→                    tn = new_tn;
   378→                }
   379→                None => return Ok(previous_typ),
   380→                _ => return Ok(r),
   381→            }
   382→        }
   383→    }
