   385→    fn convert_ptr_to_reference(
   386→        &mut self,
   387→        ptr: TypePtr,
   388→        ns: &Namespace,
   389→    ) -> Result<Annotated<Type>, ConvertError> {
   390→        let mutability = ptr.mutability;
   391→        let elem = self.convert_boxed_type(ptr.elem, ns, &TypeConversionContext::CxxInnerType)?;
   392→        // TODO - in the future, we should check if this is a rust::Str and throw
   393→        // a wobbler if not. rust::Str should only be seen _by value_ in C++
   394→        // headers; it manifests as &str in Rust but on the C++ side it must
   395→        // be a plain value. We should detect and abort.
   396→        let mut outer = elem.map(|elem| match mutability {
   397→            Some(_) => Type::Path(parse_quote! {
   398→                ::std::pin::Pin < & #mutability #elem >
   399→            }),
   400→            None => Type::Reference(parse_quote! {
   401→                & #elem
   402→            }),
   403→        });
   404→        outer.kind = if mutability.is_some() {
   405→            TypeKind::MutableReference
   406→        } else {
   407→            TypeKind::Reference
   408→        };
   409→        Ok(outer)
   410→    }
