   412→    fn get_templated_typename(
   413→        &mut self,
   414→        rs_definition: &Type,
   415→    ) -> Result<(QualifiedName, Option<UnanalyzedApi>), ConvertError> {
   416→        let count = self.concrete_templates.len();
   417→        // We just use this as a hash key, essentially.
   418→        // TODO: Once we've completed the TypeConverter refactoring (see #220),
   419→        // pass in an actual original_name_map here.
   420→        let cpp_definition = type_to_cpp(rs_definition, &HashMap::new())?;
   421→        let e = self.concrete_templates.get(&cpp_definition);
   422→        match e {
   423→            Some(tn) => Ok((tn.clone(), None)),
   424→            None => {
   425→                let synthetic_ident = format!(
   426→                    "{}_AutocxxConcrete",
   427→                    cpp_definition.replace(|c: char| !(c.is_ascii_alphanumeric() || c == '_'), "_")
   428→                );
   429→                // Remove runs of multiple _s. Trying to avoid a dependency on
   430→                // regex.
   431→                let synthetic_ident = synthetic_ident
   432→                    .split('_')
   433→                    .filter(|s| !s.is_empty())
   434→                    .join("_");
   435→                // Ensure we're not duplicating some existing concrete template name.
   436→                // If so, we'll invent a name which is guaranteed to be unique.
   437→                let synthetic_ident = match self
   438→                    .concrete_templates
   439→                    .values()
   440→                    .map(|n| n.get_final_item())
   441→                    .find(|s| s == &synthetic_ident)
   442→                {
   443→                    None => synthetic_ident,
   444→                    Some(_) => format!("AutocxxConcrete{}", count),
   445→                };
   446→                let api = UnanalyzedApi::ConcreteType {
   447→                    name: ApiName::new_in_root_namespace(make_ident(&synthetic_ident)),
   448→                    cpp_definition: cpp_definition.clone(),
   449→                    rs_definition: Some(Box::new(rs_definition.clone())),
   450→                };
   451→                self.concrete_templates
   452→                    .insert(cpp_definition, api.name().clone());
   453→                Ok((api.name().clone(), Some(api)))
   454→            }
   455→        }
   456→    }
   457→
   458→    fn confirm_inner_type_is_acceptable_generic_payload(
   459→        &self,
   460→        path_args: &PathArguments,
   461→        desc: &QualifiedName,
   462→        generic_behavior: CxxGenericType,
   463→        forward_declarations_ok: bool,
   464→    ) -> Result<TypeKind, ConvertError> {
   465→        // For now, all supported generics accept the same payloads. This
   466→        // may change in future in which case we'll need to accept more arguments here.
   467→        match path_args {
   468→            PathArguments::None => Ok(TypeKind::Regular),
   469→            PathArguments::Parenthesized(_) => Err(
   470→                ConvertError::TemplatedTypeContainingNonPathArg(desc.clone()),
   471→            ),
   472→            PathArguments::AngleBracketed(ab) => {
   473→                for inner in &ab.args {
   474→                    match inner {
   475→                        GenericArgument::Type(Type::Path(typ)) => {
   476→                            let inner_qn = QualifiedName::from_type_path(typ);
   477→                            if !forward_declarations_ok
   478→                                && self.forward_declarations.contains(&inner_qn)
   479→                            {
   480→                                return Err(ConvertError::TypeContainingForwardDeclaration(
   481→                                    inner_qn,
   482→                                ));
   483→                            }
   484→                            if generic_behavior == CxxGenericType::Rust {
   485→                                if !inner_qn.get_namespace().is_empty() {
   486→                                    return Err(ConvertError::RustTypeWithAPath(inner_qn));
   487→                                }
   488→                                if !self.config.is_rust_type(&inner_qn.get_final_ident()) {
   489→                                    return Err(ConvertError::BoxContainingNonRustType(inner_qn));
   490→                                }
   491→                                if self
   492→                                    .config
   493→                                    .is_subclass_holder(&inner_qn.get_final_ident().to_string())
   494→                                {
   495→                                    return Ok(TypeKind::SubclassHolder(
   496→                                        inner_qn.get_final_ident(),
   497→                                    ));
   498→                                } else {
   499→                                    return Ok(TypeKind::Regular);
   500→                                }
   501→                            }
   502→                            if let Some(more_generics) = typ.path.segments.last() {
   503→                                self.confirm_inner_type_is_acceptable_generic_payload(
   504→                                    &more_generics.arguments,
   505→                                    desc,
   506→                                    generic_behavior,
   507→                                    forward_declarations_ok,
   508→                                )?;
   509→                            }
   510→                        }
   511→                        _ => {
   512→                            return Err(ConvertError::TemplatedTypeContainingNonPathArg(
   513→                                desc.clone(),
   514→                            ))
   515→                        }
   516→                    }
   517→                }
   518→                Ok(TypeKind::Regular)
   519→            }
   520→        }
   521→    }
   522→
   523→    fn find_typedefs<A: AnalysisPhase>(apis: &ApiVec<A>) -> HashMap<QualifiedName, Type>
   524→    where
   525→        A::TypedefAnalysis: TypedefTarget,
   526→    {
   527→        apis.iter()
   528→            .filter_map(|api| match &api {
   529→                Api::Typedef { analysis, .. } => analysis
   530→                    .get_target()
   531→                    .cloned()
   532→                    .map(|ty| (api.name().clone(), ty)),
   533→                _ => None,
   534→            })
   535→            .collect()
   536→    }
   537→
   538→    fn find_concrete_templates<A: AnalysisPhase>(
   539→        apis: &ApiVec<A>,
   540→    ) -> HashMap<String, QualifiedName> {
   541→        apis.iter()
   542→            .filter_map(|api| match &api {
   543→                Api::ConcreteType { cpp_definition, .. } => {
   544→                    Some((cpp_definition.clone(), api.name().clone()))
   545→                }
   546→                _ => None,
   547→            })
   548→            .collect()
   549→    }
   550→
   551→    fn find_incomplete_types<A: AnalysisPhase>(apis: &ApiVec<A>) -> HashSet<QualifiedName> {
   552→        apis.iter()
   553→            .filter_map(|api| match api {
   554→                Api::ForwardDeclaration { .. } => Some(api.name()),
   555→                _ => None,
   556→            })
   557→            .cloned()
   558→            .collect()
