   562→/// Processing functions sometimes results in new types being materialized.
   563→/// These types haven't been through the analysis phases (chicken and egg
   564→/// problem) but fortunately, don't need to. We need to keep the type
   565→/// system happy by adding an [ApiAnalysis] but in practice, for the sorts
   566→/// of things that get created, it's always blank.
   567→pub(crate) fn add_analysis<A: AnalysisPhase>(api: UnanalyzedApi) -> Api<A> {
   568→    match api {
   569→        Api::ConcreteType {
   570→            name,
   571→            rs_definition,
   572→            cpp_definition,
   573→        } => Api::ConcreteType {
   574→            name,
   575→            rs_definition,
   576→            cpp_definition,
   577→        },
   578→        Api::IgnoredItem { name, err, ctx } => Api::IgnoredItem { name, err, ctx },
   579→        _ => panic!("Function analysis created an unexpected type of extra API"),
   580→    }
   581→}
   582→pub(crate) trait TypedefTarget {
   583→    fn get_target(&self) -> Option<&Type>;
   584→}
   585→
   586→impl TypedefTarget for () {
   587→    fn get_target(&self) -> Option<&Type> {
   588→        None
   589→    }
   590→}
   591→
   592→impl TypedefTarget for TypedefAnalysis {
   593→    fn get_target(&self) -> Option<&Type> {
   594→        match self.kind {
   595→            TypedefKind::Type(ref ty) => Some(&ty.ty),
   596→            TypedefKind::Use(_) => None,
   597→        }
   598→    }
   599→}
   600→
   601→pub(crate) fn find_types<A: AnalysisPhase>(apis: &ApiVec<A>) -> HashSet<QualifiedName> {
   602→    apis.iter()
   603→        .filter_map(|api| match api {
   604→            Api::ForwardDeclaration { .. }
   605→            | Api::ConcreteType { .. }
   606→            | Api::Typedef { .. }
   607→            | Api::Enum { .. }
   608→            | Api::Struct { .. }
   609→            | Api::Subclass { .. }
   610→            | Api::RustType { .. } => Some(api.name()),
   611→            Api::StringConstructor { .. }
   612→            | Api::Function { .. }
   613→            | Api::Const { .. }
   614→            | Api::CType { .. }
   615→            | Api::RustSubclassFn { .. }
   616→            | Api::IgnoredItem { .. }
   617→            | Api::SubclassTraitItem { .. }
   618→            | Api::RustFn { .. } => None,
   619→        })
   620→        .cloned()
