    34→pub(crate) fn namespaced_name_using_original_name_map(
    35→    qual_name: &QualifiedName,
    36→    original_name_map: &CppNameMap,
    37→) -> String {
    38→    if let Some(cpp_name) = original_name_map.get(qual_name) {
    39→        qual_name
    40→            .get_namespace()
    41→            .iter()
    42→            .chain(once(cpp_name))
    43→            .join("::")
