    51→    original_name_map: &CppNameMap,
    52→) -> String {
    53→    match original_name_map.get(qual_name) {
    54→        Some(original_name) => {
    55→            // If we have an original name, this may be a nested struct
    56→            // (e.g. A::B). The final ident here is just 'B' so...
    57→            original_name
    58→                .rsplit_once("::")
    59→                .map_or(original_name.clone(), |(_, original_name)| {
    60→                    original_name.to_string()
    61→                })
    62→        }
    63→        None => qual_name.get_final_cpp_item(),
    64→    }
    65→}
