    67→pub(crate) fn type_to_cpp(ty: &Type, cpp_name_map: &CppNameMap) -> Result<String, ConvertError> {
    68→    match ty {
    69→        Type::Path(typ) => {
    70→            // If this is a std::unique_ptr we do need to pass
    71→            // its argument through.
    72→            let qual_name = QualifiedName::from_type_path(typ);
    73→            let root = namespaced_name_using_original_name_map(&qual_name, cpp_name_map);
    74→            if root == "Pin" {
    75→                // Strip all Pins from type names when describing them in C++.
    76→                let inner_type = &typ.path.segments.last().unwrap().arguments;
    77→                if let syn::PathArguments::AngleBracketed(ab) = inner_type {
    78→                    let inner_type = ab.args.iter().next().unwrap();
    79→                    if let syn::GenericArgument::Type(gat) = inner_type {
    80→                        return type_to_cpp(gat, cpp_name_map);
    81→                    }
    82→                }
    83→                panic!("Pin<...> didn't contain the inner types we expected");
    84→            }
    85→            let suffix = match &typ.path.segments.last().unwrap().arguments {
    86→                syn::PathArguments::AngleBracketed(ab) => {
    87→                    let results: Result<Vec<_>, _> = ab
    88→                        .args
    89→                        .iter()
    90→                        .map(|x| match x {
    91→                            syn::GenericArgument::Type(gat) => type_to_cpp(gat, cpp_name_map),
    92→                            _ => Ok("".to_string()),
    93→                        })
    94→                        .collect();
    95→                    Some(results?.join(", "))
    96→                }
    97→                syn::PathArguments::None | syn::PathArguments::Parenthesized(_) => None,
    98→            };
    99→            match suffix {
