   101→                Some(suffix) => Ok(format!("{}<{}>", root, suffix)),
   102→            }
   103→        }
   104→        Type::Reference(typr) => Ok(format!(
   105→            "{}{}&",
   106→            get_mut_string(&typr.mutability),
   107→            type_to_cpp(typr.elem.as_ref(), cpp_name_map)?
   108→        )),
   109→        Type::Ptr(typp) => Ok(format!(
   110→            "{}{}*",
   111→            get_mut_string(&typp.mutability),
   112→            type_to_cpp(typp.elem.as_ref(), cpp_name_map)?
   113→        )),
   114→        Type::Array(_)
