   116→        | Type::Group(_)
   117→        | Type::ImplTrait(_)
   118→        | Type::Infer(_)
   119→        | Type::Macro(_)
   120→        | Type::Never(_)
   121→        | Type::Paren(_)
   122→        | Type::Slice(_)
   123→        | Type::TraitObject(_)
   124→        | Type::Tuple(_)
