    33→
    34→/// A set of futures which may complete in any order.
    35→///
    36→/// This structure is optimized to manage a large number of futures.
    37→/// Futures managed by [`FuturesUnordered`] will only be polled when they
    38→/// generate wake-up notifications. This reduces the required amount of work
    39→/// needed to poll large numbers of futures.
    40→///
    41→/// [`FuturesUnordered`] can be filled by [`collect`](Iterator::collect)ing an
    42→/// iterator of futures into a [`FuturesUnordered`], or by
    43→/// [`push`](FuturesUnordered::push)ing futures onto an existing
    44→/// [`FuturesUnordered`]. When new futures are added,
    45→/// [`poll_next`](Stream::poll_next) must be called in order to begin receiving
    46→/// wake-ups for new futures.
    47→///
    48→/// Note that you can create a ready-made [`FuturesUnordered`] via the
    49→/// [`collect`](Iterator::collect) method, or you can start with an empty set
    50→/// with the [`FuturesUnordered::new`] constructor.
    51→///
    52→/// This type is only available when the `std` or `alloc` feature of this
    53→/// library is activated, and it is activated by default.
    54→#[must_use = "streams do nothing unless polled"]
    55→pub struct FuturesUnordered<Fut> {
    56→    ready_to_run_queue: Arc<ReadyToRunQueue<Fut>>,
    57→    head_all: AtomicPtr<Task<Fut>>,
    58→    is_terminated: AtomicBool,
    59→}
    60→
    61→unsafe impl<Fut: Send> Send for FuturesUnordered<Fut> {}
    62→unsafe impl<Fut: Sync> Sync for FuturesUnordered<Fut> {}
    63→impl<Fut> Unpin for FuturesUnordered<Fut> {}
    64→
    65→impl Spawn for FuturesUnordered<FutureObj<'_, ()>> {
    66→    fn spawn_obj(&self, future_obj: FutureObj<'static, ()>)
    67→        -> Result<(), SpawnError>
    68→    {
    69→        self.push(future_obj);
    70→        Ok(())
    71→    }
    72→}
    73→
    74→impl LocalSpawn for FuturesUnordered<LocalFutureObj<'_, ()>> {
    75→    fn spawn_local_obj(&self, future_obj: LocalFutureObj<'static, ()>)
    76→        -> Result<(), SpawnError>
    77→    {
    78→        self.push(future_obj);
    79→        Ok(())
    80→    }
    81→}
