    83→// FuturesUnordered is implemented using two linked lists. One which links all
    84→// futures managed by a `FuturesUnordered` and one that tracks futures that have
    85→// been scheduled for polling. The first linked list allows for thread safe
    86→// insertion of nodes at the head as well as forward iteration, but is otherwise
    87→// not thread safe and is only accessed by the thread that owns the
    88→// `FuturesUnordered` value for any other operations. The second linked list is
    89→// an implementation of the intrusive MPSC queue algorithm described by
    90→// 1024cores.net.
    91→//
    92→// When a future is submitted to the set, a task is allocated and inserted in
    93→// both linked lists. The next call to `poll_next` will (eventually) see this
    94→// task and call `poll` on the future.
    95→//
    96→// Before a managed future is polled, the current context's waker is replaced
    97→// with one that is aware of the specific future being run. This ensures that
    98→// wake-up notifications generated by that specific future are visible to
    99→// `FuturesUnordered`. When a wake-up notification is received, the task is
   100→// inserted into the ready to run queue, so that its future can be polled later.
   101→//
   102→// Each task is wrapped in an `Arc` and thereby atomically reference counted.
   103→// Also, each task contains an `AtomicBool` which acts as a flag that indicates
   104→// whether the task is currently inserted in the atomic queue. When a wake-up
   105→// notifiaction is received, the task will only be inserted into the ready to
   106→// run queue if it isn't inserted already.
   107→
   108→impl<Fut> Default for FuturesUnordered<Fut> {
   109→    fn default() -> Self {
   110→        Self::new()
   111→    }
   112→}
   113→
   114→impl<Fut> FuturesUnordered<Fut> {
   115→    /// Constructs a new, empty [`FuturesUnordered`].
   116→    ///
   117→    /// The returned [`FuturesUnordered`] does not contain any futures.
   118→    /// In this state, [`FuturesUnordered::poll_next`](Stream::poll_next) will
   119→    /// return [`Poll::Ready(None)`](Poll::Ready).
   120→    pub fn new() -> Self {
   121→        let stub = Arc::new(Task {
   122→            future: UnsafeCell::new(None),
   123→            next_all: AtomicPtr::new(ptr::null_mut()),
   124→            prev_all: UnsafeCell::new(ptr::null()),
   125→            len_all: UnsafeCell::new(0),
   126→            next_ready_to_run: AtomicPtr::new(ptr::null_mut()),
   127→            queued: AtomicBool::new(true),
   128→            ready_to_run_queue: Weak::new(),
   129→        });
   130→        let stub_ptr = &*stub as *const Task<Fut>;
   131→        let ready_to_run_queue = Arc::new(ReadyToRunQueue {
   132→            waker: AtomicWaker::new(),
   133→            head: AtomicPtr::new(stub_ptr as *mut _),
   134→            tail: UnsafeCell::new(stub_ptr),
   135→            stub,
   136→        });
   137→
   138→        Self {
   139→            head_all: AtomicPtr::new(ptr::null_mut()),
   140→            ready_to_run_queue,
   141→            is_terminated: AtomicBool::new(false),
   142→        }
   143→    }
   144→
   145→    /// Returns the number of futures contained in the set.
   146→    ///
   147→    /// This represents the total number of in-flight futures.
   148→    pub fn len(&self) -> usize {
   149→        let (_, len) = self.atomic_load_head_and_len_all();
   150→        len
   151→    }
   152→
   153→    /// Returns `true` if the set contains no futures.
   154→    pub fn is_empty(&self) -> bool {
   155→        // Relaxed ordering can be used here since we don't need to read from
   156→        // the head pointer, only check whether it is null.
   157→        self.head_all.load(Relaxed).is_null()
   158→    }
   159→
   160→    /// Push a future into the set.
   161→    ///
   162→    /// This method adds the given future to the set. This method will not
   163→    /// call [`poll`](core::future::Future::poll) on the submitted future. The caller must
   164→    /// ensure that [`FuturesUnordered::poll_next`](Stream::poll_next) is called
   165→    /// in order to receive wake-up notifications for the given future.
   166→    pub fn push(&self, future: Fut) {
