   168→            future: UnsafeCell::new(Some(future)),
   169→            next_all: AtomicPtr::new(self.pending_next_all()),
   170→            prev_all: UnsafeCell::new(ptr::null_mut()),
   171→            len_all: UnsafeCell::new(0),
