// `IterPinMut` can be sent across threads safely because it borrows from
// `FuturesUnordered` with appropriate lifetime bounds, ensuring the underlying
// data structure's thread safety properties are preserved. `Task<Fut>` already
// implements `Send` and `Sync`, and the iterators inherit these properties
// through their lifetime-bound relationship to the parent `FuturesUnordered`.
unsafe impl<Fut: Send> Send for IterPinMut<'_, Fut> {}
unsafe impl<Fut: Sync> Sync for IterPinMut<'_, Fut> {}

// `IterMut` wraps `IterPinMut` and inherits the same safety properties.
unsafe impl<Fut: Send + Unpin> Send for IterMut<'_, Fut> {}
unsafe impl<Fut: Sync + Unpin> Sync for IterMut<'_, Fut> {}

// `IterPinRef` can be sent across threads safely for the same reasons as
// `IterPinMut`, with the additional safety of immutable access.
unsafe impl<Fut: Send> Send for IterPinRef<'_, Fut> {}
unsafe impl<Fut: Sync> Sync for IterPinRef<'_, Fut> {}

// `Iter` wraps `IterPinRef` and inherits the same safety properties.
unsafe impl<Fut: Send + Unpin> Send for Iter<'_, Fut> {}
