{"content": "/**
 * Reproduction script for NavLink relative="path" issue
 * Issue: NavLink is never active when using relative="path"
 */

// Set DEV flag for react-router
global.__DEV__ = true;

const React = require('react');

// Mock JSDOM environment for React Router
const { JSDOM } = require('jsdom');
const dom = new JSDOM('<!DOCTYPE html><html><body></body></html>', {
  url: 'https://example.com/',
  pretendToBeVisual: true,
  resources: 'usable'
});

global.window = dom.window;
global.document = dom.window.document;
global.navigator = dom.window.navigator;

// Now load React Router components
const { MemoryRouter, Routes, Route, NavLink } = require('./packages/react-router-dom');

// Test component to reproduce the issue
function TestNavLinkRelativePath() {
  return React.createElement(
    MemoryRouter,
    { initialEntries: ['/contact/1'] },
    React.createElement(
      Routes,
      null,
      React.createElement(
        Route,
        {
          path: '/contact/:id',
          element: React.createElement(NavLinkComponent)
        }
      )
    )
  );
}

function NavLinkComponent() {
  return React.createElement(
    'div',
    null,
    React.createElement(
      NavLink,
      {
        relative: 'path',
        to: '../1',
        className: ({ isActive }) => {
          console.log(`NavLink isActive: ${isActive}`);
          return isActive ? 'active' : 'inactive';
        }
      },
      'Michael'
    )
  );
}

// Simple test runner with timeout
function runTest() {
  console.log('Testing NavLink relative="path" issue...');
  console.log('Scenario:');
  console.log('  - Current URL: /contact/1'); 
  console.log('  - Route path: /contact/:id');
  console.log('  - NavLink to="../1" with relative="path"');
  console.log('  - Expected: NavLink should be active');

  try {
    const ReactTestRenderer = require('react-test-renderer');

    let renderer;
    ReactTestRenderer.act(() => {
      renderer = ReactTestRenderer.create(
        React.createElement(TestNavLinkRelativePath)
      );
    });

    const tree = renderer.toJSON();
    console.log('\nRendered component tree:', JSON.stringify(tree, null, 2));

    // Find the anchor element
    const anchor = renderer.root.findByType('a');
    const className = anchor.props.className;

    console.log(`\nNavLink className: "${className}"`);

    if (className === 'active') {
      console.log('✅ SUCCESS: NavLink is correctly active');
      return true;
    } else if (className === 'inactive') {
      console.log('❌ FAILURE: NavLink is not active');
      console.log('This confirms the bug described in the GitHub issue');
      return false;
    } else {
      console.log('❓ UNEXPECTED: NavLink has unexpected className');
      return false;
    }

  } catch (error) {
    console.log('❌ ERROR running test:', error.message);
    console.log(error.stack);
    return false;
  }
}

// Set up timeout (30 seconds)
const timeout = setTimeout(() => {
  console.log('\n❌ TIMEOUT: Test took longer than 30 seconds');
  process.exit(1);
}, 30000);

try {
  const success = runTest();
  clearTimeout(timeout);

  if (success) {
    console.log('\nTest completed successfully');
    process.exit(0);
  } else {
    console.log('\nTest completed with failures');
    process.exit(1);
  }
} catch (error) {
  clearTimeout(timeout);
  console.log('\n❌ FATAL ERROR:', error.message);
  console.log(error.stack);
  process.exit(1);
}", "file_path": "/workspace/react-router/reproduce_issue.js"}

