{"content": "/**
 * @jest-environment ./__tests__/custom-environment.js
 */

import { render } from "@testing-library/react";
import "@testing-library/jest-dom";
import * as React from "react";
import * as TestRenderer from "react-test-renderer";
import {
  MemoryRouter,
  Routes,
  Route,
  NavLink,
} from "react-router-dom";

describe("NavLink relative path behavior", () => {
  describe('when using relative="path"', () => {
    it('should be active when to="../id" resolves to current pathname', () => {
      let renderer: TestRenderer.ReactTestRenderer;
      TestRenderer.act(() => {
        renderer = TestRenderer.create(
          <MemoryRouter initialEntries={["/contact/1"]}>
            <Routes>
              <Route
                path="/contact/:id"
                element={
                  <NavLink
                    to="../1"
                    relative="path"
                    className={({ isActive }) => isActive ? "active" : "inactive"}
                  >
                    Contact 1
                  </NavLink>
                }
              />
            </Routes>
          </MemoryRouter>
        );
      });

      let anchor = renderer.root.findByType("a");
      expect(anchor.props.className).toBe("active");
      expect(anchor.props.href).toBe("/contact/1");
    });

    it('should not be active when to="../id" resolves to different pathname', () => {
      let renderer: TestRenderer.ReactTestRenderer;
      TestRenderer.act(() => {
        renderer = TestRenderer.create(
          <MemoryRouter initialEntries={["/contact/2"]}>
            <Routes>
              <Route
                path="/contact/:id"
                element={
                  <NavLink
                    to="../1"
                    relative="path"
                    className={({ isActive }) => isActive ? "active" : "inactive"}
                  >
                    Contact 1
                  </NavLink>
                }
              />
            </Routes>
          </MemoryRouter>
        );
      });

      let anchor = renderer.root.findByType("a");
      expect(anchor.props.className).toBe("inactive");
      expect(anchor.props.href).toBe("/contact/1");
    });

    it('should work with nested routes', () => {
      let renderer: TestRenderer.ReactTestRenderer;
      TestRenderer.act(() => {
        renderer = TestRenderer.create(
          <MemoryRouter initialEntries={["/app/users/123/profile"]}>
            <Routes>
              <Route path="/app/users/:userId/*" element={<UserLayout />} />
            </Routes>
          </MemoryRouter>
        );
      });

      let anchor = renderer.root.findByType("a");
      expect(anchor.props.className).toBe("active");
      expect(anchor.props.href).toBe("/app/users/123");

      function UserLayout() {
        return (
          <div>
            <NavLink
              to="../../123"
              relative="path"
              className={({ isActive }) => isActive ? "active" : "inactive"}
            >
              User 123
            </NavLink>
            <Routes>
              <Route path="profile" element={<div>Profile</div>} />
            </Routes>
          </div>
        );
      }
    });

    it('should work with end=true', () => {
      let renderer: TestRenderer.ReactTestRenderer;
      TestRenderer.act(() => {
        renderer = TestRenderer.create(
          <MemoryRouter initialEntries={["/contact/1/edit"]}>
            <Routes>
              <Route
                path="/contact/:id/*"
                element={
                  <div>
                    <NavLink
                      to="../1"
                      relative="path"
                      end={true}
                      className={({ isActive }) => isActive ? "active" : "inactive"}
                    >
                      Contact 1
                    </NavLink>
                    <Routes>
                      <Route path="edit" element={<div>Edit</div>} />
                    </Routes>
                  </div>
                }
              />
            </Routes>
          </MemoryRouter>
        );
      });

      let anchor = renderer.root.findByType("a");
      // Should not be active because end=true and we're at /contact/1/edit
      expect(anchor.props.className).toBe("inactive");
      expect(anchor.props.href).toBe("/contact/1");
    });
  });

  describe('regression tests', () => {
    it('should not break existing behavior without relative prop', () => {
      let renderer: TestRenderer.ReactTestRenderer;
      TestRenderer.act(() => {
        renderer = TestRenderer.create(
          <MemoryRouter initialEntries={["/contact/1"]}>
            <Routes>
              <Route
                path="/contact/:id"
                element={
                  <NavLink
                    to="/contact/1"
                    className={({ isActive }) => isActive ? "active" : "inactive"}
                  >
                    Contact 1
                  </NavLink>
                }
              />
            </Routes>
          </MemoryRouter>
        );
      });

      let anchor = renderer.root.findByType("a");
      expect(anchor.props.className).toBe("active");
      expect(anchor.props.href).toBe("/contact/1");
    });

    it('should not break existing relative="route" behavior', () => {
      let renderer: TestRenderer.ReactTestRenderer;
      TestRenderer.act(() => {
        renderer = TestRenderer.create(
          <MemoryRouter initialEntries={["/contact/1"]}>
            <Routes>
              <Route
                path="/contact/:id"
                element={
                  <NavLink
                    to="."
                    relative="route"
                    className={({ isActive }) => isActive ? "active" : "inactive"}
                  >
                    Current Contact
                  </NavLink>
                }
              />
            </Routes>
          </MemoryRouter>
        );
      });

      let anchor = renderer.root.findByType("a");
      expect(anchor.props.className).toBe("active");
      expect(anchor.props.href).toBe("/contact/1");
    });
  });
