   343→// printHelpCustom is the default implementation of HelpPrinterCustom.
   344→//
   345→// The customFuncs map will be combined with a default template.FuncMap to
   346→// allow using arbitrary functions in template rendering.
   347→func printHelpCustom(out io.Writer, templ string, data interface{}, customFuncs map[string]interface{}) {
   348→
   349→	const maxLineLength = 10000
   350→
   351→	funcMap := template.FuncMap{
   352→		"join":           strings.Join,
   353→		"subtract":       subtract,
   354→		"indent":         indent,
   355→		"nindent":        nindent,
   356→		"trim":           strings.TrimSpace,
   357→		"wrap":           func(input string, offset int) string { return wrap(input, offset, maxLineLength) },
   358→		"offset":         offset,
   359→		"offsetCommands": offsetCommands,
   360→	}
   361→
   362→	if customFuncs["wrapAt"] != nil {
   363→		if wa, ok := customFuncs["wrapAt"]; ok {
   364→			if waf, ok := wa.(func() int); ok {
   365→				wrapAt := waf()
   366→				customFuncs["wrap"] = func(input string, offset int) string {
   367→					return wrap(input, offset, wrapAt)
   368→				}
   369→			}
   370→		}
   371→	}
   372→
   373→	for key, value := range customFuncs {
   374→		funcMap[key] = value
   375→	}
   376→
   377→	w := tabwriter.NewWriter(out, 1, 8, 2, ' ', 0)
   378→	t := template.Must(template.New("help").Funcs(funcMap).Parse(templ))
   379→	t.New("helpNameTemplate").Parse(helpNameTemplate)
   380→	t.New("usageTemplate").Parse(usageTemplate)
   381→	t.New("descriptionTemplate").Parse(descriptionTemplate)
   382→	t.New("visibleCommandTemplate").Parse(visibleCommandTemplate)
   383→	t.New("copyrightTemplate").Parse(copyrightTemplate)
   384→	t.New("versionTemplate").Parse(versionTemplate)
   385→	t.New("visibleFlagCategoryTemplate").Parse(visibleFlagCategoryTemplate)
   386→	t.New("visibleFlagTemplate").Parse(visibleFlagTemplate)
   387→	t.New("visibleGlobalFlagCategoryTemplate").Parse(strings.Replace(visibleFlagCategoryTemplate, "OPTIONS", "GLOBAL OPTIONS", -1))
   388→	t.New("authorsTemplate").Parse(authorsTemplate)
   389→	t.New("visibleCommandCategoryTemplate").Parse(visibleCommandCategoryTemplate)
   390→
   391→	err := t.Execute(w, data)
   392→	if err != nil {
   393→		// If the writer is closed, t.Execute will fail, and there's nothing
   394→		// we can do to recover.
   395→		if os.Getenv("CLI_TEMPLATE_ERROR_DEBUG") != "" {
   396→			_, _ = fmt.Fprintf(ErrWriter, "CLI TEMPLATE ERROR: %#v\n", err)
   397→		}
   398→		return
   399→	}
   400→	_ = w.Flush()
   401→}
