   492→func wrap(input string, offset int, wrapAt int) string {
   493→	var ss []string
   494→
   495→	lines := strings.Split(input, "\n")
   496→
   497→	padding := strings.Repeat(" ", offset)
   498→
   499→	for i, line := range lines {
   500→		if line == "" {
   501→			ss = append(ss, line)
   502→		} else {
   503→			wrapped := wrapLine(line, offset, wrapAt, padding)
   504→			if i == 0 {
   505→				ss = append(ss, wrapped)
   506→			} else {
   507→				ss = append(ss, padding+wrapped)
   508→
   509→			}
   510→
   511→		}
   512→	}
   513→
   514→	return strings.Join(ss, "\n")
   515→}
   516→
   517→func wrapLine(input string, offset int, wrapAt int, padding string) string {
   518→	if wrapAt <= offset || len(input) <= wrapAt-offset {
   519→		return input
   520→	}
   521→
   522→	lineWidth := wrapAt - offset
   523→	words := strings.Fields(input)
   524→	if len(words) == 0 {
   525→		return input
   526→	}
   527→
   528→	wrapped := words[0]
   529→	spaceLeft := lineWidth - len(wrapped)
   530→	for _, word := range words[1:] {
   531→		if len(word)+1 > spaceLeft {
   532→			wrapped += "\n" + padding + word
   533→			spaceLeft = lineWidth - len(word)
   534→		} else {
   535→			wrapped += " " + word
   536→			spaceLeft -= 1 + len(word)
   537→		}
   538→	}
   539→
   540→	return wrapped
   541→}
