   547→// this function tries to find the max width of the names column
   548→// so say we have the following rows for help
   549→//
   550→//	foo1, foo2, foo3  some string here
   551→//	bar1, b2 some other string here
   552→//
   553→// We want to offset the 2nd row usage by some amount so that everything
   554→// is aligned
   555→//
   556→//	foo1, foo2, foo3  some string here
   557→//	bar1, b2          some other string here
   558→//
   559→// to find that offset we find the length of all the rows and use the max
   560→// to calculate the offset
   561→func offsetCommands(cmds []*Command, fixed int) int {
   562→	var max int = 0
   563→	for _, cmd := range cmds {
   564→		s := strings.Join(cmd.Names(), ", ")
   565→		if len(s) > max {
   566→			max = len(s)
   567→		}
   568→	}
   569→	return max + fixed
   570→}
