   154→      }
   155→      throw errorReading(request, response, e);
   156→    } finally {
   157→      if (shouldClose) {
   158→        ensureClosed(response.body());
   159→      }
   160→    }
   161→  }
   162→
   163→  long elapsedTime(long start) {
   164→    return TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
   165→  }
   166→
   167→  Request targetRequest(RequestTemplate template) {
   168→    for (RequestInterceptor interceptor : requestInterceptors) {
   169→      interceptor.apply(template);
   170→    }
   171→    return target.apply(template);
   172→  }
   173→
   174→  Object decode(Response response) throws Throwable {
   175→    try {
   176→      return decoder.decode(response, metadata.returnType());
   177→    } catch (FeignException e) {
   178→      throw e;
   179→    } catch (RuntimeException e) {
   180→      throw new DecodeException(response.status(), e.getMessage(), e);
   181→    }
   182→  }
   183→
   184→  static class Factory {
   185→
   186→    private final Client client;
   187→    private final Retryer retryer;
   188→    private final List<RequestInterceptor> requestInterceptors;
   189→    private final Logger logger;
   190→    private final Logger.Level logLevel;
   191→    private final boolean decode404;
   192→    private final boolean closeAfterDecode;
   193→    private final ExceptionPropagationPolicy propagationPolicy;
   194→
   195→    Factory(Client client, Retryer retryer, List<RequestInterceptor> requestInterceptors,
   196→        Logger logger, Logger.Level logLevel, boolean decode404, boolean closeAfterDecode,
   197→        ExceptionPropagationPolicy propagationPolicy) {
   198→      this.client = checkNotNull(client, "client");
   199→      this.retryer = checkNotNull(retryer, "retryer");
   200→      this.requestInterceptors = checkNotNull(requestInterceptors, "requestInterceptors");
   201→      this.logger = checkNotNull(logger, "logger");
   202→      this.logLevel = checkNotNull(logLevel, "logLevel");
   203→      this.decode404 = decode404;
   204→      this.closeAfterDecode = closeAfterDecode;
   205→      this.propagationPolicy = propagationPolicy;
   206→    }
   207→
   208→    public MethodHandler create(Target<?> target,
   209→                                MethodMetadata md,
   210→                                RequestTemplate.Factory buildTemplateFromArgs,
   211→                                Options options,
   212→                                Decoder decoder,
   213→                                ErrorDecoder errorDecoder) {
   214→      return new SynchronousMethodHandler(target, client, retryer, requestInterceptors, logger,
   215→          logLevel, md, buildTemplateFromArgs, options, decoder,
   216→          errorDecoder, decode404, closeAfterDecode, propagationPolicy);
