    19→import java.lang.reflect.Proxy;
    20→import java.util.*;
    21→import java.util.Map.Entry;
    22→import feign.InvocationHandlerFactory.MethodHandler;
    23→import feign.Param.Expander;
    24→import feign.Request.Options;
    25→import feign.codec.Decoder;
