    32→public class ReflectiveFeign extends Feign {
    33→
    34→  private final ParseHandlersByName targetToHandlersByName;
    35→  private final InvocationHandlerFactory factory;
    36→  private final QueryMapEncoder queryMapEncoder;
    37→
    38→  ReflectiveFeign(ParseHandlersByName targetToHandlersByName, InvocationHandlerFactory factory,
    39→      QueryMapEncoder queryMapEncoder) {
    40→    this.targetToHandlersByName = targetToHandlersByName;
    41→    this.factory = factory;
    42→    this.queryMapEncoder = queryMapEncoder;
    43→  }
    44→
    45→  /**
    46→   * creates an api binding to the {@code target}. As this invokes reflection, care should be taken
    47→   * to cache the result.
    48→   */
    49→  @SuppressWarnings("unchecked")
    50→  @Override
    51→  public <T> T newInstance(Target<T> target) {
    52→    Map<String, MethodHandler> nameToHandler = targetToHandlersByName.apply(target);
    53→    Map<Method, MethodHandler> methodToHandler = new LinkedHashMap<Method, MethodHandler>();
    54→    List<DefaultMethodHandler> defaultMethodHandlers = new LinkedList<DefaultMethodHandler>();
    55→
    56→    for (Method method : target.type().getMethods()) {
    57→      if (method.getDeclaringClass() == Object.class) {
    58→        continue;
    59→      } else if (Util.isDefault(method)) {
    60→        DefaultMethodHandler handler = new DefaultMethodHandler(method);
    61→        defaultMethodHandlers.add(handler);
    62→        methodToHandler.put(method, handler);
    63→      } else {
    64→        methodToHandler.put(method, nameToHandler.get(Feign.configKey(target.type(), method)));
    65→      }
    66→    }
    67→    InvocationHandler handler = factory.create(target, methodToHandler);
    68→    T proxy = (T) Proxy.newProxyInstance(target.type().getClassLoader(),
    69→        new Class<?>[] {target.type()}, handler);
    70→
    71→    for (DefaultMethodHandler defaultMethodHandler : defaultMethodHandlers) {
    72→      defaultMethodHandler.bindTo(proxy);
    73→    }
    74→    return proxy;
    75→  }
    76→
    77→  static class FeignInvocationHandler implements InvocationHandler {
    78→
    79→    private final Target target;
    80→    private final Map<Method, MethodHandler> dispatch;
    81→
    82→    FeignInvocationHandler(Target target, Map<Method, MethodHandler> dispatch) {
    83→      this.target = checkNotNull(target, "target");
    84→      this.dispatch = checkNotNull(dispatch, "dispatch for %s", target);
    85→    }
    86→
    87→    @Override
    88→    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
    89→      if ("equals".equals(method.getName())) {
    90→        try {
    91→          Object otherHandler =
    92→              args.length > 0 && args[0] != null ? Proxy.getInvocationHandler(args[0]) : null;
    93→          return equals(otherHandler);
    94→        } catch (IllegalArgumentException e) {
    95→          return false;
    96→        }
    97→      } else if ("hashCode".equals(method.getName())) {
    98→        return hashCode();
    99→      } else if ("toString".equals(method.getName())) {
   100→        return toString();
   101→      }
   102→
   103→      return dispatch.get(method).invoke(args);
   104→    }
   105→
   106→    @Override
   107→    public boolean equals(Object obj) {
   108→      if (obj instanceof FeignInvocationHandler) {
   109→        FeignInvocationHandler other = (FeignInvocationHandler) obj;
   110→        return target.equals(other.target);
   111→      }
   112→      return false;
   113→    }
   114→
   115→    @Override
   116→    public int hashCode() {
   117→      return target.hashCode();
   118→    }
   119→
   120→    @Override
   121→    public String toString() {
   122→      return target.toString();
   123→    }
   124→  }
   125→
   126→  static final class ParseHandlersByName {
   127→
   128→    private final Contract contract;
   129→    private final Options options;
   130→    private final Encoder encoder;
   131→    private final Decoder decoder;
   132→    private final ErrorDecoder errorDecoder;
   133→    private final QueryMapEncoder queryMapEncoder;
   134→    private final SynchronousMethodHandler.Factory factory;
   135→
   136→    ParseHandlersByName(
   137→        Contract contract,
   138→        Options options,
   139→        Encoder encoder,
   140→        Decoder decoder,
   141→        QueryMapEncoder queryMapEncoder,
   142→        ErrorDecoder errorDecoder,
   143→        SynchronousMethodHandler.Factory factory) {
   144→      this.contract = contract;
   145→      this.options = options;
   146→      this.factory = factory;
   147→      this.errorDecoder = errorDecoder;
   148→      this.queryMapEncoder = queryMapEncoder;
   149→      this.encoder = checkNotNull(encoder, "encoder");
   150→      this.decoder = checkNotNull(decoder, "decoder");
   151→    }
   152→
   153→    public Map<String, MethodHandler> apply(Target key) {
   154→      List<MethodMetadata> metadata = contract.parseAndValidatateMetadata(key.type());
   155→      Map<String, MethodHandler> result = new LinkedHashMap<String, MethodHandler>();
   156→      for (MethodMetadata md : metadata) {
   157→        BuildTemplateByResolvingArgs buildTemplate;
   158→        if (!md.formParams().isEmpty() && md.template().bodyTemplate() == null) {
   159→          buildTemplate = new BuildFormEncodedTemplateFromArgs(md, encoder, queryMapEncoder);
   160→        } else if (md.bodyIndex() != null) {
   161→          buildTemplate = new BuildEncodedTemplateFromArgs(md, encoder, queryMapEncoder);
   162→        } else {
   163→          buildTemplate = new BuildTemplateByResolvingArgs(md, queryMapEncoder);
   164→        }
   165→        result.put(md.configKey(),
   166→            factory.create(key, md, buildTemplate, options, decoder, errorDecoder));
   167→      }
   168→      return result;
   169→    }
   170→  }
   171→
   172→  private static class BuildTemplateByResolvingArgs implements RequestTemplate.Factory {
   173→
   174→    private final QueryMapEncoder queryMapEncoder;
   175→
   176→    protected final MethodMetadata metadata;
   177→    private final Map<Integer, Expander> indexToExpander = new LinkedHashMap<Integer, Expander>();
   178→
   179→    private BuildTemplateByResolvingArgs(MethodMetadata metadata, QueryMapEncoder queryMapEncoder) {
   180→      this.metadata = metadata;
   181→      this.queryMapEncoder = queryMapEncoder;
   182→      if (metadata.indexToExpander() != null) {
   183→        indexToExpander.putAll(metadata.indexToExpander());
   184→        return;
   185→      }
   186→      if (metadata.indexToExpanderClass().isEmpty()) {
   187→        return;
   188→      }
   189→      for (Entry<Integer, Class<? extends Expander>> indexToExpanderClass : metadata
   190→          .indexToExpanderClass().entrySet()) {
   191→        try {
   192→          indexToExpander
   193→              .put(indexToExpanderClass.getKey(), indexToExpanderClass.getValue().newInstance());
   194→        } catch (InstantiationException e) {
   195→          throw new IllegalStateException(e);
   196→        } catch (IllegalAccessException e) {
   197→          throw new IllegalStateException(e);
   198→        }
   199→      }
   200→    }
   201→
   202→    @Override
   203→    public RequestTemplate create(Object[] argv) {
   204→      RequestTemplate mutable = RequestTemplate.from(metadata.template());
   205→      if (metadata.urlIndex() != null) {
   206→        int urlIndex = metadata.urlIndex();
   207→        checkArgument(argv[urlIndex] != null, "URI parameter %s was null", urlIndex);
   208→        mutable.target(String.valueOf(argv[urlIndex]));
   209→      }
   210→      Map<String, Object> varBuilder = new LinkedHashMap<String, Object>();
   211→      for (Entry<Integer, Collection<String>> entry : metadata.indexToName().entrySet()) {
   212→        int i = entry.getKey();
   213→        Object value = argv[entry.getKey()];
   214→        if (value != null) { // Null values are skipped.
   215→          if (indexToExpander.containsKey(i)) {
   216→            value = expandElements(indexToExpander.get(i), value);
   217→          }
   218→          for (String name : entry.getValue()) {
   219→            varBuilder.put(name, value);
   220→          }
   221→        }
   222→      }
   223→
   224→      RequestTemplate template = resolve(argv, mutable, varBuilder);
   225→      if (metadata.queryMapIndex() != null) {
   226→        // add query map parameters after initial resolve so that they take
   227→        // precedence over any predefined values
   228→        Object value = argv[metadata.queryMapIndex()];
   229→        Map<String, Object> queryMap = toQueryMap(value);
   230→        template = addQueryMapQueryParameters(queryMap, template);
   231→      }
   232→
   233→      if (metadata.headerMapIndex() != null) {
   234→        template =
   235→            addHeaderMapHeaders((Map<String, Object>) argv[metadata.headerMapIndex()], template);
   236→      }
   237→
   238→      return template;
   239→    }
   240→
   241→    private Map<String, Object> toQueryMap(Object value) {
   242→      if (value instanceof Map) {
   243→        return (Map<String, Object>) value;
   244→      }
   245→      try {
   246→        return queryMapEncoder.encode(value);
   247→      } catch (EncodeException e) {
   248→        throw new IllegalStateException(e);
   249→      }
   250→    }
   251→
   252→    private Object expandElements(Expander expander, Object value) {
   253→      if (value instanceof Iterable) {
   254→        return expandIterable(expander, (Iterable) value);
   255→      }
   256→      return expander.expand(value);
   257→    }
   258→
   259→    private List<String> expandIterable(Expander expander, Iterable value) {
   260→      List<String> values = new ArrayList<String>();
   261→      for (Object element : value) {
   262→        if (element != null) {
   263→          values.add(expander.expand(element));
   264→        }
   265→      }
   266→      return values;
   267→    }
   268→
   269→    @SuppressWarnings("unchecked")
   270→    private RequestTemplate addHeaderMapHeaders(Map<String, Object> headerMap,
   271→                                                RequestTemplate mutable) {
   272→      for (Entry<String, Object> currEntry : headerMap.entrySet()) {
   273→        Collection<String> values = new ArrayList<String>();
   274→
   275→        Object currValue = currEntry.getValue();
   276→        if (currValue instanceof Iterable<?>) {
   277→          Iterator<?> iter = ((Iterable<?>) currValue).iterator();
   278→          while (iter.hasNext()) {
   279→            Object nextObject = iter.next();
   280→            values.add(nextObject == null ? null : nextObject.toString());
   281→          }
   282→        } else {
   283→          values.add(currValue == null ? null : currValue.toString());
   284→        }
   285→
   286→        mutable.header(currEntry.getKey(), values);
   287→      }
   288→      return mutable;
   289→    }
   290→
   291→    @SuppressWarnings("unchecked")
   292→    private RequestTemplate addQueryMapQueryParameters(Map<String, Object> queryMap,
   293→                                                       RequestTemplate mutable) {
   294→      for (Entry<String, Object> currEntry : queryMap.entrySet()) {
   295→        Collection<String> values = new ArrayList<String>();
   296→
   297→        boolean encoded = metadata.queryMapEncoded();
   298→        Object currValue = currEntry.getValue();
   299→        if (currValue instanceof Iterable<?>) {
   300→          Iterator<?> iter = ((Iterable<?>) currValue).iterator();
   301→          while (iter.hasNext()) {
   302→            Object nextObject = iter.next();
   303→            values.add(nextObject == null ? null
   304→                : encoded ? nextObject.toString()
   305→                    : UriUtils.encode(nextObject.toString()));
   306→          }
   307→        } else {
   308→          values.add(currValue == null ? null
   309→              : encoded ? currValue.toString() : UriUtils.encode(currValue.toString()));
   310→        }
   311→
   312→        mutable.query(encoded ? currEntry.getKey() : UriUtils.encode(currEntry.getKey()), values);
   313→      }
   314→      return mutable;
   315→    }
   316→
   317→    protected RequestTemplate resolve(Object[] argv,
   318→                                      RequestTemplate mutable,
   319→                                      Map<String, Object> variables) {
   320→      return mutable.resolve(variables);
   321→    }
   322→  }
   323→
   324→  private static class BuildFormEncodedTemplateFromArgs extends BuildTemplateByResolvingArgs {
   325→
   326→    private final Encoder encoder;
   327→
   328→    private BuildFormEncodedTemplateFromArgs(MethodMetadata metadata, Encoder encoder,
   329→        QueryMapEncoder queryMapEncoder) {
   330→      super(metadata, queryMapEncoder);
   331→      this.encoder = encoder;
   332→    }
   333→
   334→    @Override
   335→    protected RequestTemplate resolve(Object[] argv,
   336→                                      RequestTemplate mutable,
   337→                                      Map<String, Object> variables) {
   338→      Map<String, Object> formVariables = new LinkedHashMap<String, Object>();
   339→      for (Entry<String, Object> entry : variables.entrySet()) {
   340→        if (metadata.formParams().contains(entry.getKey())) {
   341→          formVariables.put(entry.getKey(), entry.getValue());
   342→        }
   343→      }
   344→      try {
   345→        encoder.encode(formVariables, Encoder.MAP_STRING_WILDCARD, mutable);
   346→      } catch (EncodeException e) {
   347→        throw e;
   348→      } catch (RuntimeException e) {
   349→        throw new EncodeException(e.getMessage(), e);
   350→      }
   351→      return super.resolve(argv, mutable, variables);
   352→    }
   353→  }
   354→
   355→  private static class BuildEncodedTemplateFromArgs extends BuildTemplateByResolvingArgs {
   356→
   357→    private final Encoder encoder;
   358→
   359→    private BuildEncodedTemplateFromArgs(MethodMetadata metadata, Encoder encoder,
   360→        QueryMapEncoder queryMapEncoder) {
   361→      super(metadata, queryMapEncoder);
   362→      this.encoder = encoder;
   363→    }
   364→
   365→    @Override
   366→    protected RequestTemplate resolve(Object[] argv,
   367→                                      RequestTemplate mutable,
   368→                                      Map<String, Object> variables) {
   369→      Object body = argv[metadata.bodyIndex()];
   370→      checkArgument(body != null, "Body parameter %s was null", metadata.bodyIndex());
   371→      try {
   372→        encoder.encode(body, metadata.bodyType(), mutable);
   373→      } catch (EncodeException e) {
   374→        throw e;
   375→      } catch (RuntimeException e) {
   376→        throw new EncodeException(e.getMessage(), e);
   377→      }
   378→      return super.resolve(argv, mutable, variables);
   379→    }
   380→  }
   381→}
