    33→/**
    34→ * Defines what annotations and values are valid on interfaces.
    35→ */
    36→public interface Contract {
    37→
    38→  /**
    39→   * Called to parse the methods in the class that are linked to HTTP requests.
    40→   *
    41→   * @param targetType {@link feign.Target#type() type} of the Feign interface.
    42→   */
    43→  // TODO: break this and correct spelling at some point
    44→  List<MethodMetadata> parseAndValidatateMetadata(Class<?> targetType);
    45→
    46→  abstract class BaseContract implements Contract {
    47→
    48→    @Override
    49→    public List<MethodMetadata> parseAndValidatateMetadata(Class<?> targetType) {
    50→      checkState(targetType.getTypeParameters().length == 0, "Parameterized types unsupported: %s",
    51→          targetType.getSimpleName());
    52→      checkState(targetType.getInterfaces().length <= 1, "Only single inheritance supported: %s",
    53→          targetType.getSimpleName());
    54→      if (targetType.getInterfaces().length == 1) {
    55→        checkState(targetType.getInterfaces()[0].getInterfaces().length == 0,
    56→            "Only single-level inheritance supported: %s",
    57→            targetType.getSimpleName());
    58→      }
    59→      Map<String, MethodMetadata> result = new LinkedHashMap<String, MethodMetadata>();
    60→      for (Method method : targetType.getMethods()) {
    61→        if (method.getDeclaringClass() == Object.class ||
    62→            (method.getModifiers() & Modifier.STATIC) != 0 ||
    63→            Util.isDefault(method)) {
    64→          continue;
    65→        }
    66→        MethodMetadata metadata = parseAndValidateMetadata(targetType, method);
    67→        checkState(!result.containsKey(metadata.configKey()), "Overrides unsupported: %s",
    68→            metadata.configKey());
    69→        result.put(metadata.configKey(), metadata);
    70→      }
    71→      return new ArrayList<>(result.values());
    72→    }
    73→
    74→    /**
    75→     * @deprecated use {@link #parseAndValidateMetadata(Class, Method)} instead.
    76→     */
    77→    @Deprecated
    78→    public MethodMetadata parseAndValidatateMetadata(Method method) {
    79→      return parseAndValidateMetadata(method.getDeclaringClass(), method);
    80→    }
    81→
    82→    /**
    83→     * Called indirectly by {@link #parseAndValidatateMetadata(Class)}.
    84→     */
    85→    protected MethodMetadata parseAndValidateMetadata(Class<?> targetType, Method method) {
    86→      MethodMetadata data = new MethodMetadata();
    87→      data.returnType(Types.resolve(targetType, targetType, method.getGenericReturnType()));
    88→      data.configKey(Feign.configKey(targetType, method));
    89→
    90→      if (targetType.getInterfaces().length == 1) {
    91→        processAnnotationOnClass(data, targetType.getInterfaces()[0]);
    92→      }
    93→      processAnnotationOnClass(data, targetType);
    94→
    95→
    96→      for (Annotation methodAnnotation : method.getAnnotations()) {
    97→        processAnnotationOnMethod(data, methodAnnotation, method);
    98→      }
    99→      checkState(data.template().method() != null,
   100→          "Method %s not annotated with HTTP method type (ex. GET, POST)",
   101→          method.getName());
   102→      Class<?>[] parameterTypes = method.getParameterTypes();
   103→      Type[] genericParameterTypes = method.getGenericParameterTypes();
   104→
   105→      Annotation[][] parameterAnnotations = method.getParameterAnnotations();
   106→      int count = parameterAnnotations.length;
   107→      for (int i = 0; i < count; i++) {
   108→        boolean isHttpAnnotation = false;
   109→        if (parameterAnnotations[i] != null) {
   110→          isHttpAnnotation = processAnnotationsOnParameter(data, parameterAnnotations[i], i);
   111→        }
   112→        if (parameterTypes[i] == URI.class) {
   113→          data.urlIndex(i);
   114→        } else if (!isHttpAnnotation) {
   115→          checkState(data.formParams().isEmpty(),
   116→              "Body parameters cannot be used with form parameters.");
   117→          checkState(data.bodyIndex() == null, "Method has too many Body parameters: %s", method);
   118→          data.bodyIndex(i);
   119→          data.bodyType(Types.resolve(targetType, targetType, genericParameterTypes[i]));
   120→        }
   121→      }
   122→
   123→      if (data.headerMapIndex() != null) {
   124→        checkMapString("HeaderMap", parameterTypes[data.headerMapIndex()],
   125→            genericParameterTypes[data.headerMapIndex()]);
   126→      }
   127→
   128→      if (data.queryMapIndex() != null) {
   129→        if (Map.class.isAssignableFrom(parameterTypes[data.queryMapIndex()])) {
   130→          checkMapKeys("QueryMap", genericParameterTypes[data.queryMapIndex()]);
   131→        }
   132→      }
   133→
   134→      return data;
   135→    }
   136→
   137→    private static void checkMapString(String name, Class<?> type, Type genericType) {
   138→      checkState(Map.class.isAssignableFrom(type),
   139→          "%s parameter must be a Map: %s", name, type);
   140→      checkMapKeys(name, genericType);
   141→    }
   142→
   143→    private static void checkMapKeys(String name, Type genericType) {
   144→      Class<?> keyClass = null;
   145→
   146→      // assume our type parameterized
   147→      if (ParameterizedType.class.isAssignableFrom(genericType.getClass())) {
   148→        Type[] parameterTypes = ((ParameterizedType) genericType).getActualTypeArguments();
   149→        keyClass = (Class<?>) parameterTypes[0];
   150→      } else if (genericType instanceof Class<?>) {
   151→        // raw class, type parameters cannot be inferred directly, but we can scan any extended
   152→        // interfaces looking for any explict types
   153→        Type[] interfaces = ((Class) genericType).getGenericInterfaces();
   154→        if (interfaces != null) {
   155→          for (Type extended : interfaces) {
   156→            if (ParameterizedType.class.isAssignableFrom(extended.getClass())) {
   157→              // use the first extended interface we find.
   158→              Type[] parameterTypes = ((ParameterizedType) extended).getActualTypeArguments();
   159→              keyClass = (Class<?>) parameterTypes[0];
   160→              break;
   161→            }
   162→          }
   163→        }
   164→      }
   165→
   166→      if (keyClass != null) {
   167→        checkState(String.class.equals(keyClass),
   168→            "%s key must be a String: %s", name, keyClass.getSimpleName());
   169→      }
   170→    }
   171→
   172→
   173→    /**
   174→     * Called by parseAndValidateMetadata twice, first on the declaring class, then on the target
   175→     * type (unless they are the same).
   176→     *
   177→     * @param data metadata collected so far relating to the current java method.
   178→     * @param clz the class to process
   179→     */
   180→    protected abstract void processAnnotationOnClass(MethodMetadata data, Class<?> clz);
   181→
   182→    /**
   183→     * @param data metadata collected so far relating to the current java method.
   184→     * @param annotation annotations present on the current method annotation.
   185→     * @param method method currently being processed.
   186→     */
   187→    protected abstract void processAnnotationOnMethod(MethodMetadata data,
   188→                                                      Annotation annotation,
   189→                                                      Method method);
   190→
   191→    /**
   192→     * @param data metadata collected so far relating to the current java method.
   193→     * @param annotations annotations present on the current parameter annotation.
   194→     * @param paramIndex if you find a name in {@code annotations}, call
   195→     *        {@link #nameParam(MethodMetadata, String, int)} with this as the last parameter.
   196→     * @return true if you called {@link #nameParam(MethodMetadata, String, int)} after finding an
   197→     *         http-relevant annotation.
   198→     */
   199→    protected abstract boolean processAnnotationsOnParameter(MethodMetadata data,
   200→                                                             Annotation[] annotations,
   201→                                                             int paramIndex);
   202→
   203→    /**
   204→     * links a parameter name to its index in the method signature.
   205→     */
   206→    protected void nameParam(MethodMetadata data, String name, int i) {
   207→      Collection<String> names =
   208→          data.indexToName().containsKey(i) ? data.indexToName().get(i) : new ArrayList<String>();
   209→      names.add(name);
   210→      data.indexToName().put(i, names);
   211→    }
   212→  }
   213→
   214→  class Default extends BaseContract {
   215→
   216→    static final Pattern REQUEST_LINE_PATTERN = Pattern.compile("^([A-Z]+)[ ]*(.*)$");
   217→
   218→    @Override
   219→    protected void processAnnotationOnClass(MethodMetadata data, Class<?> targetType) {
   220→      if (targetType.isAnnotationPresent(Headers.class)) {
   221→        String[] headersOnType = targetType.getAnnotation(Headers.class).value();
   222→        checkState(headersOnType.length > 0, "Headers annotation was empty on type %s.",
   223→            targetType.getName());
   224→        Map<String, Collection<String>> headers = toMap(headersOnType);
   225→        headers.putAll(data.template().headers());
   226→        data.template().headers(null); // to clear
   227→        data.template().headers(headers);
   228→      }
   229→    }
   230→
   231→    @Override
   232→    protected void processAnnotationOnMethod(MethodMetadata data,
   233→                                             Annotation methodAnnotation,
   234→                                             Method method) {
   235→      Class<? extends Annotation> annotationType = methodAnnotation.annotationType();
   236→      if (annotationType == RequestLine.class) {
   237→        String requestLine = RequestLine.class.cast(methodAnnotation).value();
   238→        checkState(emptyToNull(requestLine) != null,
   239→            "RequestLine annotation was empty on method %s.", method.getName());
   240→
   241→        Matcher requestLineMatcher = REQUEST_LINE_PATTERN.matcher(requestLine);
   242→        if (!requestLineMatcher.find()) {
   243→          throw new IllegalStateException(String.format(
   244→              "RequestLine annotation didn't start with an HTTP verb on method %s",
   245→              method.getName()));
   246→        } else {
   247→          data.template().method(HttpMethod.valueOf(requestLineMatcher.group(1)));
   248→          data.template().uri(requestLineMatcher.group(2));
   249→        }
   250→        data.template().decodeSlash(RequestLine.class.cast(methodAnnotation).decodeSlash());
   251→        data.template()
   252→            .collectionFormat(RequestLine.class.cast(methodAnnotation).collectionFormat());
   253→
   254→      } else if (annotationType == Body.class) {
   255→        String body = Body.class.cast(methodAnnotation).value();
   256→        checkState(emptyToNull(body) != null, "Body annotation was empty on method %s.",
   257→            method.getName());
   258→        if (body.indexOf('{') == -1) {
   259→          data.template().body(body);
   260→        } else {
   261→          data.template().bodyTemplate(body);
   262→        }
   263→      } else if (annotationType == Headers.class) {
   264→        String[] headersOnMethod = Headers.class.cast(methodAnnotation).value();
   265→        checkState(headersOnMethod.length > 0, "Headers annotation was empty on method %s.",
   266→            method.getName());
   267→        data.template().headers(toMap(headersOnMethod));
   268→      }
   269→    }
   270→
   271→    @Override
   272→    protected boolean processAnnotationsOnParameter(MethodMetadata data,
   273→                                                    Annotation[] annotations,
   274→                                                    int paramIndex) {
   275→      boolean isHttpAnnotation = false;
   276→      for (Annotation annotation : annotations) {
   277→        Class<? extends Annotation> annotationType = annotation.annotationType();
   278→        if (annotationType == Param.class) {
   279→          Param paramAnnotation = (Param) annotation;
   280→          String name = paramAnnotation.value();
   281→          checkState(emptyToNull(name) != null, "Param annotation was empty on param %s.",
   282→              paramIndex);
   283→          nameParam(data, name, paramIndex);
   284→          Class<? extends Param.Expander> expander = paramAnnotation.expander();
   285→          if (expander != Param.ToStringExpander.class) {
   286→            data.indexToExpanderClass().put(paramIndex, expander);
   287→          }
   288→          data.indexToEncoded().put(paramIndex, paramAnnotation.encoded());
   289→          isHttpAnnotation = true;
   290→          if (!data.template().hasRequestVariable(name)) {
   291→            data.formParams().add(name);
   292→          }
   293→        } else if (annotationType == QueryMap.class) {
   294→          checkState(data.queryMapIndex() == null,
   295→              "QueryMap annotation was present on multiple parameters.");
   296→          data.queryMapIndex(paramIndex);
   297→          data.queryMapEncoded(QueryMap.class.cast(annotation).encoded());
   298→          isHttpAnnotation = true;
   299→        } else if (annotationType == HeaderMap.class) {
   300→          checkState(data.headerMapIndex() == null,
   301→              "HeaderMap annotation was present on multiple parameters.");
   302→          data.headerMapIndex(paramIndex);
   303→          isHttpAnnotation = true;
   304→        }
   305→      }
   306→      return isHttpAnnotation;
   307→    }
   308→
   309→    private static Map<String, Collection<String>> toMap(String[] input) {
   310→      Map<String, Collection<String>> result =
   311→          new LinkedHashMap<String, Collection<String>>(input.length);
   312→      for (String header : input) {
   313→        int colon = header.indexOf(':');
   314→        String name = header.substring(0, colon);
   315→        if (!result.containsKey(name)) {
   316→          result.put(name, new ArrayList<String>(1));
   317→        }
   318→        result.get(name).add(header.substring(colon + 1).trim());
   319→      }
   320→      return result;
   321→    }
   322→  }
   323→}
