  path: string,
  params: ?Object,
  routeMsg: string
): string {
  // Normalize asterisk to named parameter to avoid unnamed param issues
  const normalizedPath = path.replace(/\*/g, ':pathMatch(.*)')
  try {
    const filler =
      regexpCompileCache[normalizedPath] ||
      (regexpCompileCache[normalizedPath] = Regexp.compile(normalizedPath))
    return filler(params || {}, { pretty: true })
  } catch (e) {
    if (process.env.NODE_ENV !== 'production') {
      warn(false, `missing param for ${routeMsg}: ${e.message}`)
    }
    return ''
  }
}"}

