const VueRouter = require('./dist/vue-router.common.js')

const routes = [
  { path: '/', name: 'home', component: { name: 'home', template: '<div>Home</div>' }},
  { path: '/prefix/*', name: 'prefixCatchAll', component: { name: 'catchAll', template: '<div>Catch All</div>' }},
  { path: '*', name: 'catchAll', component: { name: 'notFound', template: '<div>Not Found</div>' }}
]

// Mock Vue
global.Vue = {
  mixin: function() {},
  component: function() {},
  config: { optionMergeStrategies: {} },
  util: {
    warn: function() {},
    extend: Object.assign
  }
}

const router = new VueRouter({ routes })

console.log('Testing catch-all routes with prefixes...\n')

// Test 1: Match a prefixed catch-all route
console.log('Test 1: Matching /prefix/foo')
const route1 = router.match('/prefix/foo')
console.log('  Matched path:', route1.matched[0] ? route1.matched[0].path : 'none')
console.log('  Params:', route1.params)
console.log('  Expected params.pathMatch: "foo"')
console.log('  ✓ Pass:', route1.params.pathMatch === 'foo' ? 'YES' : 'NO')

// Test 2: Match a regular catch-all route
console.log('\nTest 2: Matching /not-found')
const route2 = router.match('/not-found')
console.log('  Matched path:', route2.matched[0] ? route2.matched[0].path : 'none')
console.log('  Params:', route2.params)
console.log('  Expected params.pathMatch: "/not-found"')
console.log('  ✓ Pass:', route2.params.pathMatch === '/not-found' ? 'YES' : 'NO')

// Test 3: Resolve a named route with catch-all (this would trigger fillParams)
console.log('\nTest 3: Resolving named route "prefixCatchAll" with params')
try {
  const route3 = router.resolve({ name: 'prefixCatchAll', params: { pathMatch: 'bar/baz' }})
  console.log('  Generated path:', route3.route.path)
  console.log('  Expected path: /prefix/bar/baz')
  console.log('  ✓ Pass:', route3.route.path === '/prefix/bar/baz' ? 'YES' : 'NO')
  console.log('\nNo warnings or errors! Fix is working correctly.')
} catch (e) {
  console.log('  ✗ Error:', e.message)
  console.log('\nFix is NOT working correctly.')
}

console.log('\n✅ All tests completed!')
"}

