    32→function getHLines(parser: Parser): boolean[] {
    33→    // Return an array. The array length = number of hlines.
    34→    // Each element in the array tells if the line is dashed.
    35→    const hlineInfo = [];
    36→    parser.consumeSpaces();
    37→    let nxt = parser.nextToken.text;
    38→    while (nxt === "\\hline" \|\| nxt === "\\hdashline") {
    39→        parser.consume();
    40→        hlineInfo.push(nxt === "\\hdashline");
    41→        parser.consumeSpaces();
    42→        nxt = parser.nextToken.text;
    43→    }
    44→    return hlineInfo;
    45→}
