    47→/**
    48→ * Parse the body of the environment, with rows delimited by \\ and
    49→ * columns delimited by &, and create a nested list in row-major order
    50→ * with one group per cell.  If given an optional argument style
    51→ * ("text", "display", etc.), then each cell is cast into that style.
    52→ */
    53→function parseArray(
    54→    parser: Parser,
    55→    {hskipBeforeAndAfter, addJot, cols, arraystretch, colSeparationType}: {\|
    56→        hskipBeforeAndAfter?: boolean,
    57→        addJot?: boolean,
    58→        cols?: AlignSpec[],
    59→        arraystretch?: number,
    60→        colSeparationType?: ColSeparationType,
