    62→    style: StyleStr,
    63→): ParseNode<"array"> {
    64→    // Parse body of array with \\ temporarily mapped to \cr
    65→    parser.gullet.beginGroup();
    66→    parser.gullet.macros.set("\\\\", "\\cr");
    67→
    68→    // Get current arraystretch if it's not set by the environment
    69→    if (!arraystretch) {
    70→        const stretch = parser.gullet.expandMacroAsText("\\arraystretch");
    71→        if (stretch == null) {
    72→            // Default \arraystretch from lttab.dtx
    73→            arraystretch = 1;
    74→        } else {
    75→            arraystretch = parseFloat(stretch);
    76→            if (!arraystretch \|\| arraystretch < 0) {
    77→                throw new ParseError(`Invalid \\arraystretch: ${stretch}`);
    78→            }
    79→        }
    80→    }
    81→
    82→    // Start group for first cell
    83→    parser.gullet.beginGroup();
    84→
    85→    let row = [];
    86→    const body = [row];
    87→    const rowGaps = [];
    88→    const hLinesBeforeRow = [];
    89→
    90→    // Test for \hline at the top of the array.
    91→    hLinesBeforeRow.push(getHLines(parser));
    92→
    93→    while (true) {  // eslint-disable-line no-constant-condition
    94→        // Parse each cell in its own group (namespace)
