   148→    return {
   149→        type: "array",
   150→        mode: parser.mode,
   151→        addJot,
   152→        arraystretch,
   153→        body,
   154→        cols,
   155→        rowGaps,
   156→        hskipBeforeAndAfter,
   157→        hLinesBeforeRow,
   158→        colSeparationType,
   159→    };
   160→}
