   446→        if (cols[0].type === "separator") {
   447→            menclose += "top ";
   448→            iStart = 1;
   449→        }
   450→        if (cols[cols.length - 1].type === "separator") {
   451→            menclose += "bottom ";
   452→            iEnd -= 1;
   453→        }
   454→
   455→        for (let i = iStart; i < iEnd; i++) {
   456→            if (cols[i].type === "align") {
   457→                align += alignMap[cols[i].align];
   458→
   459→                if (prevTypeWasAlign) {
   460→                    columnLines += "none ";
   461→                }
   462→                prevTypeWasAlign = true;
   463→            } else if (cols[i].type === "separator") {
