    49→        for (const undef in undefs) {
    50→            if (undefs.hasOwnProperty(undef)) {
    51→                if (undefs[undef] === undefined) {
    52→                    delete this.current[undef];
    53→                } else {
    54→                    this.current[undef] = undefs[undef];
