    21→
    22→// immutable atom state
    23→export type AtomState<Value = unknown> = {
    24→  e?: Error // read error
    25→  p?: Promise<void> // read promise
    26→  w?: Promise<void> // write promise
    27→  v?: Value
    28→  r: Revision
    29→  i?: InvalidatedRevision
