    33→type AtomStateMap = WeakMap<AnyAtom, AtomState>
    34→
    35→type Listeners = Set<() => void>
    36→type Dependents = Set<AnyAtom>
    37→type Mounted = {
    38→  l: Listeners
    39→  d: Dependents
    40→  u: OnUnmount | void
    41→}
    42→
    43→type MountedMap = WeakMap<AnyAtom, Mounted>
    44→
    45→export type NewAtomReceiver = (newAtom: AnyAtom) => void
    46→
    47→type StateVersion = number
    48→
    49→type PendingAtoms = Set<AnyAtom>
    50→
    51→// mutable state
    52→export type State = {
    53→  n?: NewAtomReceiver
    54→  v: StateVersion
    55→  a: AtomStateMap
    56→  m: MountedMap
    57→  p: PendingAtoms
    58→}
