    60→export const createState = (
    61→  initialValues?: Iterable<readonly [AnyAtom, unknown]>,
    62→  newAtomReceiver?: NewAtomReceiver
    63→): State => {
    64→  const state: State = {
    65→    n: newAtomReceiver,
    66→    v: 0,
    67→    a: new WeakMap(),
    68→    m: new WeakMap(),
    69→    p: new Set(),
    70→  }
    71→  if (initialValues) {
    72→    for (const [atom, value] of initialValues) {
    73→      const atomState: AtomState = { v: value, r: 0, d: new Map() }
    74→      if (
