    86→const getAtomState = <Value>(state: State, atom: Atom<Value>) =>
    87→  state.a.get(atom) as AtomState<Value> | undefined
    88→
    89→const wipAtomState = <Value>(
    90→  state: State,
    91→  atom: Atom<Value>,
    92→  dependencies?: Set<AnyAtom>
