    94→  const atomState = getAtomState(state, atom)
    95→  const nextAtomState = {
    96→    r: 0,
    97→    ...atomState,
    98→    d: dependencies
    99→      ? new Map(
   100→          Array.from(dependencies).map((a) => [
   101→            a,
   102→            getAtomState(state, a)?.r ?? 0,
   103→          ])
   104→        )
   105→      : atomState
   106→      ? atomState.d
   107→      : new Map(),
